/* MXM Studio - Log de Envios — content script da extensão Firefox (MIT).
   Porte automático a partir do userscript (Tampermonkey) de mesmo nome. */
const mxmStorageCache = Object.create(null);

function GM_getValue(key, defaultValue) {
  if (Object.prototype.hasOwnProperty.call(mxmStorageCache, key)) {
    return mxmStorageCache[key];
  }
  return defaultValue;
}

function GM_setValue(key, value) {
  mxmStorageCache[key] = value;
  const payload = {};
  payload[key] = value;
  browser.storage.local.set(payload).catch((err) => {
    console.warn('[Log de Envios] Falha ao gravar no armazenamento da extensão.', err);
  });
}

// Modo debug: liga os logs de diagnóstico da captura de letra/Diff Check
// no console (normalmente escondidos do usuário comum). Só é ativado por
// um gesto secreto — 5 cliques seguidos no logo do painel de
// Configurações, ver instalarGestoModoDebug()/alternarModoDebug() — nunca
// por um botão visível nas Configurações.
const MXM_LOG_DEBUG_KEY = 'mxm_log_debug_ativo';

function isModoDebugAtivo() {
  return GM_getValue(MXM_LOG_DEBUG_KEY, false) === true;
}

function debugLog(...args) {
  if (!isModoDebugAtivo()) return;
  console.log(...args);
}

function debugWarn(...args) {
  if (!isModoDebugAtivo()) return;
  console.warn(...args);
}

// ---------- simulador de data/hora (debug) ----------
// Guardamos só um OFFSET em ms (diferença entre a data-alvo escolhida e o
// relógio real do dispositivo no momento em que o usuário clicou em
// "Aplicar") em vez de um timestamp fixo — assim o tempo simulado
// continua correndo normalmente daí pra frente (não fica "congelado"),
// igual ao userscript avulso "Time Warp" já usado pra testar isso em
// outros sites. mxmAgora()/mxmAgoraMs() substituem TODO uso de
// `new Date()`/`Date.now()` sem argumento usado pra saber "que horas
// são agora" no resto do arquivo (ciclo de missões, cronômetros, resumo
// do dia, backups automáticos etc.) — chamadas como
// `new Date(algumTimestamp)`, que constroem uma data a partir de um
// valor explícito, não são afetadas e continuam como estavam.
const STORAGE_DEBUG_SIMULACAO_ATIVA_KEY = 'mxm_log_debug_simulacao_ativa';
const STORAGE_DEBUG_SIMULACAO_OFFSET_KEY = 'mxm_log_debug_simulacao_offset_ms';

function isSimulacaoDataAtiva() {
  return GM_getValue(STORAGE_DEBUG_SIMULACAO_ATIVA_KEY, false) === true;
}

function getOffsetSimulacaoData() {
  return Number(GM_getValue(STORAGE_DEBUG_SIMULACAO_OFFSET_KEY, 0)) || 0;
}

// dataAlvo: objeto Date (real) escolhido pelo usuário no campo de debug.
function ativarSimulacaoData(dataAlvo) {
  const offset = dataAlvo.getTime() - Date.now();
  GM_setValue(STORAGE_DEBUG_SIMULACAO_OFFSET_KEY, offset);
  GM_setValue(STORAGE_DEBUG_SIMULACAO_ATIVA_KEY, true);
}

function desativarSimulacaoData() {
  GM_setValue(STORAGE_DEBUG_SIMULACAO_ATIVA_KEY, false);
}

// "Agora", já considerando a simulação de debug quando ativa. Usar isto
// (e mxmAgoraMs()) em vez de `new Date()`/`Date.now()` sem argumento em
// qualquer lugar do arquivo que precise saber a hora atual.
function mxmAgora() {
  if (!isSimulacaoDataAtiva()) return new Date();
  return new Date(Date.now() + getOffsetSimulacaoData());
}

function mxmAgoraMs() {
  return mxmAgora().getTime();
}

// ---------- simulador de tamanho de lista (debug) ----------
// Mesma filosofia do simulador de data acima: NUNCA toca no log real
// (getLogs()/saveLogs()) — guarda só um "modo" separado (off/vazia/uma) e
// quem lê decide, na hora de montar a tela, se substitui as entradas de
// exibição por um cenário fake. O storage de verdade (GM_getValue(
// STORAGE_KEY)) nunca é lido nem escrito por nada aqui — só serve pra
// testar rapidamente os estados "log vazio" e "lista com 1 música" (ex:
// o bug do marcador "Fim da lista"/dicas de lista curta) sem precisar
// apagar de verdade o histórico de quem está testando.
const STORAGE_DEBUG_SIMULACAO_LISTA_KEY = 'mxm_log_debug_simulacao_lista_modo';

// 'off' (padrão) | 'vazia' | 'uma'
function getModoSimulacaoLista() {
  const modo = GM_getValue(STORAGE_DEBUG_SIMULACAO_LISTA_KEY, 'off');
  return modo === 'vazia' || modo === 'uma' ? modo : 'off';
}

function setModoSimulacaoLista(modo) {
  GM_setValue(STORAGE_DEBUG_SIMULACAO_LISTA_KEY, modo === 'vazia' || modo === 'uma' ? modo : 'off');
}

function isSimulacaoListaAtiva() {
  return getModoSimulacaoLista() !== 'off';
}

async function mxmLoadStorage() {
  const stored = await browser.storage.local.get(null);
  if (stored && typeof stored === 'object') {
    Object.assign(mxmStorageCache, stored);
  }
}

browser.storage.onChanged.addListener((changes, area) => {
  if (area !== 'local') return;
  for (const [key, change] of Object.entries(changes)) {
    if (!change || change.newValue === undefined) {
      delete mxmStorageCache[key];
    } else {
      mxmStorageCache[key] = change.newValue;
    }
  }
});


