  // link "Ver código-fonte no GitHub" na janela "Sobre" (ver
  // abrirJanelaSobre), diferente de GITHUB_RELEASES_PAGE_URL acima (que
  // aponta direto pra aba de Releases/.xpi).
  const GITHUB_REPO_PAGE_URL = `https://github.com/${GITHUB_REPO_OWNER}/${GITHUB_REPO_NAME}`;

  async function buscarXpiGithub(versao) {
    const tag = `v${versao}`;
    const url = `https://api.github.com/repos/${GITHUB_REPO_OWNER}/${GITHUB_REPO_NAME}/releases/tags/${encodeURIComponent(
      tag
    )}`;
    try {
      const res = await fetch(url, { headers: { Accept: 'application/vnd.github+json' }, cache: 'no-store' });
      if (res.status === 404) return { ok: false, motivo: 'sem_release_github' };
      if (!res.ok) return { ok: false, motivo: 'erro_github' };
      const dados = await res.json();
      const asset = (dados.assets || []).find(
        (a) => a && typeof a.name === 'string' && a.name.toLowerCase().endsWith('.xpi')
      );
      if (!asset) return { ok: false, motivo: 'sem_release_github' };
      return { ok: true, url: asset.browser_download_url };
    } catch (erro) {
      return { ok: false, motivo: 'erro_github' };
    }
  }

  // Contrato compatível com criarRetryAtualizacao (e com o antigo
  // aplicarAtualizacaoAgora): devolve { aplicada: true } quando conseguiu
  // abrir o .xpi, ou { aplicada: false, motivo } quando ainda não achou —
  // aí quem chamou decide se tenta de novo sozinho.
  function tentarAtualizarViaGithub(callback) {
    const versao = getUpdateDisponivel();
    if (!versao) {
      callback({ ok: true, aplicada: false, motivo: 'sem_release_github' });
      return;
    }
    buscarXpiGithub(versao).then((resultado) => {
      if (resultado.ok) {
        window.open(resultado.url, '_blank', 'noopener');
        callback({ ok: true, aplicada: true });
      } else {
        callback({ ok: true, aplicada: false, motivo: resultado.motivo });
      }
    });
  }

  // página do addon "Musixmatch Studio - Total USD + BRL" no AMO (Firefox) —
  // usada no aviso da aba Reward pra dar um link direto de instalação
  // quando essa extensão não está instalada/ativa.
  const TOTAL_USD_BRL_SCRIPT_URL = 'https://addons.mozilla.org/pt-BR/firefox/addon/mxm-reward-count/';

  // ---------- aba "Reward" (reaproveitado do script "Total USD + BRL") ----------

  // Mesma tabela fixa de taxas por missão do script "Total USD + BRL" — em
  // vez de tentar ler "Reward: X USD" do DOM (que só existe na página da
  // missão em si, não faz sentido pra um histórico de envios já registrados),
  // a taxa de cada missão conhecida fica fixa aqui. Missão que não estiver
  // na lista cai pro valor padrão (FALLBACK_REWARD_RATE), marcado como
  // "taxa estimada" na interface.
  const FALLBACK_REWARD_RATE = 0.5;
  const MISSION_REWARD_RATES = {
    'QA on Automatic Transcription': 0.5,
    'Russian Content Mission': 0.5,
    'The Jukebox': 0.5,
    'Top Weekly Amazon Music': 1,
    'Top Weekly iHeart': 0.5,
    'Top Weekly Saregama': 1,
    'Top Weekly Spotify': 0.5,
    'Weekly Musixmatch Artists Special': 2,
    'Weekly YouTube': 0.5,
  };

  // ✅ Moeda secundária: em vez de sempre converter pra BRL, agora lê a
  // mesma preferência que o usuário já escolheu no widget "Total USD + BRL"
  // (localStorage, mesma origem/página — sem ponte nem mensagem entre
  // scripts). CURRENCY_META e FALLBACK_RATES são cópias exatas das tabelas
  // do widget, pra qualquer moeda escolhida lá (BRL/EUR/GBP/ARS/JPY/CHF/
  // CAD/AUD) ter símbolo/bandeira/valor de emergência aqui também.
  const SECONDARY_CURRENCY_KEY = 'mxm_widget_secondary_currency';
  const CURRENCY_META = {
    USD: { symbol: '$', flag: 'us', label: 'USD' },
    BRL: { symbol: 'R$', flag: 'br', label: 'BRL' },
    EUR: { symbol: '€', flag: 'eu', label: 'EUR' },
    GBP: { symbol: '£', flag: 'gb', label: 'GBP' },
    ARS: { symbol: 'AR$', flag: 'ar', label: 'ARS' },
    JPY: { symbol: '¥', flag: 'jp', label: 'JPY' },
    CHF: { symbol: 'CHF ', flag: 'ch', label: 'CHF' },
    CAD: { symbol: 'CA$', flag: 'ca', label: 'CAD' },
    AUD: { symbol: 'AU$', flag: 'au', label: 'AUD' },
  };
  const FALLBACK_RATES = {
    BRL: 5.2, EUR: 0.92, GBP: 0.79, ARS: 1180, JPY: 152, CHF: 0.87, CAD: 1.37, AUD: 1.53,
  };

  // Mesmas fontes de cotação do widget: AwesomeAPI (principal, pares
  // "MOEDA-BRL") com Frankfurter/BCE como plano B (não cobre ARS).
  const FX_API_BASE = 'https://economia.awesomeapi.com.br/json/last/';
  const FX_FALLBACK_API_BASE = 'https://api.frankfurter.dev/v1/latest';
  const FX_FALLBACK_UNSUPPORTED = ['ARS'];
  const FX_TIMEOUT_MS = 2500;

  // Lê a moeda secundária escolhida pelo usuário no widget "Total USD +
  // BRL". Se o widget nunca rodou nessa máquina (chave ausente) ou o valor
  // salvo não é uma moeda conhecida, cai pra BRL (comportamento de sempre).
  function getSecondaryCurrencyCode() {
    try {
      const salvo = localStorage.getItem(SECONDARY_CURRENCY_KEY);
      if (salvo && Object.prototype.hasOwnProperty.call(CURRENCY_META, salvo)) return salvo;
    } catch (e) {}
    return 'BRL';
  }

  // Símbolo de exibição de uma moeda (ex: 'R$', '€', 'AR$'). Cai pro
  // símbolo de BRL se o código não for conhecido (nunca deveria acontecer,
  // já que getSecondaryCurrencyCode() só devolve códigos válidos).
  function simboloMoeda(codigo) {
    return (CURRENCY_META[codigo] || CURRENCY_META.BRL).symbol;
  }

  // Cada moeda tem sua própria convenção de separador decimal (BRL/EUR/ARS
  // usam vírgula, USD/GBP/JPY usam ponto) — .toFixed(2) sempre devolve
  // ponto, o que fica errado pra quem lê em português. Usamos Intl aqui
  // pra formatar cada valor do jeito que o falante daquela moeda espera,
  // mantendo o símbolo próprio da tabela CURRENCY_META (que já não segue
  // o padrão ISO em alguns casos, ex.: "AR$", "CA$").
  const CURRENCY_LOCALE = {
    USD: 'en-US', BRL: 'pt-BR', EUR: 'de-DE', GBP: 'en-GB',
    ARS: 'es-AR', JPY: 'ja-JP', CHF: 'de-CH', CAD: 'en-CA', AUD: 'en-AU',
  };
  function formatarNumeroMoeda(valor, codigo, casasDecimais) {
    const locale = CURRENCY_LOCALE[codigo] || 'en-US';
    const casas = casasDecimais != null ? casasDecimais : codigo === 'JPY' ? 0 : 2;
    try {
      return new Intl.NumberFormat(locale, {
        minimumFractionDigits: casas,
        maximumFractionDigits: casas,
      }).format(valor);
    } catch (e) {
      return Number(valor || 0).toFixed(casas);
    }
  }

  // Código da moeda usada num resumo mensal já salvo. Resumos salvos antes
  // dessa sincronização com o widget não têm o campo `moeda` — assume-se
  // BRL pra eles, que era o comportamento fixo da época.
  function moedaDoResumo(resumo) {
    return (resumo && resumo.moeda) || 'BRL';
  }

  let usdToSecondary = FALLBACK_RATES.BRL;
  let secondaryCurrencyDaCotacao = 'BRL'; // pra qual moeda usdToSecondary foi calculada por último
  let fxUpdatedAt = 0;
  let fxCarregando = false;

  // ---------- histórico de cotação (mini-gráfico no card "Total ganho") ----------

  // Mesmo provedor (AwesomeAPI) usado pra cotação ao vivo, só que no
  // endpoint de fechamentos diários — evita depender de uma fonte nova.
  const FX_HISTORY_API_BASE = 'https://economia.awesomeapi.com.br/json/daily/';
  const FX_HISTORY_DIAS = 7;
  const FX_HISTORY_CACHE_PREFIX = 'mxm_log_fx_historico_';
  const FX_HISTORY_CACHE_TTL_MS = 6 * 60 * 60 * 1000; // 6h — histórico diário não precisa recarregar toda hora

  let fxHistorico = null; // { moeda, pontos: [{ts, rate}, ...] (ordem cronológica) }
  let fxHistoricoCarregando = false;

  function chaveCacheHistorico(moeda) {
    return `${FX_HISTORY_CACHE_PREFIX}${moeda}`;
  }

  function lerHistoricoDoCache(moeda) {
    try {
      const bruto = localStorage.getItem(chaveCacheHistorico(moeda));
      if (!bruto) return null;
      const dados = JSON.parse(bruto);
      if (!dados || !Array.isArray(dados.pontos) || !dados.pontos.length) return null;
      if (mxmAgoraMs() - (dados.fetchedAt || 0) > FX_HISTORY_CACHE_TTL_MS) return null;
      return dados;
    } catch (e) {
      return null;
    }
  }

  function salvarHistoricoNoCache(moeda, pontos) {
    try {
      localStorage.setItem(chaveCacheHistorico(moeda), JSON.stringify({ moeda, pontos, fetchedAt: mxmAgoraMs() }));
    } catch (e) {}
  }

  // Busca os N últimos fechamentos diários de um par MOEDA-BRL na
  // AwesomeAPI. Devolve em ordem cronológica (mais antigo primeiro) —
  // a API entrega mais recente primeiro.
  async function fetchFechamentosDiarios(par, dias) {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), FX_TIMEOUT_MS);
    try {
      const url = `${FX_HISTORY_API_BASE}${par}/${dias}?_=${mxmAgoraMs()}`;
      const res = await fetch(url, { signal: controller.signal, cache: 'no-store' });
      if (!res.ok) throw new Error('HTTP ' + res.status);
      const data = await res.json();
      if (!Array.isArray(data) || !data.length) throw new Error('resposta vazia');
      return data
        .map((item) => ({ ts: parseInt(item.timestamp, 10) * 1000, bid: parseFloat(item.bid) }))
        .filter((item) => Number.isFinite(item.ts) && Number.isFinite(item.bid) && item.bid > 0)
        .sort((a, b) => a.ts - b.ts);
    } finally {
      clearTimeout(timeoutId);
    }
  }

  // Monta o histórico de USD→moeda secundária dos últimos N dias, com a
  // mesma lógica de par cruzado (via BRL) usada na cotação ao vivo em
  // fetchPrimaryRate. Silencioso em qualquer falha — o card simplesmente
  // não mostra o mini-gráfico até a próxima tentativa.
  async function fetchHistoricoFx(moeda, dias) {
    const isBrl = moeda === 'BRL';
    if (isBrl) {
      const usdBrl = await fetchFechamentosDiarios('USD-BRL', dias);
      return usdBrl.map((p) => ({ ts: p.ts, rate: p.bid }));
    }
    const [usdBrl, secBrl] = await Promise.all([
      fetchFechamentosDiarios('USD-BRL', dias),
      fetchFechamentosDiarios(`${moeda}-BRL`, dias),
    ]);
    const n = Math.min(usdBrl.length, secBrl.length);
    if (!n) throw new Error('sem pontos em comum');
    const pontos = [];
    for (let i = 0; i < n; i++) {
      const a = usdBrl[usdBrl.length - n + i];
      const b = secBrl[secBrl.length - n + i];
      pontos.push({ ts: a.ts, rate: a.bid / b.bid });
    }
    return pontos;
  }

  // Garante que fxHistorico está carregado e é da moeda certa — busca em
  // segundo plano (sem travar o render) e usa cache local de 6h pra não
  // bater na API toda vez que o painel reabre.
  function garantirHistoricoFxAtualizado() {
    const moeda = getSecondaryCurrencyCode();
    if (fxHistoricoCarregando) return;
    if (fxHistorico && fxHistorico.moeda === moeda) return;

    const doCache = lerHistoricoDoCache(moeda);
    if (doCache) {
      fxHistorico = { moeda, pontos: doCache.pontos };
      return;
    }

    fxHistoricoCarregando = true;
    fetchHistoricoFx(moeda, FX_HISTORY_DIAS)
      .then((pontos) => {
        if (!pontos.length) return;
        fxHistorico = { moeda, pontos };
        salvarHistoricoNoCache(moeda, pontos);
        if (document.getElementById('mxm-log-reward-conteudo')) renderPainelReward();
      })
      .catch(() => {})
      .finally(() => {
        fxHistoricoCarregando = false;
      });
  }

  // Monta o SVG do mini-gráfico (linha + preenchimento em degradê) a
  // partir dos pontos do histórico. `corBase` é a cor da linha/gradiente —
  // verde se a moeda valorizou frente ao USD no período, vermelho se
  // desvalorizou, pra dar uma leitura rápida sem precisar de eixo/legenda.
  // width="100%" + viewBox fixo faz o traçado esticar pra largura real do
  // card (responsivo), sem precisar saber o tamanho em pixels de antemão.
  function montarSvgHistoricoFx(pontos, viewBoxLargura, altura) {
    if (!pontos || pontos.length < 2) return '';
    const valores = pontos.map((p) => p.rate);
    const min = Math.min(...valores);
    const max = Math.max(...valores);
    const amplitude = max - min || max * 0.001 || 1;
    const padTopo = 6;
    const padBase = 4;
    const alturaUtil = altura - padTopo - padBase;

    const subiu = valores[valores.length - 1] >= valores[0];
    const corBase = subiu ? '#1DB954' : '#f2555a';
    const gradId = `mxm-fx-hist-grad-${Math.random().toString(36).slice(2, 8)}`;

    const coords = pontos.map((p, i) => {
      const x = pontos.length > 1 ? (i / (pontos.length - 1)) * viewBoxLargura : 0;
      const y = padTopo + alturaUtil - ((p.rate - min) / amplitude) * alturaUtil;
      return [x, y];
    });

    const linhaD = coords.map(([x, y], i) => `${i === 0 ? 'M' : 'L'}${x.toFixed(1)},${y.toFixed(1)}`).join(' ');
    const areaD = `${linhaD} L${viewBoxLargura.toFixed(1)},${altura} L0,${altura} Z`;

    return `
      <svg width="100%" height="${altura}" viewBox="0 0 ${viewBoxLargura} ${altura}" preserveAspectRatio="none" style="display:block; overflow:visible;">
        <defs>
          <linearGradient id="${gradId}" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stop-color="${corBase}" stop-opacity="0.4" />
            <stop offset="100%" stop-color="${corBase}" stop-opacity="0" />
          </linearGradient>
        </defs>
        <path d="${areaD}" fill="url(#${gradId})" stroke="none" />
        <path d="${linhaD}" fill="none" stroke="${corBase}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke" />
        <circle cx="${coords[coords.length - 1][0].toFixed(1)}" cy="${coords[coords.length - 1][1].toFixed(1)}" r="2.6" fill="${corBase}" />
      </svg>
    `;
  }

  // HTML do pill do histórico — mini-gráfico compacto dentro de um pill
  // Tabs V3 semitransparente, pra ficar ao lado do badge "Ao vivo"
  // (não mais uma faixa esticada ocupando a largura toda). Some (retorna
  // '') enquanto não há dados prontos, sem placeholder piscando.
  function montarBlocoHistoricoFxHtml(moeda) {
    if (!fxHistorico || fxHistorico.moeda !== moeda || fxHistorico.pontos.length < 2) return '';
    const pontos = fxHistorico.pontos;
    const svg = montarSvgHistoricoFx(pontos, 110, 26);
    if (!svg) return '';

    const variacaoPct = ((pontos[pontos.length - 1].rate - pontos[0].rate) / pontos[0].rate) * 100;
    const variacaoTexto = `${variacaoPct >= 0 ? '+' : ''}${variacaoPct.toFixed(2)}%`;
    const corVariacao = variacaoPct >= 0 ? '#1DB954' : '#f2555a';
    const periodoTexto = t('historicoDias').replace('{dias}', FX_HISTORY_DIAS);
    const titulo = `USD/${moeda} — ${periodoTexto}: ${variacaoTexto}`;

    return `
      <div title="${escapeHtml(titulo)}" style="display:flex; align-items:center; justify-content:center; gap:8px;">
        <div style="width:110px;">${svg}</div>
        <span style="font-size:10.5px; font-weight:700; color:${corVariacao}; white-space:nowrap;">${variacaoTexto}</span>
      </div>
    `;
  }

  // Normaliza o nome de uma missão pra comparar com a tabela fixa: remove
  // "(Curators)" (não importa a posição), colapsa espaços e ignora
  // maiúsculas/minúsculas — mesma lógica do "Total USD + BRL".
  function normalizeMissionLabelForLookup(label) {
    if (!label) return '';
    return label
      .replace(/\(curators\)/gi, '')
      .replace(/\s+/g, ' ')
      .trim()
      .toLowerCase();
  }

  const MISSION_REWARD_RATES_NORMALIZED = Object.entries(MISSION_REWARD_RATES).reduce((acc, [label, rate]) => {
    acc[normalizeMissionLabelForLookup(label)] = rate;
    return acc;
  }, {});

  // Consulta a tabela fixa pelo nome da missão. Retorna null se a missão
  // não estiver cadastrada (quem chamou decide usar o valor padrão).
  function getKnownMissionRate(missionLabel) {
    const key = normalizeMissionLabelForLookup(missionLabel);
    if (key && Object.prototype.hasOwnProperty.call(MISSION_REWARD_RATES_NORMALIZED, key)) {
      return MISSION_REWARD_RATES_NORMALIZED[key];
    }
    return null;
  }

  const WIDGET_MISSION_BLACKLIST_KEY = 'mxm_widget_mission_blacklist';
  const WIDGET_MISSION_DEDUCTIONS_KEY = 'mxm_widget_mission_deductions';

  function loadWidgetMissionBlacklist() {
    try {
      const raw = localStorage.getItem(WIDGET_MISSION_BLACKLIST_KEY);
      const arr = raw ? JSON.parse(raw) : [];
      return Array.isArray(arr) ? arr.filter((e) => e && e.key) : [];
    } catch (e) {
      return [];
    }
  }

  // Aceita tanto o "missionId" cru quanto um rótulo já normalizado — usa o
  // mesmo critério de comparação do widget (normalizeMissionLabelForLookup),
  // então "Weekly YouTube" e "Weekly YouTube (Curators)" batem com a mesma
  // entrada da lista negra.
  function isMissionBlacklistedByWidget(missionLabel) {
    const key = normalizeMissionLabelForLookup(missionLabel);
    if (!key) return false;
    return loadWidgetMissionBlacklist().some((e) => e.key === key);
  }

  function loadWidgetMissionDeductions() {
    try {
      const raw = localStorage.getItem(WIDGET_MISSION_DEDUCTIONS_KEY);
      const arr = raw ? JSON.parse(raw) : [];
      return Array.isArray(arr)
        ? arr.filter((e) => e && e.key && Number.isFinite(parseFloat(e.amount)) && parseFloat(e.amount) > 0)
        : [];
    } catch (e) {
      return [];
    }
  }

  function getWidgetMissionDeduction(missionLabel) {
    const key = normalizeMissionLabelForLookup(missionLabel);
    if (!key) return 0;
    const entry = loadWidgetMissionDeductions().find((e) => e.key === key);
    return entry ? parseFloat(entry.amount) || 0 : 0;
  }

  // Aplica o desconto manual daquela missão (se houver) a um valor USD
  // bruto, nunca deixando o resultado negativo — mesmo critério do widget
  // (applyMissionDeduction nele). Usado tanto pelo cálculo interno
  // (calcularRecompensas) quanto pelo retrato lido ao vivo do widget
  // (lerDadosWidgetTotalUsdBrl), pra sempre bater com o que o próprio
  // widget mostra na aba dele.
  function aplicarDescontoWidget(missionLabel, usdBruto) {
    if (!Number.isFinite(usdBruto)) return usdBruto;
    const desconto = getWidgetMissionDeduction(missionLabel);
    if (!desconto) return usdBruto;
    return Math.max(0, usdBruto - desconto);
  }

  // Busca na AwesomeAPI a cotação USD→moeda escolhida (mesma lógica do
  // widget "Total USD + BRL": a API só tem pares "MOEDA-BRL", então quando
  // a moeda não é BRL busca os dois pares numa chamada só e calcula a taxa
  // cruzada usando o BRL como intermediário).
  async function fetchPrimaryRate(moeda) {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), FX_TIMEOUT_MS);
    try {
      const isBrl = moeda === 'BRL';
      const pairs = isBrl ? 'USD-BRL' : `USD-BRL,${moeda}-BRL`;
      const url = `${FX_API_BASE}${pairs}?_=${mxmAgoraMs()}`;
      const res = await fetch(url, { signal: controller.signal, cache: 'no-store' });
      if (!res.ok) throw new Error('HTTP ' + res.status);
      const data = await res.json();
      const usdBrlBid = parseFloat(data && data.USDBRL && data.USDBRL.bid);
      if (!Number.isFinite(usdBrlBid) || usdBrlBid <= 0) throw new Error('bid USD-BRL inválido');
      let rate = usdBrlBid;
      if (!isBrl) {
        const secBid = parseFloat(data && data[moeda + 'BRL'] && data[moeda + 'BRL'].bid);
        if (!Number.isFinite(secBid) || secBid <= 0) throw new Error('bid secundário inválido');
        rate = usdBrlBid / secBid;
      }
      return rate;
    } finally {
      clearTimeout(timeoutId);
    }
  }

  // Plano B (Frankfurter/BCE), só chamado se a AwesomeAPI falhar; não
  // existe pra ARS.
  async function fetchFallbackRate(moeda) {
    if (FX_FALLBACK_UNSUPPORTED.includes(moeda)) throw new Error('moeda sem fonte secundária disponível');
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), FX_TIMEOUT_MS);
    try {
      const url = `${FX_FALLBACK_API_BASE}?from=USD&to=${moeda}&_=${mxmAgoraMs()}`;
      const res = await fetch(url, { signal: controller.signal, cache: 'no-store' });
      if (!res.ok) throw new Error('HTTP ' + res.status);
      const data = await res.json();
      const rate = parseFloat(data && data.rates && data.rates[moeda]);
      if (!Number.isFinite(rate) || rate <= 0) throw new Error('taxa da fonte secundária inválida');
      return rate;
    } finally {
      clearTimeout(timeoutId);
    }
  }

  // Busca a cotação USD→(moeda secundária escolhida no widget). Se a moeda
  // mudou desde a última busca, descarta o valor de emergência antigo e
  // parte de um fallback aproximado pra essa moeda nova até a API responder.
  // Falha silenciosamente e mantém o último valor conhecido — nunca trava a
  // interface por causa disso.
  async function fetchUsdBrl() {
    const moeda = getSecondaryCurrencyCode();
    if (moeda !== secondaryCurrencyDaCotacao) {
      usdToSecondary = FALLBACK_RATES[moeda] || FALLBACK_RATES.BRL;
      secondaryCurrencyDaCotacao = moeda;
    }
    fxCarregando = true;
    try {
      usdToSecondary = await fetchPrimaryRate(moeda);
      fxUpdatedAt = mxmAgoraMs();
    } catch (ePrimary) {
      try {
        usdToSecondary = await fetchFallbackRate(moeda);
        fxUpdatedAt = mxmAgoraMs();
      } catch (eFallback) {
        // as duas fontes falharam — mantém o último valor bom conhecido
      }
    } finally {
      fxCarregando = false;
    }
  }

  // Agrupa as entradas do log por missão e calcula o total em USD/BRL usando
  // a tabela fixa de taxas (ou o valor padrão pra missões desconhecidas).
  // Conta uma tarefa por registro do log (não por tentativa/reenvio — reenviar
  // a letra de uma faixa já enviada não gera uma segunda recompensa).
  function calcularRecompensas(entradas) {
    const porMissao = {};

    entradas.forEach((e) => {
      const nomeMissao = e.missao || t('semMissaoIdentificada');
      if (isMissionBlacklistedByWidget(nomeMissao)) return;
      if (!porMissao[nomeMissao]) {
        const taxaConhecida = e.missao ? getKnownMissionRate(e.missao) : null;
        porMissao[nomeMissao] = {
          missao: nomeMissao,
          count: 0,
          rate: taxaConhecida !== null ? taxaConhecida : FALLBACK_REWARD_RATE,
          estimada: taxaConhecida === null,
        };
      }
      porMissao[nomeMissao].count++;
    });

    const breakdown = Object.values(porMissao)
      .map((item) => {
        const deducao = getWidgetMissionDeduction(item.missao);
        return { ...item, usd: aplicarDescontoWidget(item.missao, item.count * item.rate), deducao };
      })
      .sort((a, b) => b.usd - a.usd);

    const totalUSD = breakdown.reduce((soma, item) => soma + item.usd, 0);
    const moeda = getSecondaryCurrencyCode();
    const totalBRL = totalUSD * usdToSecondary;
    const totalCount = breakdown.reduce((soma, item) => soma + item.count, 0);

    return { breakdown, totalUSD, totalBRL, totalCount, moeda };
  }

  // Chave EXATA usada pelo script "Musixmatch - Total USD + BRL"
  // (MISSION_TOTALS_KEY nele) pra salvar o retrato de cada missão no
  // localStorage. Como os dois scripts rodam na mesma página/origem, o
  // Log de Envios consegue ler esses dados direto — sem nenhuma ponte ou
  // mensagem entre scripts, só a mesma chave de storage.
  const MXM_WIDGET_TOTALS_KEY = 'mxm_widget_mission_totals';

  const WIDGET_HEARTBEAT_KEY = 'mxm_widget_heartbeat';
  const WIDGET_HEARTBEAT_TIMEOUT_MS = 8000;

  // Converte um valor (pode vir como timestamp numérico ou string) num
  // número de ms desde epoch. Retorna NaN se não der pra interpretar.
  function paraTimestamp(valor) {
    if (valor === null || valor === undefined) return NaN;
    if (typeof valor === 'number') return valor;
    const comoNumero = Number(valor);
    if (Number.isFinite(comoNumero)) return comoNumero;
    const comoData = Date.parse(valor);
    return Number.isFinite(comoData) ? comoData : NaN;
  }

  function widgetTotalUsdBrlEstaAtivo() {
    try {
      const raw = localStorage.getItem(WIDGET_HEARTBEAT_KEY);
      if (!raw) return false;
      const ts = paraTimestamp(raw);
      if (!Number.isFinite(ts)) return false;
      return mxmAgoraMs() - ts <= WIDGET_HEARTBEAT_TIMEOUT_MS;
    } catch (e) {
      return false;
    }
  }

  function lerDadosWidgetTotalUsdBrl() {
    if (!widgetTotalUsdBrlEstaAtivo()) return null;

    try {
      const raw = localStorage.getItem(MXM_WIDGET_TOTALS_KEY);
      if (!raw) return null;
      const totals = JSON.parse(raw);
      if (!totals || typeof totals !== 'object') return null;

      const breakdown = Object.entries(totals)
        .map(([missionId, entry]) => {
          const usd = parseFloat(entry && entry.usd);
          if (!Number.isFinite(usd)) return null;
          const missao = (entry && entry.label) || missionId;
          if (isMissionBlacklistedByWidget(missao)) return null;
          const count = parseInt(entry && entry.count, 10);
          const rate = parseFloat(entry && entry.rate);
          const deducao = getWidgetMissionDeduction(missao);
          return {
            missao,
            count: Number.isFinite(count) ? count : 0,
            rate: Number.isFinite(rate) ? rate : null,
            usd: aplicarDescontoWidget(missao, usd),
            deducao,
            updatedAt: (entry && entry.updatedAt) || null,
            estimada: false, // vem direto do widget, não é um "chute" nosso
          };
        })
        .filter(Boolean)
        .sort((a, b) => b.usd - a.usd);

      if (breakdown.length === 0) return null;

      const totalUSD = breakdown.reduce((soma, item) => soma + item.usd, 0);
      const moeda = getSecondaryCurrencyCode();
      const totalBRL = totalUSD * usdToSecondary;
      const totalCount = breakdown.reduce((soma, item) => soma + item.count, 0);

      return { breakdown, totalUSD, totalBRL, totalCount, moeda, origem: 'widget' };
    } catch (e) {
      return null;
    }
  }

  // Se a moeda secundária escolhida no widget mudou desde a última cotação
  // buscada, dispara uma nova busca em segundo plano (sem bloquear quem
  // chamou) — assim qualquer ponto que use obterDadosReward (painel Reward,
  // resumo do mês, popup de fim de mês, carrossel de slides) se autocorrige
  // na próxima vez que renderizar, mesmo fora do painel Reward aberto.
  function garantirCotacaoAtualizada() {
    if (fxCarregando) return;
    if (getSecondaryCurrencyCode() !== secondaryCurrencyDaCotacao) fetchUsdBrl();
  }

  // Ponto único usado pelo painel: prioriza os dados reais do widget "Total
  // USD + BRL" e só recorre ao cálculo interno (a partir do próprio log)
  // como reserva.
  function obterDadosReward(entradasLog) {
    garantirCotacaoAtualizada();
    const doWidget = lerDadosWidgetTotalUsdBrl();
    if (doWidget) return doWidget;
    return { ...calcularRecompensas(entradasLog), origem: 'log' };
  }


  // Seletores da linha de faixa na lista de tasks (mesmo padrão usado no
  // script "Suite" pra localizar as linhas clicáveis da listagem).
  const ROW_SELECTOR = 'div.r-16y2uox.r-dd0y9b';
  const PRIMARY_TEXT_SEL = 'div[dir="auto"][style*="--mxm-contentPrimary"]';
