  // Chave do ciclo a que uma ENTRADA do log pertence, pelo timestamp real
  // do primeiro envio (mais confiável que reconstruir a partir da string
  // de data/hora exibida). Entradas antigas sem timestamp numérico válido
  // devolvem null — quem chama decide o fallback (mantém o comportamento
  // anterior pra não reclassificar dado histórico às cegas).
  function chaveCicloDaEntrada(entrada) {
    if (!entrada || !Number.isFinite(entrada.timestamp)) return null;
    return chaveMesAno(dataEfetivaParaCiclo(new Date(entrada.timestamp)));
  }

  // ---------- nomes customizados por ciclo (tela "Ciclos", ver abrirPainelCiclos) ----------
  // Guardados por chave de ciclo (mesmo formato "MM/AAAA" de chaveMesAno),
  // então sobrevivem à troca de ano/mês sem precisar reindexar nada.

  function getNomesCiclos() {
    try {
      const raw = localStorage.getItem(STORAGE_NOMES_CICLOS_KEY);
      const obj = raw ? JSON.parse(raw) : {};
      return obj && typeof obj === 'object' ? obj : {};
    } catch (e) {
      return {};
    }
  }

  function getNomeCiclo(mesAnoChave, numeroCiclo) {
    const nomes = getNomesCiclos();
    const custom = nomes[mesAnoChave];
    if (custom && custom.trim()) return custom.trim();
    return `${t('cicloNumeroPadraoPrefixo')} ${numeroCiclo}`;
  }

  function setNomeCiclo(mesAnoChave, nome) {
    const nomes = getNomesCiclos();
    const limpo = (nome || '').trim();
    if (limpo) nomes[mesAnoChave] = limpo;
    else delete nomes[mesAnoChave]; // string vazia = volta ao nome padrão
    try {
      localStorage.setItem(STORAGE_NOMES_CICLOS_KEY, JSON.stringify(nomes));
    } catch (e) {
      // localStorage indisponível/cheio — falha silenciosa, mesmo padrão
      // de outras funções de storage neste arquivo.
    }
  }

  function entradasDoMes(entradas, mesAnoChave) {
    return (entradas || []).filter((e) => {
      const chaveCiclo = chaveCicloDaEntrada(e);
      if (chaveCiclo) return chaveCiclo === mesAnoChave;
      // Fallback pra entradas sem timestamp confiável (dado bem antigo):
      // comportamento de antes, calendário puro a partir de e.data.
      const partes = (e.data || '').split('/');
      if (partes.length !== 3) return false;
      return `${partes[1]}/${partes[2]}` === mesAnoChave;
    });
  }

  function coletarCapasDoMes(entradas) {
    const vistas = new Set();
    const capas = [];
    for (const e of entradas) {
      const url = e.imagemUrl;
      if (!url || vistas.has(url)) continue;
      vistas.add(url);
      capas.push(url);
      if (capas.length >= 24) break;
    }
    return capas;
  }

  function coletarTitulosDoMes(entradas) {
    const vistos = new Set();
    const titulos = [];
    for (const e of entradas) {
      const nome = nomeMusicaResumo(e);
      if (!nome || nome === '?' || vistos.has(nome)) continue;
      vistos.add(nome);
      titulos.push(nome);
      if (titulos.length >= 30) break;
    }
    return titulos;
  }

  function calcularDetalhesResumoMes(entradas) {
    function resumoMusica(e) {
      if (!e) return null;
      return { titulo: e.titulo || '', artista: e.artista || '', duracaoSegundos: e.duracaoSegundos, imagemUrl: e.imagemUrl || null };
    }
    function resumoLetra(e, tamanho) {
      if (!e) return null;
      // guarda também o texto bruto da letra (antes só o tamanho
      // era salvo) — usado no fundo de "texto se escrevendo" do slide
      // correspondente do carrossel (ver montarFundoTextoEscrevendo).
      return { titulo: e.titulo || '', artista: e.artista || '', tamanho, imagemUrl: e.imagemUrl || null, texto: (e.letra || '').trim() };
    }

    let musicaMaisLonga = null;
    let musicaMaisCurta = null;
    entradas.forEach((e) => {
      if (!Number.isFinite(e.duracaoSegundos)) return;
      if (!musicaMaisCurta || e.duracaoSegundos < musicaMaisCurta.duracaoSegundos) musicaMaisCurta = e;
      if (!musicaMaisLonga || e.duracaoSegundos > musicaMaisLonga.duracaoSegundos) musicaMaisLonga = e;
    });

    let letraMaisLonga = null;
    let letraMaisCurta = null;
    let tamanhoMaisLonga = 0;
    let tamanhoMaisCurta = Infinity;
    entradas.forEach((e) => {
      const texto = (e.letra || '').trim();
      if (!texto) return;
      const tamanho = texto.length;
      if (tamanho > tamanhoMaisLonga) {
        tamanhoMaisLonga = tamanho;
        letraMaisLonga = e;
      }
      if (tamanho < tamanhoMaisCurta) {
        tamanhoMaisCurta = tamanho;
        letraMaisCurta = e;
      }
    });

    let totalInstrumentais = 0;
    const porMissao = {};
    const musicasPorMissao = {};
    entradas.forEach((e) => {
      if (e.tipo === 'instrumental') totalInstrumentais++;
      const nomeMissao = e.missao || t('semMissaoIdentificada');
      porMissao[nomeMissao] = (porMissao[nomeMissao] || 0) + 1;
      (musicasPorMissao[nomeMissao] = musicasPorMissao[nomeMissao] || []).push(nomeMusicaResumo(e));
    });

    let missaoComMais = null;
    let missaoComMenos = null;
    Object.entries(porMissao).forEach(([nome, qtd]) => {
      if (!missaoComMais || qtd > missaoComMais.qtd) missaoComMais = { nome, qtd };
      if (!missaoComMenos || qtd < missaoComMenos.qtd) missaoComMenos = { nome, qtd };
    });
    // se só teve uma missão no mês (ou todas empatadas), "mais" e "menos"
    // seriam a mesma linha — deixa "menos" de fora pra não repetir à toa.
    if (missaoComMais && missaoComMenos && missaoComMais.nome === missaoComMenos.nome) {
      missaoComMenos = null;
    }
    if (missaoComMais) missaoComMais.musicas = musicasPorMissao[missaoComMais.nome] || [];
    if (missaoComMenos) missaoComMenos.musicas = musicasPorMissao[missaoComMenos.nome] || [];

    return {
      // se só teve 1 música com duração válida no mês, maisLonga e
      // maisCurta seriam a mesma faixa — deixa "curta" de fora.
      musicaMaisLonga: resumoMusica(musicaMaisLonga),
      musicaMaisCurta: musicaMaisCurta === musicaMaisLonga ? null : resumoMusica(musicaMaisCurta),
      letraMaisLonga: resumoLetra(letraMaisLonga, tamanhoMaisLonga),
      letraMaisCurta: letraMaisCurta === letraMaisLonga ? null : resumoLetra(letraMaisCurta, tamanhoMaisCurta),
      totalInstrumentais,
      missaoComMais,
      missaoComMenos,
      capasDoMes: coletarCapasDoMes(entradas),
      titulosDoMes: coletarTitulosDoMes(entradas),
    };
  }

  function calcularResumoDoMes(mesAnoChave) {
    garantirCotacaoAtualizada();
    const todasEntradas = entradasDoMes(Object.values(getLogs()), mesAnoChave);
    const entradas = todasEntradas.filter((e) => !isMissionBlacklistedByWidget(e.missao || t('semMissaoIdentificada')));
    const detalhes = calcularDetalhesResumoMes(entradas);
    const recompensas = calcularRecompensas(entradas);

    return {
      quantidade: recompensas.totalCount,
      valorUSD: recompensas.totalUSD,
      valorBRL: recompensas.totalBRL,
      moeda: recompensas.moeda,
      ...detalhes,
    };
  }

  function diasRestantesNoMes(date) {
    const ultimoDia = new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
    return ultimoDia - date.getDate();
  }

  function getAvisoFimMesSuspenso() {
    return GM_getValue(STORAGE_AVISO_FIM_MES_SUSPENSO_KEY, null);
  }

  function suspenderAvisoFimMes(mesAnoChave) {
    GM_setValue(STORAGE_AVISO_FIM_MES_SUSPENSO_KEY, mesAnoChave);
  }

  // quantas horas faltam até a virada do mês, a partir de `date`
  // (pode dar negativo se por acaso já passou, o que não deveria acontecer
  // em uso normal já que o painel é reaberto do zero a cada abertura).
  function horasRestantesNoMes(date) {
    const inicioProximoMes = new Date(date.getFullYear(), date.getMonth() + 1, 1, 0, 0, 0, 0);
    return (inicioProximoMes.getTime() - OFFSET_VIRADA_CICLO_MS - date.getTime()) / 3600000;
  }

  function getAvisoResumoMesSuspenso() {
    return GM_getValue(STORAGE_AVISO_RESUMO_MES_SUSPENSO_KEY, null);
  }

  function suspenderAvisoResumoMes(mesAnoChave) {
    GM_setValue(STORAGE_AVISO_RESUMO_MES_SUSPENSO_KEY, mesAnoChave);
  }

  function deveMostrarAvisoResumoMes() {
    const agora = mxmAgora();
    const mesAtualChave = chaveCicloAtual();
    if (getAvisoResumoMesSuspenso() === mesAtualChave) return false;
    if (horasRestantesNoMes(agora) > AVISO_RESUMO_MES_LIMITE_HORAS) return false;
    if (horasRestantesNoMes(agora) <= 0) return false;
    return calcularResumoDoMes(mesAtualChave).quantidade > 0;
  }

  function resumoAoVivoDisponivel() {
    const agora = mxmAgora();
    const mesAtualChave = chaveCicloAtual();
    if (horasRestantesNoMes(agora) > AVISO_RESUMO_MES_LIMITE_HORAS) return false;
    if (horasRestantesNoMes(agora) <= 0) return false;
    return calcularResumoDoMes(mesAtualChave).quantidade > 0;
  }

  function deveMostrarAvisoFimMes() {
    const agora = mxmAgora();
    const mesAtualChave = chaveCicloAtual();
    if (getAvisoFimMesSuspenso() === mesAtualChave) return false;
    const dias = diasRestantesNoMes(agora);
    if (dias > AVISO_FIM_MES_LIMITE_DIAS) return false;
    if (dias <= 0) return false;
    return calcularResumoDoMes(mesAtualChave).quantidade > 0;
  }

  function getResumosMensais() {
    return GM_getValue(STORAGE_RESUMOS_MENSAIS_KEY, {});
  }

  function salvarResumoMensal(mesAnoChave, resumo) {
    const resumos = getResumosMensais();
    resumos[mesAnoChave] = { ...resumo, salvoEm: mxmAgoraMs() };
    GM_setValue(STORAGE_RESUMOS_MENSAIS_KEY, resumos);
  }

  function apagarResumoMensal(mesAnoChave) {
    const resumos = getResumosMensais();
    delete resumos[mesAnoChave];
    GM_setValue(STORAGE_RESUMOS_MENSAIS_KEY, resumos);
  }

  function getMesesPerguntados() {
    return GM_getValue(STORAGE_MESES_PERGUNTADOS_KEY, []);
  }

  function marcarMesPerguntado(mesAnoChave) {
    const lista = getMesesPerguntados();
    if (!lista.includes(mesAnoChave)) {
      lista.push(mesAnoChave);
      GM_setValue(STORAGE_MESES_PERGUNTADOS_KEY, lista);
    }
  }

  // Substitui os tokens {mes}/{qtd}/{usd}/{brl} de uma string de tradução —
  // mesmo padrão simples usado só aqui, já que essas são as únicas mensagens
  // do script com valores dinâmicos dentro do texto traduzido.
  function preencherTemplate(template, valores) {
    return String(template || '').replace(/\{(\w+)\}/g, (match, chave) =>
      Object.prototype.hasOwnProperty.call(valores, chave) ? valores[chave] : match
    );
  }

  // "1 caractere" vs "{n} caracteres" — usado nas linhas de
  // maior/menor letra do bloco "Mais detalhes do mês".
  function formatarContagemCaracteres(n) {
    return n === 1 ? t('resumoAtualCaractere') : preencherTemplate(t('resumoAtualCaracteres'), { n: String(n) });
  }

  function partesTemplateContagemCaracteres() {
    const tpl = t('resumoAtualCaracteres');
    const idx = tpl.indexOf('{n}');
    return idx === -1 ? ['', tpl] : [tpl.slice(0, idx), tpl.slice(idx + 3)];
  }

  // Toast simples e genérico (texto só, sem capa/artista) — showPopup é
  // específico pra confirmação de envio de música, então não serve aqui.
  function mostrarToastSimples(mensagem, tipoSom) {
    // bipe correspondente ao toast — 'erro' pros avisos de falha
    // (ex: backup automático que não conseguiu salvar), 'sucesso' pros
    // demais (padrão), passado explicitamente pelo chamador.
    tocarSom(tipoSom || 'sucesso');
    document.querySelectorAll('#mxm-log-toast-simples').forEach((el) => el.remove());
    const toast = document.createElement('div');
    toast.id = 'mxm-log-toast-simples';
    Object.assign(toast.style, {
      position: 'fixed',
      top: '24px',
      left: '50%',
      transform: 'translateX(-50%) translateY(-16px)',
      zIndex: 999999,
      background: 'color-mix(in srgb, var(--md-sys-color-primary) 9%, var(--md-sys-color-surface-container-low))',
      color: 'var(--md-sys-color-on-surface)',
      padding: '12px 18px',
      borderRadius: 'var(--md-shape-lg)',
      fontFamily: 'sans-serif',
      fontSize: '13px',
      fontWeight: '600',
      boxShadow: 'var(--md-elevation-3)',
      border: '1px solid color-mix(in srgb, var(--md-sys-color-primary) 30%, transparent)',
      opacity: '0',
      transition: 'opacity 0.25s ease, transform 0.25s ease',
      pointerEvents: 'none',
    });
    toast.textContent = mensagem;
    document.body.appendChild(toast);
    requestAnimationFrame(() => {
      toast.style.opacity = '1';
      toast.style.transform = 'translateX(-50%) translateY(0)';
    });
    setTimeout(() => {
      if (!toast.isConnected) return;
      toast.style.opacity = '0';
      toast.style.transform = 'translateX(-50%) translateY(-16px)';
      setTimeout(() => toast.remove(), 260);
    }, 3000);
  }

  // Cartão de aviso (mesmo padrão visual/animação de abrirConfirmacao, mas
  // com ícone/cor neutros — não é uma ação destrutiva) perguntando se o
  // usuário quer guardar o resumo do mês que acabou de virar.
  function abrirPromptResumoMensal(mesAnoChave, resumo) {
    document.querySelectorAll('#mxm-log-resumo-mensal-overlay').forEach((el) => el.remove());

    const overlay = document.createElement('div');
    overlay.id = 'mxm-log-resumo-mensal-overlay';
    Object.assign(overlay.style, {
      position: 'fixed',
      inset: '0',
      background: 'color-mix(in srgb, var(--md-sys-color-scrim) 60%, transparent)',
      zIndex: proximoZIndexFlutuante(),
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
    });

    const mensagem = preencherTemplate(t('resumoMensalMensagem'), {
      mes: formatarRotuloMes(mesAnoChave),
      qtd: resumo.quantidade,
      usd: `$${resumo.valorUSD.toFixed(2)}`,
      brl: `${simboloMoeda(moedaDoResumo(resumo))}${resumo.valorBRL.toFixed(2)}`,
    });

    overlay.innerHTML = `
      <div style="background:var(--md-sys-color-surface-container-low); color:var(--md-sys-color-on-surface); width:340px; max-width:90vw; border-radius:var(--md-shape-xl); box-shadow:var(--md-elevation-3); font-family:sans-serif; overflow:hidden;">
        <div style="padding:18px 18px 4px; display:flex; align-items:flex-start; gap:10px;">
          <div style="width:34px; height:34px; border-radius:var(--md-shape-sm); background:color-mix(in srgb, var(--md-sys-color-primary) 14%, transparent); display:flex; align-items:center; justify-content:center; flex-shrink:0;" class="mxm-icone-pop">${icone(
            'calendar',
            17,
            'var(--md-sys-color-primary)'
          )}</div>
          <div style="flex:1; min-width:0;">
            <div style="font-size:14px; font-weight:700; margin-bottom:4px;">${t('resumoMensalTitulo')}</div>
            <div style="font-size:12.5px; color:var(--md-sys-color-on-surface-variant); line-height:1.5;">${mensagem}</div>
          </div>
          <div id="mxm-log-resumo-mensal-slides" title="${escapeHtml(
            t('resumoAtualVerSlides')
          )}" style="width:30px; height:30px; border-radius:50%; background:color-mix(in srgb, var(--md-sys-color-primary) 14%, transparent); color:var(--md-sys-color-primary); display:flex; align-items:center; justify-content:center; flex-shrink:0; cursor:pointer;">${icone(
      'sparkles',
      14,
      'var(--md-sys-color-primary)'
    )}</div>
        </div>
        <div style="display:flex; gap:8px; padding:16px 18px;">
          <button id="mxm-log-resumo-mensal-agora-nao" style="flex:1; padding:8px; border-radius:var(--md-shape-sm); border:1px solid var(--md-sys-color-outline-variant); background:transparent; color:var(--md-sys-color-on-surface-variant); font-size:13px; cursor:pointer;">${t(
            'resumoMensalAgoraNao'
          )}</button>
          <button id="mxm-log-resumo-mensal-salvar" style="flex:1; padding:8px; border-radius:var(--md-shape-sm); border:none; background:var(--md-sys-color-primary); color:var(--md-sys-color-on-primary); font-size:13px; font-weight:600; cursor:pointer;">${t(
            'resumoMensalBotaoSalvar'
          )}</button>
        </div>
      </div>
    `;

    document.body.appendChild(overlay);
    const cartao = overlay.firstElementChild;
    animarEntradaCartao(cartao, { distancia: 8, duracao: 180 });

    marcarMesPerguntado(mesAnoChave);

    document.getElementById('mxm-log-resumo-mensal-agora-nao').addEventListener('click', () =>
      fecharOverlayAnimado(overlay, cartao, { distancia: 8, duracao: 180 })
    );
    // mesmo atalho pro carrossel de slides — aqui é o momento mais
    // natural pra ver ("mostrar essa tela no final"), já que esse prompt só
    // aparece quando o mês literalmente acabou de virar.
    document.getElementById('mxm-log-resumo-mensal-slides').addEventListener('click', () => {
      tocarSom('clique');
      fecharOverlayAnimado(overlay, cartao, { distancia: 8, duracao: 180 });
      abrirResumoSlides(mesAnoChave, resumo);
    });
    document.getElementById('mxm-log-resumo-mensal-salvar').addEventListener('click', () => {
      salvarResumoMensal(mesAnoChave, resumo);
      fecharOverlayAnimado(overlay, cartao, { distancia: 8, duracao: 180 });
      mostrarToastSimples(preencherTemplate(t('resumoMensalSalvoToast'), { mes: formatarRotuloMes(mesAnoChave) }));
      if (document.getElementById('mxm-log-reward-conteudo')) renderPainelReward();
    });
  }

  // uma linha do bloco "Mais detalhes do mês" — ícone redondo +
  // rótulo à esquerda, título/artista + métrica secundária à direita
  // (truncado com ellipsis pra não estourar a largura do cartão de 360px).
  function renderLinhaDetalheResumo(iconeNome, cor, label, tituloPrincipal, valorSecundario) {
    const linhaSecundaria = valorSecundario
      ? `<span style="display:block; font-size:10.5px; color:var(--md-sys-color-outline); margin-top:1px;">${escapeHtml(
          valorSecundario
        )}</span>`
      : '';
    return `
      <div style="display:flex; justify-content:space-between; align-items:center; gap:10px; padding:9px 11px; margin-bottom:6px; border-radius:var(--md-shape-lg); background:var(--md-sys-color-surface-container-high);">
        <span style="display:flex; align-items:center; gap:7px; min-width:0; flex-shrink:0;">
          <span style="width:22px; height:22px; border-radius:50%; background:color-mix(in srgb, ${cor} 20%, transparent); display:flex; align-items:center; justify-content:center; flex-shrink:0; color:${cor};">${icone(
      iconeNome,
      11,
      cor
    )}</span>
          <span style="font-size:10.5px; font-weight:600; color:var(--md-sys-color-on-surface-variant); line-height:1.3; max-width:92px;">${escapeHtml(
            label
          )}</span>
        </span>
        <span style="text-align:right; min-width:0; overflow:hidden;">
          <span style="display:block; font-size:12px; font-weight:700; color:var(--md-sys-color-on-surface); overflow:hidden; text-overflow:ellipsis; white-space:nowrap; max-width:170px;" title="${escapeHtml(
            tituloPrincipal
          )}">${escapeHtml(tituloPrincipal)}</span>
          ${linhaSecundaria}
        </span>
      </div>
    `;
  }

  // "Título — Artista" (só o título se não tiver artista) —
  // usado tanto nas linhas de "Mais detalhes do mês" quanto nos slides do
  // carrossel (ver montarSlidesResumoMes).
  function nomeMusicaResumo(m) {
    return `${m.titulo || '?'}${m.artista ? ' — ' + m.artista : ''}`;
  }

  function renderDetalhesResumoMes(resumo) {
    const nomeMusica = nomeMusicaResumo;
    const linhas = [];

    if (resumo.musicaMaisLonga && Number.isFinite(resumo.musicaMaisLonga.duracaoSegundos)) {
      linhas.push(
        renderLinhaDetalheResumo(
          'music',
          'var(--md-sys-color-primary)',
          t('resumoAtualMusicaMaisLonga'),
          nomeMusica(resumo.musicaMaisLonga),
          segundosParaDuracao(resumo.musicaMaisLonga.duracaoSegundos) || ''
        )
      );
    }
    if (resumo.musicaMaisCurta && Number.isFinite(resumo.musicaMaisCurta.duracaoSegundos)) {
      linhas.push(
        renderLinhaDetalheResumo(
          'music',
          'var(--md-sys-color-tertiary)',
          t('resumoAtualMusicaMaisCurta'),
          nomeMusica(resumo.musicaMaisCurta),
          segundosParaDuracao(resumo.musicaMaisCurta.duracaoSegundos) || ''
        )
      );
    }
    if (resumo.letraMaisLonga) {
      linhas.push(
        renderLinhaDetalheResumo(
          'fileText',
          'var(--md-sys-color-primary)',
          t('resumoAtualLetraMaisLonga'),
          nomeMusica(resumo.letraMaisLonga),
          formatarContagemCaracteres(resumo.letraMaisLonga.tamanho)
        )
      );
    }
    if (resumo.letraMaisCurta) {
      linhas.push(
        renderLinhaDetalheResumo(
          'fileText',
          'var(--md-sys-color-tertiary)',
          t('resumoAtualLetraMaisCurta'),
          nomeMusica(resumo.letraMaisCurta),
          formatarContagemCaracteres(resumo.letraMaisCurta.tamanho)
        )
      );
    }
    if (resumo.missaoComMais) {
      linhas.push(
        renderLinhaDetalheResumo(
          'target',
          'var(--md-sys-color-primary)',
          t('resumoAtualMissaoMais'),
          resumo.missaoComMais.nome,
          `${resumo.missaoComMais.qtd} ${t('tarefasAbrev')}`
        )
      );
    }
    if (resumo.missaoComMenos) {
      linhas.push(
        renderLinhaDetalheResumo(
          'target',
          'var(--md-sys-color-tertiary)',
          t('resumoAtualMissaoMenos'),
          resumo.missaoComMenos.nome,
          `${resumo.missaoComMenos.qtd} ${t('tarefasAbrev')}`
        )
      );
    }
    // instrumentais sempre aparece se teve pelo menos 1 envio no mês
    // (mesmo que 0 instrumentais — "0" também é uma informação válida).
    linhas.push(
      renderLinhaDetalheResumo(
        'volume2',
        'var(--md-sys-color-secondary)',
        t('resumoAtualInstrumentais'),
        String(resumo.totalInstrumentais || 0),
        ''
      )
    );

    if (!linhas.length) return '';

    return `
      <div style="margin-top:2px;">
        <div style="font-size:10.5px; font-weight:700; letter-spacing:.3px; text-transform:uppercase; color:var(--md-sys-color-on-surface-variant); margin-bottom:8px;">${t(
          'resumoAtualDetalhesTitulo'
        )}</div>
        ${linhas.join('')}
      </div>
    `;
  }

  // ---------- carrossel de slides do resumo mensal (uma tela cheia por métrica, no estilo "retrospectiva") ----------

  // Monta a lista ordenada de slides a partir do mesmo objeto `resumo` já
  // usado no cartão compacto (ver calcularResumoDoMes) — cada slide é só
  // um descritor simples (tipo + dados), sem HTML ainda; renderSlideConteudo
  // é quem transforma isso em marcação. Slides cujo dado não existe (ex:
  // sem letra capturada no mês) simplesmente não entram na lista.
  // PoC — preview de 30s (Apple Music via iTunes Search API, com fallback
  // pra Deezer Search API quando a iTunes não acha) nos slides do resumo
  // mensal que falam de uma música específica. A busca na iTunes é feita
  // direto aqui no content script; o fallback na Deezer é feito no
  // background.js (ver mxm-log-preview-deezer) porque a Deezer não libera
  // CORS pra chamadas de outra origem — só o background escapa disso.
  // Cacheamos por "titulo — artista" pra não rebuscar toda vez que o
  // carrossel reabre — e reaproveitado também pelo clique na capa da lista
  // principal do log (ver alternarPreviewAppleMusicNaCapa).
  const cachePreviewAppleMusic = new Map();

  function buscarPreviewDeezerViaBackground(termo) {
    return browser.runtime
      .sendMessage({ type: 'mxm-log-preview-deezer', termo })
      .then((resposta) => {
        if (!resposta || !resposta.ok) {
          debugWarn('[preview-deezer] background respondeu erro:', resposta && resposta.erro);
          return null;
        }
        return resposta.resultado || null;
      })
      .catch((erro) => {
        debugWarn('[preview-deezer] sendMessage falhou:', erro);
        return null;
      });
  }

  function buscarPreviewAppleMusicCache(titulo, artista) {
    const chave = `${titulo || ''}—${artista || ''}`.toLowerCase();
    if (cachePreviewAppleMusic.has(chave)) return cachePreviewAppleMusic.get(chave);
    // Busca feita direto aqui no content script (fetch simples pro
    // endpoint público da iTunes Search API, que manda CORS liberado) —
    // ida-e-volta via mensagem pro background.js caía em NetworkError
    // nessa instalação MV3 do Firefox mesmo com o host em
    // host_permissions; fazer o fetch aqui evita depender disso.
    const termo = [titulo, artista].filter(Boolean).join(' ').trim();
    const promessa = !termo
      ? Promise.resolve(null)
      : fetch(`https://itunes.apple.com/search?term=${encodeURIComponent(termo)}&media=music&entity=song&limit=1`)
          .then((resposta) => {
            if (!resposta.ok) throw new Error(`iTunes Search API respondeu ${resposta.status}`);
            return resposta.json();
          })
          .then((dados) => {
            const faixa = dados && Array.isArray(dados.results) ? dados.results[0] : null;
            debugLog('[preview-apple-music]', { titulo, artista, faixa });
            if (!faixa || !faixa.previewUrl) return null;
            return { previewUrl: faixa.previewUrl, trackName: faixa.trackName, artistName: faixa.artistName };
          })
          .catch((erro) => {
            debugWarn('[preview-apple-music] fetch falhou:', erro);
            return null;
          })
          .then((resultadoItunes) => {
            // iTunes não achou (ou faixa achada não tem previewUrl) —
            // tenta a Deezer antes de desistir, cobre mais faixas "sem
            // nada de base" do que a iTunes sozinha.
            if (resultadoItunes) return resultadoItunes;
            return buscarPreviewDeezerViaBackground(termo).then((resultadoDeezer) => {
              debugLog('[preview-deezer]', { titulo, artista, resultadoDeezer });
              return resultadoDeezer;
            });
          });
    cachePreviewAppleMusic.set(chave, promessa);
    return promessa;
  }

  // ---------- PoC preview Apple Music — capa clicável na lista principal do log ----------

  // Moldura de progresso contornando o perímetro quadrado (arredondado)
  // da própria capa (38px), em vez de um anel circular que estourava pra
  // fora dela. stroke-dasharray/offset usam o perímetro aproximado de um
  // "rounded rect" (2*(largura+altura) - 8*raio + 2*PI*raio, que equivale
  // ao perímetro de um quadrado com os cantos arredondados substituídos
  // por 1/4 de círculo cada). Começa no meio do topo e fecha no sentido
  // horário conforme os 30s avançam (stroke-dashoffset decrescendo).
  const LADO_MOLDURA_CAPA_PREVIEW = 38;
  const RAIO_CANTO_MOLDURA_CAPA_PREVIEW = 6;
  const PERIMETRO_MOLDURA_CAPA_PREVIEW =
    4 * LADO_MOLDURA_CAPA_PREVIEW -
    8 * RAIO_CANTO_MOLDURA_CAPA_PREVIEW +
    2 * Math.PI * RAIO_CANTO_MOLDURA_CAPA_PREVIEW;

  function svgAnelProgressoCapa() {
    const l = LADO_MOLDURA_CAPA_PREVIEW;
    const r = RAIO_CANTO_MOLDURA_CAPA_PREVIEW;
    const inset = 1.25; // metade da stroke-width, pra moldura não ficar cortada nas bordas
    return `
      <svg class="mxm-log-capa-preview-anel" width="${l}" height="${l}" viewBox="0 0 ${l} ${l}" style="position:absolute; top:0; left:0; z-index:2; pointer-events:none; opacity:0;">
        <rect x="${inset}" y="${inset}" width="${l - inset * 2}" height="${l - inset * 2}" rx="${r}" fill="none" stroke="var(--md-sys-color-primary)" stroke-width="2.5" stroke-linecap="round" stroke-dasharray="${PERIMETRO_MOLDURA_CAPA_PREVIEW}" stroke-dashoffset="${PERIMETRO_MOLDURA_CAPA_PREVIEW}"/>
      </svg>
    `;
  }

  // Um único <audio> global pra toda a lista: clicar numa segunda capa
  // enquanto outra está tocando para a primeira antes de iniciar a nova —
  // nunca duas prévias ao mesmo tempo. `elementoCapaAtual` guarda a capa
  // (o próprio elemento do DOM) que está associada ao áudio tocando agora,
  // pra saber qual marcação visual (anel/ícone) desligar quando ele parar.
  const audioPreviewCapaLog = new Audio();
  let elementoCapaAtual = null;

  function limparEstadoVisualCapaAtual() {
    if (elementoCapaAtual) {
      elementoCapaAtual.removeAttribute('data-preview-tocando');
      const iconeEl = elementoCapaAtual.querySelector('.mxm-log-capa-preview-hover');
      if (iconeEl) iconeEl.innerHTML = icone('play', 14, '#fff');
      const anelEl = elementoCapaAtual.querySelector('.mxm-log-capa-preview-anel rect');
      if (anelEl) anelEl.setAttribute('stroke-dashoffset', String(PERIMETRO_MOLDURA_CAPA_PREVIEW));
    }
    elementoCapaAtual = null;
  }

  audioPreviewCapaLog.addEventListener('ended', limparEstadoVisualCapaAtual);
  audioPreviewCapaLog.addEventListener('pause', () => {
    // 'pause' também dispara quando trocamos o .src pra tocar uma faixa
    // nova (ver abaixo) — só limpa o estado visual se realmente não há
    // nada carregado pra tocar em seguida (currentTime zerado + sem src
    // não é garantia suficiente sozinho, então usamos uma flag explícita).
    if (audioPreviewCapaLog.dataset.trocandoFaixa === '1') return;
    limparEstadoVisualCapaAtual();
  });
  // anel de progresso dos 30s (ver svgAnelProgressoCapa) —
  // 'timeupdate' dispara com frequência suficiente (a cada ~250ms no
  // Firefox) pra uma barra curta como essa, sem precisar de rAF.
  audioPreviewCapaLog.addEventListener('timeupdate', () => {
    if (!elementoCapaAtual || !audioPreviewCapaLog.duration) return;
    const anelEl = elementoCapaAtual.querySelector('.mxm-log-capa-preview-anel rect');
    if (!anelEl) return;
    const fracao = Math.min(1, audioPreviewCapaLog.currentTime / audioPreviewCapaLog.duration);
    anelEl.setAttribute('stroke-dashoffset', String(PERIMETRO_MOLDURA_CAPA_PREVIEW * (1 - fracao)));
  });

  function alternarPreviewAppleMusicNaCapa(elementoCapa, titulo, artista) {
    const hoverEl = elementoCapa.querySelector('.mxm-log-capa-preview-hover');
    const anelSvgEl = elementoCapa.querySelector('.mxm-log-capa-preview-anel');

    // clicou de novo na MESMA capa que já está tocando → pausa/retoma
    // esse áudio, sem rebuscar nada.
    if (elementoCapaAtual === elementoCapa && audioPreviewCapaLog.src) {
      if (audioPreviewCapaLog.paused) {
        audioPreviewCapaLog.play().catch(() => {});
        elementoCapa.setAttribute('data-preview-tocando', '1');
        if (hoverEl) hoverEl.innerHTML = icone('pause', 14, '#fff');
      } else {
        audioPreviewCapaLog.pause();
        elementoCapa.removeAttribute('data-preview-tocando');
        if (hoverEl) hoverEl.innerHTML = icone('play', 14, '#fff');
      }
      return;
    }

    // trocando de faixa (de outra capa, ou primeira vez) — feedback
    // imediato de "carregando" antes da busca resolver, já que a rede
    // pode levar um instante.
    audioPreviewCapaLog.dataset.trocandoFaixa = '1';
    audioPreviewCapaLog.pause();
    limparEstadoVisualCapaAtual();
    elementoCapaAtual = elementoCapa;
    elementoCapa.setAttribute('data-preview-tocando', '1');
    if (hoverEl) hoverEl.innerHTML = icone('loader', 14, '#fff');
    const anelInicialEl = anelSvgEl ? anelSvgEl.querySelector('circle') : null;
    if (anelInicialEl) anelInicialEl.setAttribute('stroke-dashoffset', String(PERIMETRO_MOLDURA_CAPA_PREVIEW));

    buscarPreviewAppleMusicCache(titulo, artista).then((resultado) => {
      delete audioPreviewCapaLog.dataset.trocandoFaixa;
      // o usuário pode ter clicado em outra capa (ou fechado o painel)
      // enquanto a busca corria — só segue se essa capa ainda é a "atual".
      if (elementoCapaAtual !== elementoCapa) return;

      if (!resultado || !resultado.previewUrl) {
        limparEstadoVisualCapaAtual();
        mostrarToastSimples(t('logCapaPreviaIndisponivel'), 'erro');
        return;
      }

      audioPreviewCapaLog.src = resultado.previewUrl;
      audioPreviewCapaLog.volume = 0.9;
      audioPreviewCapaLog.play().catch(() => {});
      if (hoverEl) hoverEl.innerHTML = icone('pause', 14, '#fff');
    });
  }

  function montarSlidesResumoMes(mesAnoChave, resumo) {
    garantirCotacaoAtualizada();
    const moedaAtual = getSecondaryCurrencyCode();
    const valorSecundarioAtual = resumo.valorUSD * usdToSecondary;
    const mes = formatarRotuloMes(mesAnoChave);
    const slides = [
      { tipo: 'capa', icone: 'eye', cor: 'var(--md-sys-color-primary)', mes, capas: resumo.capasDoMes || [] },
      {
        tipo: 'stat',
        icone: 'dollar',
        cor: '#f2b705',
        rotulo:
          moedaAtual === 'BRL' ? t('resumoSlidesBRL') : preencherTemplate(t('resumoSlidesMoedaGenerica'), { moeda: moedaAtual }),
        valor: `${simboloMoeda(moedaAtual)}${valorSecundarioAtual.toFixed(2)}`,
        dinheiro: true,
        valorNumerico: valorSecundarioAtual,
        prefixoValor: simboloMoeda(moedaAtual),
      },
      {
        tipo: 'stat',
        icone: 'dollar',
        cor: '#1DB954',
        rotulo: t('resumoSlidesUSD'),
        valor: `$${resumo.valorUSD.toFixed(2)}`,
        dinheiro: true,
        valorNumerico: resumo.valorUSD,
        prefixoValor: '$',
      },
      {
        tipo: 'stat',
        icone: 'checkSquare',
        cor: 'var(--md-sys-color-primary)',
        rotulo: t('resumoSlidesTarefas'),
        valor: String(resumo.quantidade),
        contagemAnimada: true,
        valorNumerico: resumo.quantidade,
        casasDecimais: 0,
        titulosFundo: resumo.titulosDoMes || [],
      },
    ];

    if (resumo.musicaMaisLonga && Number.isFinite(resumo.musicaMaisLonga.duracaoSegundos)) {
      slides.push({
        tipo: 'item',
        icone: 'music',
        cor: 'var(--md-sys-color-primary)',
        rotulo: t('resumoAtualMusicaMaisLonga'),
        titulo: nomeMusicaResumo(resumo.musicaMaisLonga),
        valor: segundosParaDuracao(resumo.musicaMaisLonga.duracaoSegundos) || '',
        imagemUrl: resumo.musicaMaisLonga.imagemUrl,
        // PoC preview Apple Music — ver buscarPreviewAppleMusicCache.
        previewTitulo: resumo.musicaMaisLonga.titulo,
        previewArtista: resumo.musicaMaisLonga.artista,
      });
    }
    if (resumo.musicaMaisCurta && Number.isFinite(resumo.musicaMaisCurta.duracaoSegundos)) {
      slides.push({
        tipo: 'item',
        icone: 'music',
        cor: 'var(--md-sys-color-tertiary)',
        rotulo: t('resumoAtualMusicaMaisCurta'),
        titulo: nomeMusicaResumo(resumo.musicaMaisCurta),
        valor: segundosParaDuracao(resumo.musicaMaisCurta.duracaoSegundos) || '',
        imagemUrl: resumo.musicaMaisCurta.imagemUrl,
        previewTitulo: resumo.musicaMaisCurta.titulo,
        previewArtista: resumo.musicaMaisCurta.artista,
      });
    }
    if (resumo.letraMaisLonga) {
      const [prefixoLonga, sufixoLonga] = partesTemplateContagemCaracteres();
      slides.push({
        tipo: 'item',
        icone: 'fileText',
        cor: 'var(--md-sys-color-primary)',
        rotulo: t('resumoAtualLetraMaisLonga'),
        titulo: nomeMusicaResumo(resumo.letraMaisLonga),
        valor: formatarContagemCaracteres(resumo.letraMaisLonga.tamanho),
        imagemUrl: resumo.letraMaisLonga.imagemUrl,
        // texto de fundo + número final — disparam o fundo de
        // "texto se escrevendo" nesse slide, junto com a contagem animada
        // do selo (ver renderSlideConteudo/montarFundoTextoEscrevendo).
        textoFundoAnimado: resumo.letraMaisLonga.texto || '',
        contagemFinalAnimada: resumo.letraMaisLonga.tamanho,
        contagemPrefixo: prefixoLonga,
        contagemSufixo: sufixoLonga,
      });
    }
    if (resumo.letraMaisCurta) {
      const [prefixoCurta, sufixoCurta] = partesTemplateContagemCaracteres();
      slides.push({
        tipo: 'item',
        icone: 'fileText',
        cor: 'var(--md-sys-color-tertiary)',
        rotulo: t('resumoAtualLetraMaisCurta'),
        titulo: nomeMusicaResumo(resumo.letraMaisCurta),
        valor: formatarContagemCaracteres(resumo.letraMaisCurta.tamanho),
        imagemUrl: resumo.letraMaisCurta.imagemUrl,
        textoFundoAnimado: resumo.letraMaisCurta.texto || '',
        contagemFinalAnimada: resumo.letraMaisCurta.tamanho,
        contagemPrefixo: prefixoCurta,
        contagemSufixo: sufixoCurta,
      });
    }
    if (resumo.missaoComMais) {
      slides.push({
        tipo: 'item',
        icone: 'target',
        cor: 'var(--md-sys-color-primary)',
        rotulo: t('resumoAtualMissaoMais'),
        titulo: resumo.missaoComMais.nome,
        valor: `${resumo.missaoComMais.qtd} ${t('tarefasAbrev')}`,
        // nomes das músicas enviadas nessa missão, se escrevendo
        // atrás do cartão, sincronizados com a contagem de tarefas subindo
        // até o total (mesmo efeito dos slides de letra mais longa/curta).
        textoFundoAnimado: (resumo.missaoComMais.musicas || []).join('\n'),
        contagemFinalAnimada: resumo.missaoComMais.qtd,
        contagemPrefixo: '',
        contagemSufixo: ` ${t('tarefasAbrev')}`,
      });
    }
    if (resumo.missaoComMenos) {
      slides.push({
        tipo: 'item',
        icone: 'target',
        cor: 'var(--md-sys-color-tertiary)',
        rotulo: t('resumoAtualMissaoMenos'),
        titulo: resumo.missaoComMenos.nome,
        valor: `${resumo.missaoComMenos.qtd} ${t('tarefasAbrev')}`,
        textoFundoAnimado: (resumo.missaoComMenos.musicas || []).join('\n'),
        contagemFinalAnimada: resumo.missaoComMenos.qtd,
        contagemPrefixo: '',
        contagemSufixo: ` ${t('tarefasAbrev')}`,
      });
    }

    slides.push({
      tipo: 'stat',
      icone: 'volume2',
      cor: 'var(--md-sys-color-secondary)',
      rotulo: t('resumoAtualInstrumentais'),
      valor: String(resumo.totalInstrumentais || 0),
      contagemAnimada: true,
      valorNumerico: resumo.totalInstrumentais || 0,
      casasDecimais: 0,
      fundoEqualizador: true,
    });

    const slidesParaRecap = slides.slice(1);

    slides.push({
      tipo: 'final',
      icone: 'star',
      cor: '#f2b705',
      mes,
      capas: resumo.capasDoMes || [],
      recap: slidesParaRecap,
    });

    return slides;
  }

  function montarGradeCapasSubindo(imagens, opcoes) {
    if (!imagens || !imagens.length) return '';
    const N_COLUNAS = (opcoes && opcoes.nColunas) || 4;
    const MIN_POR_COLUNA = (opcoes && opcoes.minPorColuna) || 6;
    const DURACOES_SEGUNDOS = [26, 34, 22, 30];

    const colunas = Array.from({ length: N_COLUNAS }, () => []);
    let i = 0;
    while (colunas.some((c) => c.length < MIN_POR_COLUNA) && i < MIN_POR_COLUNA * N_COLUNAS * 4) {
      colunas[i % N_COLUNAS].push(imagens[i % imagens.length]);
      i++;
    }

    const colunasHtml = colunas
      .map((imgs, idx) => {
        const dobradas = [...imgs, ...imgs];
        const itensHtml = dobradas
          .map(
            (url) =>
              `<div class="mxm-slide-grade-item"><img src="${escapeHtml(
                url
              )}" loading="lazy" decoding="async" onerror="this.parentElement.remove()"></div>`
          )
          .join('');
        const duracao = DURACOES_SEGUNDOS[idx % DURACOES_SEGUNDOS.length];
        return `<div class="mxm-slide-grade-coluna" style="animation-duration:${duracao}s;">${itensHtml}</div>`;
      })
      .join('');

    return `<div class="mxm-slide-grade-capas">${colunasHtml}</div>`;
  }

  function montarGradeCapasEstatica(imagens, maxItens) {
    if (!imagens || !imagens.length) return '';
    const amostra = imagens.slice(0, maxItens || 8);
    const itensHtml = amostra
      .map(
        (url) =>
          `<div class="mxm-grade-estatica-item"><img src="${escapeHtml(
            url
          )}" loading="lazy" decoding="async" onerror="this.parentElement.remove()"></div>`
      )
      .join('');
    return `<div class="mxm-grade-estatica-capas">${itensHtml}</div>`;
  }

  function montarTickerTitulosSubindo(titulos) {
    if (!titulos || !titulos.length) return '';
    const N_LINHAS = 11;
    const MIN_POR_LINHA = 6;
    const DURACOES_SEGUNDOS = [42, 33, 50, 38, 46, 30];

    const linhas = Array.from({ length: N_LINHAS }, () => []);
    let i = 0;
    while (linhas.some((l) => l.length < MIN_POR_LINHA) && i < MIN_POR_LINHA * N_LINHAS * 4) {
      linhas[i % N_LINHAS].push(titulos[i % titulos.length]);
      i++;
    }

    const linhasHtml = linhas
      .map((itens, idx) => {
        const dobrados = [...itens, ...itens];
        const itensHtml = dobrados
          .map((titulo) => `<span class="mxm-slide-ticker-item">${escapeHtml(titulo)}</span>`)
          .join('');
        const duracao = DURACOES_SEGUNDOS[idx % DURACOES_SEGUNDOS.length];
        const direcao = idx % 2 === 1 ? 'reverse' : 'normal';
        return `<div class="mxm-slide-ticker-linha" style="animation-duration:${duracao}s; animation-direction:${direcao};">${itensHtml}</div>`;
      })
      .join('');

    return `<div class="mxm-slide-ticker">${linhasHtml}</div>`;
  }

  function montarEqualizadorFundo() {
    const N_BARRAS = 26;
    const DURACOES_SEGUNDOS = [1.5, 1.9, 1.65, 2.1, 1.4, 2.3, 1.75, 2.0];
    const CORES = [
      'var(--md-sys-color-primary)',
      'var(--md-sys-color-secondary)',
      'var(--md-sys-color-tertiary)',
    ];
    const barrasHtml = Array.from({ length: N_BARRAS }, (_, i) => {
      const duracao = DURACOES_SEGUNDOS[i % DURACOES_SEGUNDOS.length];
      const atraso = ((i * 0.37) % duracao).toFixed(2);
      const cor = CORES[i % CORES.length];
      return `<div class="mxm-slide-eq-barra" style="animation-duration:${duracao}s; animation-delay:-${atraso}s; background:${cor};"></div>`;
    }).join('');
    return `<div class="mxm-slide-eq-fundo">${barrasHtml}</div>`;
  }

  function montarSparklesFundo(cor) {
    const N_PARTICULAS = 16;
    const particulasHtml = Array.from({ length: N_PARTICULAS }, (_, i) => {
      const esquerda = Math.round(((i * 61) % 100));
      const tamanho = 3 + (i % 4) * 2;
      const duracao = 4.5 + (i % 5) * 1.3;
      const atraso = -(i * 0.55);
      const deriva = (i % 2 === 0 ? 1 : -1) * (8 + (i % 3) * 6);
      return `<span class="mxm-slide-sparkle" style="left:${esquerda}%; width:${tamanho}px; height:${tamanho}px; background:${cor}; animation-duration:${duracao}s; animation-delay:${atraso}s; --mxm-sparkle-deriva:${deriva}px;"></span>`;
    }).join('');
    return `<div class="mxm-slide-sparkles-fundo">${particulasHtml}</div>`;
  }

  function montarFundoTextoEscrevendo(texto) {
    if (!texto) return '';
    return `
      <div class="mxm-slide-texto-fundo">
        <div class="mxm-slide-texto-fundo-wrap"><span id="mxm-slide-texto-fundo-animado"></span><span class="mxm-slide-texto-fundo-cursor"></span></div>
        <div style="position:absolute; inset:0; background:linear-gradient(180deg, color-mix(in srgb, var(--md-sys-color-surface-container-low) 45%, transparent) 0%, var(--md-sys-color-surface-container-low) 88%);"></div>
      </div>
    `;
  }

  function obterRecapDoSlide(slide) {
    if (slide.dinheiro) {
      return { icone: slide.icone, cor: slide.cor, rotulo: slide.rotulo, valor: `${slide.prefixoValor}${slide.valorNumerico.toFixed(2)}` };
    }
    if (slide.contagemAnimada) {
      return { icone: slide.icone, cor: slide.cor, rotulo: slide.rotulo, valor: String(slide.valorNumerico) };
    }
    if (slide.tipo === 'item') {
      return { icone: slide.icone, cor: slide.cor, rotulo: slide.rotulo, valor: slide.titulo, extra: slide.valor };
    }
    return { icone: slide.icone, cor: slide.cor, rotulo: slide.rotulo, valor: slide.valor };
  }

  // Uma linha compacta da lista de recapitulação do slide final — ícone
  // pequeno em círculo tonal, rótulo à esquerda, valor (+ um detalhe extra
  // opcional, ex: a duração ao lado do nome da música) à direita, truncado
  // com ellipsis pra nunca estourar a largura do cartão. Mais enxuta que
  // renderLinhaDetalheResumo (usada no cartão "Ver resumo agora", que tem
  // bem mais espaço) porque aqui até 9-10 linhas precisam caber juntas
  // numa área rolável de altura limitada.
  function renderLinhaRecapSlideFinal(recap, indice) {
    const extraHtml = recap.extra
      ? `<span style="display:block; font-size:9.5px; color:var(--md-sys-color-outline); margin-top:1px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; max-width:150px;">${escapeHtml(
          recap.extra
        )}</span>`
      : '';
    // cada linha entra com um pequeno atraso em cascata (índice *
    // 70ms) em vez de todas aparecerem coladas de uma vez — ver
    // mxm-slide-recap-entra.
    return `
      <div class="mxm-slide-recap-entra" style="animation-delay:${(indice || 0) * 70}ms; display:flex; align-items:center; justify-content:space-between; gap:8px; padding:6px 9px; margin-bottom:5px; border-radius:var(--md-shape-md); background:color-mix(in srgb, ${
        recap.cor
      } 10%, var(--md-sys-color-surface-container-low));">
        <span style="display:flex; align-items:center; gap:6px; min-width:0; flex-shrink:1;">
          <span style="width:18px; height:18px; border-radius:50%; background:color-mix(in srgb, ${
            recap.cor
          } 24%, transparent); display:flex; align-items:center; justify-content:center; flex-shrink:0; color:${
      recap.cor
    };">${icone(recap.icone, 10, recap.cor)}</span>
          <span style="font-size:10.5px; color:var(--md-sys-color-on-surface-variant); overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${escapeHtml(
            recap.rotulo
          )}</span>
        </span>
        <span style="text-align:right; min-width:0; flex-shrink:0;">
          <span style="display:block; font-size:11.5px; font-weight:700; color:var(--md-sys-color-on-surface); overflow:hidden; text-overflow:ellipsis; white-space:nowrap; max-width:150px;" title="${escapeHtml(
            recap.valor
          )}">${escapeHtml(recap.valor)}</span>
          ${extraHtml}
        </span>
      </div>
    `;
  }

  // PoC — botão de play do preview de 30s (Apple Music). Some sozinho se a
  // busca não achar a faixa (ver ligarBotaoPreviewAppleMusic), então
  // começa sempre no estado "carregando" pra não piscar layout.
  function montarBotaoPreviewAppleMusic(cor) {
    return `
      <button type="button" id="mxm-slide-preview-play" data-estado="carregando" style="margin-top:14px; display:inline-flex; align-items:center; gap:7px; border:none; cursor:pointer; padding:7px 16px; border-radius:var(--md-shape-full); background:color-mix(in srgb, ${cor} 14%, transparent); color:${cor}; font-family:inherit; font-size:12px; font-weight:700;">
        <span id="mxm-slide-preview-icone" style="display:flex;">${icone('loader', 13, cor)}</span>
        <span id="mxm-slide-preview-label">${escapeHtml(t('resumoPreviewCarregando'))}</span>
      </button>
    `;
  }

  // Busca o preview (cache) e liga o clique do botão renderizado por
  // montarBotaoPreviewAppleMusic. `getAudioAtivo`/`setAudioAtivo` deixam o
  // chamador (abrirResumoSlides) garantir que só um preview toca por vez e
  // que ele para ao trocar de slide/fechar o carrossel.
  function ligarBotaoPreviewAppleMusic(slide, getAudioAtivo, setAudioAtivo) {
    const botao = document.getElementById('mxm-slide-preview-play');
    if (!botao) return;

    buscarPreviewAppleMusicCache(slide.previewTitulo, slide.previewArtista).then((resultado) => {
      // o slide pode já ter trocado enquanto a busca corria — o botão
      // dessa instância pode nem existir mais no DOM, então checa de novo.
      const botaoAtual = document.getElementById('mxm-slide-preview-play');
      if (!botaoAtual) return;

      if (!resultado || !resultado.previewUrl) {
        botaoAtual.remove();
        return;
      }

      botaoAtual.dataset.estado = 'pausado';
      botaoAtual.querySelector('#mxm-slide-preview-icone').innerHTML = icone('play', 13, botaoAtual.style.color);
      botaoAtual.querySelector('#mxm-slide-preview-label').textContent = t('resumoPreviewOuvir');

      botaoAtual.addEventListener('click', () => {
        const audioAtivo = getAudioAtivo();
        if (audioAtivo && audioAtivo.dataset && audioAtivo.dataset.url === resultado.previewUrl && !audioAtivo.paused) {
          audioAtivo.pause();
          botaoAtual.dataset.estado = 'pausado';
          botaoAtual.querySelector('#mxm-slide-preview-icone').innerHTML = icone('play', 13, botaoAtual.style.color);
          botaoAtual.querySelector('#mxm-slide-preview-label').textContent = t('resumoPreviewOuvir');
          return;
        }

        // só um preview por vez — para o que estava tocando antes
        // (de outro slide ou reaberto) e sobe o volume da musiquinha
        // de fundo de volta, já que o preview real assume o protagonismo.
        if (audioAtivo) {
          audioAtivo.pause();
        }

        const audio = new Audio(resultado.previewUrl);
        audio.dataset.url = resultado.previewUrl;
        audio.volume = 0.9;
        audio.play().catch(() => {});
        setAudioAtivo(audio);

        botaoAtual.dataset.estado = 'tocando';
        botaoAtual.querySelector('#mxm-slide-preview-icone').innerHTML = icone('pause', 13, botaoAtual.style.color);
        botaoAtual.querySelector('#mxm-slide-preview-label').textContent = t('resumoPreviewTocando');

        audio.addEventListener('ended', () => {
          botaoAtual.dataset.estado = 'pausado';
          const iconeEl = document.getElementById('mxm-slide-preview-icone');
          const labelEl = document.getElementById('mxm-slide-preview-label');
          if (iconeEl) iconeEl.innerHTML = icone('play', 13, botaoAtual.style.color);
          if (labelEl) labelEl.textContent = t('resumoPreviewOuvir');
        });
      });
    });
  }

  function renderSlideConteudo(slide) {
    const iconeGrande = (tamanho) => `
      <div style="position:relative; width:${tamanho + 36}px; height:${tamanho + 36}px; margin:0 auto 18px;">
        <div class="mxm-icone-halo" style="position:absolute; inset:-10px; border-radius:50%; background:${slide.cor};"></div>
        <div class="mxm-icone-pop" style="position:relative; width:100%; height:100%; border-radius:50%; background:color-mix(in srgb, ${
      slide.cor
    } 18%, transparent); display:flex; align-items:center; justify-content:center;">${icone(
      slide.icone,
      tamanho,
      slide.cor
    )}</div>
      </div>
    `;

    const fundoCapa = slide.imagemUrl
      ? `<div style="position:absolute; inset:0; z-index:0; overflow:hidden;">
           <img src="${escapeHtml(slide.imagemUrl)}" onerror="this.remove()" class="mxm-slide-fundo-img" style="width:100%; height:100%; object-fit:cover;">
           <div style="position:absolute; inset:0; background:linear-gradient(180deg, color-mix(in srgb, var(--md-sys-color-surface-container-low) 45%, transparent) 0%, var(--md-sys-color-surface-container-low) 88%);"></div>
         </div>`
      : '';
    const comFundo = (miolo) => `${fundoCapa}<div style="position:relative; z-index:1;">${miolo}</div>`;

    if (slide.tipo === 'capa') {
      const gradeCapas = montarGradeCapasSubindo(slide.capas);
      const fundoSlide = gradeCapas
        ? `<div style="position:absolute; inset:0; z-index:0; overflow:hidden;">
             ${gradeCapas}
             <div style="position:absolute; inset:0; background:linear-gradient(180deg, color-mix(in srgb, var(--md-sys-color-surface-container-low) 55%, transparent) 0%, var(--md-sys-color-surface-container-low) 92%);"></div>
           </div>`
        : fundoCapa;

      return `${fundoSlide}<div style="position:relative; z-index:1;">
        ${iconeGrande(34)}
        <div class="mxm-slide-texto-entra-cima" style="animation-delay:80ms; font-size:12px; font-weight:700; letter-spacing:.3px; text-transform:uppercase; color:var(--md-sys-color-on-surface-variant); margin-bottom:8px;">${t(
          'resumoAtualTitulo'
        )}</div>
        <div class="mxm-slide-texto-entra-cima" style="animation-delay:170ms; font-size:24px; font-weight:800; line-height:1.3; color:var(--md-sys-color-on-surface);">${escapeHtml(
          preencherTemplate(t('resumoSlidesCapaTitulo'), { mes: slide.mes })
        )}</div>
      </div>`;
    }

    if (slide.tipo === 'final') {
      const gradeCapas = montarGradeCapasSubindo(slide.capas);
      const fundoSlide = gradeCapas
        ? `<div style="position:absolute; inset:0; z-index:0; overflow:hidden;">
             ${gradeCapas}
             <div style="position:absolute; inset:0; background:linear-gradient(180deg, color-mix(in srgb, var(--md-sys-color-surface-container-low) 55%, transparent) 0%, var(--md-sys-color-surface-container-low) 92%);"></div>
           </div>`
        : fundoCapa;

      const recapHtml = (slide.recap || [])
        .map((s, i) => renderLinhaRecapSlideFinal(obterRecapDoSlide(s), i))
        .join('');

      return `${fundoSlide}<div style="position:relative; z-index:1; width:100%; display:flex; flex-direction:column; align-items:center; min-height:0;">
        ${iconeGrande(24)}
        <div style="font-size:18px; font-weight:800; line-height:1.3; color:var(--md-sys-color-on-surface); margin-bottom:4px;">${escapeHtml(
          preencherTemplate(t('resumoSlidesFinalTitulo'), { mes: slide.mes })
        )}</div>
        <div style="font-size:12px; color:var(--md-sys-color-on-surface-variant); margin-bottom:14px;">${escapeHtml(
          t('resumoSlidesFinalTexto')
        )}</div>
        ${
          recapHtml
            ? `<div style="width:100%; max-height:190px; overflow-y:auto; text-align:left; padding:0 2px;">${recapHtml}</div>`
            : ''
        }
      </div>`;
    }

    if (slide.tipo === 'item') {
      if (slide.textoFundoAnimado) {
        return `${fundoCapa}${montarFundoTextoEscrevendo(slide.textoFundoAnimado)}<div style="position:relative; z-index:1;">
          ${iconeGrande(26)}
          <div style="font-size:11px; font-weight:700; letter-spacing:.3px; text-transform:uppercase; color:var(--md-sys-color-on-surface-variant); margin-bottom:10px;">${escapeHtml(
            slide.rotulo
          )}</div>
          <div style="font-size:19px; font-weight:800; line-height:1.35; color:var(--md-sys-color-on-surface); word-break:break-word;">${escapeHtml(
            slide.titulo
          )}</div>
          <div style="display:inline-flex; margin-top:12px; padding:5px 14px; border-radius:var(--md-shape-full); background:color-mix(in srgb, ${
            slide.cor
          } 18%, transparent); color:${
          slide.cor
        }; font-size:13px; font-weight:700; font-variant-numeric:tabular-nums;">${escapeHtml(
          slide.contagemPrefixo || ''
        )}<span id="mxm-slide-contagem-animada" data-final="${slide.contagemFinalAnimada || 0}">0</span>${escapeHtml(
          slide.contagemSufixo || ''
        )}</div>
        </div>`;
      }
      return comFundo(`
        ${iconeGrande(26)}
        <div style="font-size:11px; font-weight:700; letter-spacing:.3px; text-transform:uppercase; color:var(--md-sys-color-on-surface-variant); margin-bottom:10px;">${escapeHtml(
          slide.rotulo
        )}</div>
        <div style="font-size:19px; font-weight:800; line-height:1.35; color:var(--md-sys-color-on-surface); word-break:break-word;">${escapeHtml(
          slide.titulo
        )}</div>
        <div style="display:inline-flex; margin-top:12px; padding:5px 14px; border-radius:var(--md-shape-full); background:color-mix(in srgb, ${
          slide.cor
        } 18%, transparent); color:${slide.cor}; font-size:13px; font-weight:700;">${escapeHtml(slide.valor)}</div>
        ${slide.previewTitulo ? montarBotaoPreviewAppleMusic(slide.cor) : ''}
      `);
    }

    if (slide.dinheiro) {
      const ALTURAS_BARRAS = [0.3, 0.45, 0.38, 0.56, 0.5, 0.7, 0.62, 0.85, 1];
      const barrasHtml = ALTURAS_BARRAS.map(
        (alt, i) =>
          `<div class="mxm-mini-grafico-barra" style="height:${Math.round(
            alt * 34
          )}px; animation-delay:${i * 65}ms; background:color-mix(in srgb, ${slide.cor} 85%, transparent);"></div>`
      ).join('');
      return `${montarSparklesFundo(slide.cor)}<div style="position:relative; z-index:1;">
        ${iconeGrande(26)}
        <div style="font-size:11px; font-weight:700; letter-spacing:.3px; text-transform:uppercase; color:var(--md-sys-color-on-surface-variant); margin-bottom:8px;">${escapeHtml(
          slide.rotulo
        )}</div>
        <div id="mxm-slide-valor-numero" data-prefixo="${escapeHtml(
          slide.prefixoValor
        )}" data-final="${slide.valorNumerico}" data-casas="2" style="font-size:32px; font-weight:800; color:${
        slide.cor
      }; word-break:break-word; font-variant-numeric:tabular-nums;">${escapeHtml(slide.prefixoValor)}0.00</div>
        <div class="mxm-mini-grafico" style="display:flex; align-items:flex-end; justify-content:center; gap:5px; height:34px; margin-top:16px;">${barrasHtml}</div>
      </div>`;
    }

    if (slide.contagemAnimada) {
      let fundoSlide;
      if (slide.fundoEqualizador) {
        fundoSlide = montarEqualizadorFundo();
      } else {
        const ticker = montarTickerTitulosSubindo(slide.titulosFundo);
        fundoSlide = ticker
          ? `<div style="position:absolute; inset:0; z-index:0; overflow:hidden;">
               ${ticker}
               <div style="position:absolute; inset:0; background:linear-gradient(180deg, color-mix(in srgb, var(--md-sys-color-surface-container-low) 55%, transparent) 0%, var(--md-sys-color-surface-container-low) 92%);"></div>
             </div>`
          : fundoCapa;
      }

      return `${fundoSlide}<div style="position:relative; z-index:1;">
        ${iconeGrande(26)}
        <div style="font-size:11px; font-weight:700; letter-spacing:.3px; text-transform:uppercase; color:var(--md-sys-color-on-surface-variant); margin-bottom:8px;">${escapeHtml(
          slide.rotulo
        )}</div>
        <div id="mxm-slide-valor-numero" data-prefixo="" data-final="${
          slide.valorNumerico
        }" data-casas="${slide.casasDecimais || 0}" style="font-size:32px; font-weight:800; color:${
        slide.cor
      }; word-break:break-word; font-variant-numeric:tabular-nums;">0</div>
      </div>`;
    }

    return comFundo(`
      ${iconeGrande(26)}
      <div style="font-size:11px; font-weight:700; letter-spacing:.3px; text-transform:uppercase; color:var(--md-sys-color-on-surface-variant); margin-bottom:8px;">${escapeHtml(
        slide.rotulo
      )}</div>
      <div style="font-size:32px; font-weight:800; color:${slide.cor}; word-break:break-word;">${escapeHtml(slide.valor)}</div>
    `);
  }

  function animarNumeroDinheiro(el) {
    if (!el) return;
    const valorFinal = parseFloat(el.dataset.final || '0');
    const prefixo = el.dataset.prefixo || '';
    const casas = parseInt(el.dataset.casas, 10);
    const casasDecimais = Number.isFinite(casas) ? casas : 2;
    const DURACAO_MS = 1100;
    const inicio = performance.now();
    function passo(agora) {
      const progresso = Math.min(1, (agora - inicio) / DURACAO_MS);
      const suavizado = 1 - Math.pow(1 - progresso, 3);
      el.textContent = `${prefixo}${(valorFinal * suavizado).toFixed(casasDecimais)}`;
      if (progresso < 1) requestAnimationFrame(passo);
    }
    requestAnimationFrame(passo);
  }

  function animarContagemETextoFundo(elNumero, elTexto, textoCompleto) {
    if (!elNumero) return;
    const valorFinal = parseInt(elNumero.dataset.final || '0', 10);
    const DURACAO_MS = 1500;
    const inicio = performance.now();
    function passo(agora) {
      const progresso = Math.min(1, (agora - inicio) / DURACAO_MS);
      const suavizado = 1 - Math.pow(1 - progresso, 3);
      elNumero.textContent = String(Math.round(valorFinal * suavizado));
      if (elTexto && textoCompleto) {
        elTexto.textContent = textoCompleto.slice(0, Math.round(textoCompleto.length * suavizado));
      }
      if (progresso < 1) requestAnimationFrame(passo);
    }
    requestAnimationFrame(passo);
  }

  function dispararConfete(container) {
    if (!container) return;
    const CORES = [
      'var(--md-sys-color-primary)',
      'var(--md-sys-color-secondary)',
      'var(--md-sys-color-tertiary)',
      '#f2b705',
    ];
    const N_PECAS = 36;
    const wrap = document.createElement('div');
    wrap.className = 'mxm-confete-wrap';
    for (let i = 0; i < N_PECAS; i++) {
      const peca = document.createElement('span');
      peca.className = 'mxm-confete-peca';
      const esquerda = Math.random() * 100;
      const atraso = Math.random() * 0.5;
      const duracao = 2.2 + Math.random() * 1.4;
      const cor = CORES[i % CORES.length];
      const rotacaoFinal = 360 + Math.round(Math.random() * 360);
      peca.style.left = `${esquerda}%`;
      peca.style.background = cor;
      peca.style.animationDelay = `${atraso}s`;
      peca.style.animationDuration = `${duracao}s`;
      peca.style.setProperty('--mxm-confete-rot', `${rotacaoFinal}deg`);
      wrap.appendChild(peca);
    }
    container.appendChild(wrap);
    setTimeout(() => wrap.remove(), 4200);
  }

  // Carrossel em tela cheia (dentro do overlay, mesmo padrão dos outros
  // painéis flutuantes) — um slide por vez, navegação por setas nas
  // laterais, bolinhas de progresso clicáveis no topo, arraste (touch) e
  // setas do teclado. Pensado pra ser mostrado (ou até capturado em print)
  // no fim do mês, tipo uma "retrospectiva" curta dos números do período.
  function abrirResumoSlides(mesAnoChave, resumo) {
    document.querySelectorAll('#mxm-log-resumo-slides-overlay').forEach((el) => el.remove());

    const slides = montarSlidesResumoMes(mesAnoChave, resumo);
    let indice = 0;

    const overlay = document.createElement('div');
    overlay.id = 'mxm-log-resumo-slides-overlay';
    Object.assign(overlay.style, {
      position: 'fixed',
      inset: '0',
      background: 'color-mix(in srgb, var(--md-sys-color-scrim) 78%, transparent)',
      zIndex: proximoZIndexFlutuante(),
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
    });

    // cada bolinha virou uma barrinha com um preenchimento interno
    // (mxm-slide-dot-fill) que anima de 0% a 100% — igual ao stories do
    // Instagram — em vez de só acender de uma vez quando o slide muda.
    const dotsHtml = slides
      .map(
        (_, i) =>
          `<span class="mxm-slide-dot" data-i="${i}" style="flex:1; height:3px; border-radius:2px; background:var(--md-sys-color-outline-variant); cursor:pointer; overflow:hidden; position:relative;"><span class="mxm-slide-dot-fill" style="position:absolute; inset:0; width:0%; background:var(--md-sys-color-primary); border-radius:2px;"></span></span>`
      )
      .join('');

    overlay.innerHTML = `
      <div id="mxm-log-resumo-slides-cartao" style="position:relative; width:460px; max-width:94vw; height:540px; max-height:88vh; border-radius:var(--md-shape-xl); box-shadow:var(--md-elevation-3); overflow:hidden; font-family:sans-serif; background:var(--md-sys-color-surface-container-low); display:flex; flex-direction:column;">
        <div style="display:flex; gap:4px; padding:14px 16px 0;">${dotsHtml}</div>
        <div id="mxm-log-resumo-slides-mutar" title="${escapeHtml(
          isResumoMusicaMutado() ? t('resumoMusicaAtivar') : t('resumoMusicaSilenciar')
        )}" style="position:absolute; top:12px; right:52px; cursor:pointer; color:#fff; background:color-mix(in srgb, var(--md-sys-color-scrim) 45%, transparent); border-radius:50%; padding:6px; display:flex; z-index:2;">${icone(
      isResumoMusicaMutado() ? 'volumeX' : 'volume2',
      13,
      '#fff'
    )}</div>
        <div id="mxm-log-resumo-slides-fechar" title="${escapeHtml(t('fechar'))}" style="position:absolute; top:12px; right:12px; cursor:pointer; color:#fff; background:color-mix(in srgb, var(--md-sys-color-scrim) 45%, transparent); border-radius:50%; padding:6px; display:flex; z-index:2;">${icone(
      'x',
      13,
      '#fff'
    )}</div>
        <div id="mxm-log-resumo-slides-conteudo" style="position:relative; overflow:hidden; flex:1; display:flex; flex-direction:column; align-items:center; justify-content:center; padding:20px 30px; text-align:center; min-height:0;"></div>
        <div id="mxm-log-resumo-slides-nav" style="display:flex; gap:10px; padding:0 18px 20px;">
          <div id="mxm-log-resumo-slides-prev" title="${escapeHtml(
            t('resumoSlidesAnterior')
          )}" style="width:44px; flex-shrink:0; display:flex; align-items:center; justify-content:center; border-radius:var(--md-shape-full); background:var(--md-sys-color-surface-container-high); color:var(--md-sys-color-on-surface-variant); cursor:pointer;">${icone(
      'chevronLeft',
      16
    )}</div>
          <div id="mxm-log-resumo-slides-progresso" style="flex:1; display:flex; align-items:center; justify-content:center; font-size:11px; font-weight:600; color:var(--md-sys-color-outline);"></div>
          <div id="mxm-log-resumo-slides-next" title="${escapeHtml(
            t('resumoSlidesProximo')
          )}" style="width:44px; flex-shrink:0; display:flex; align-items:center; justify-content:center; border-radius:var(--md-shape-full); background:var(--md-sys-color-primary); color:var(--md-sys-color-on-primary); cursor:pointer;">${icone(
      'chevronRight',
      16,
      'var(--md-sys-color-on-primary)'
    )}</div>
        </div>
        <div id="mxm-log-resumo-slides-comecar-wrap" class="mxm-slide-texto-entra-cima" style="display:none; animation-delay:260ms; padding:0 18px 20px;">
          <button id="mxm-log-resumo-slides-comecar" type="button" style="width:100%; border:none; cursor:pointer; padding:13px; border-radius:var(--md-shape-full); background:var(--md-sys-color-primary); color:var(--md-sys-color-on-primary); font-family:inherit; font-size:13.5px; font-weight:700; display:flex; align-items:center; justify-content:center; gap:8px;">${escapeHtml(
      t('resumoSlidesComecar')
    )}${icone('chevronRight', 15, 'var(--md-sys-color-on-primary)')}</button>
        </div>
      </div>
    `;

    document.body.appendChild(overlay);
    const cartao = document.getElementById('mxm-log-resumo-slides-cartao');
    animarEntradaCartao(cartao, { distancia: 8, duracao: 180 });

    // PoC preview Apple Music — só um preview real tocando por vez,
    // compartilhado entre os slides via get/set (ver ligarBotaoPreviewAppleMusic).
    let audioPreviewAtivo = null;
    function pararPreviewAppleMusic() {
      if (audioPreviewAtivo) {
        audioPreviewAtivo.pause();
        audioPreviewAtivo = null;
      }
    }

    const RESUMO_MUSICA_VOLUME = 0.16;
    const musicaResumo = new Audio(browser.runtime.getURL('sounds/resumo-musica.mp3'));
    musicaResumo.loop = true;
    musicaResumo.volume = RESUMO_MUSICA_VOLUME;
    musicaResumo.muted = isResumoMusicaMutado();
    musicaResumo.play().catch(() => {});

    const botaoMutarMusica = document.getElementById('mxm-log-resumo-slides-mutar');
    if (botaoMutarMusica) {
      botaoMutarMusica.addEventListener('click', () => {
        const novoMutado = !musicaResumo.muted;
        musicaResumo.muted = novoMutado;
        setResumoMusicaMutado(novoMutado);
        botaoMutarMusica.innerHTML = icone(novoMutado ? 'volumeX' : 'volume2', 13, '#fff');
        botaoMutarMusica.title = novoMutado ? t('resumoMusicaAtivar') : t('resumoMusicaSilenciar');
        tocarSom('clique');
      });
    }

    const conteudoEl = document.getElementById('mxm-log-resumo-slides-conteudo');
    const progressoEl = document.getElementById('mxm-log-resumo-slides-progresso');
    const dots = Array.from(cartao.querySelectorAll('.mxm-slide-dot'));
    const fills = Array.from(cartao.querySelectorAll('.mxm-slide-dot-fill'));
    const navEl = document.getElementById('mxm-log-resumo-slides-nav');
    const comecarWrapEl = document.getElementById('mxm-log-resumo-slides-comecar-wrap');
    const btnComecar = document.getElementById('mxm-log-resumo-slides-comecar');
    const btnPrev = document.getElementById('mxm-log-resumo-slides-prev');
    const btnNext = document.getElementById('mxm-log-resumo-slides-next');

    let comecouSlides = false;

    const DURACAO_AUTOPLAY_MS = 5000;
    let timerAutoplay = null;

    function pararAutoplay() {
      if (timerAutoplay) {
        clearTimeout(timerAutoplay);
        timerAutoplay = null;
      }
    }

    function iniciarAutoplay() {
      pararAutoplay();
      // capa (índice 0) só conta tempo depois de "Começar" apertado —
      // senão o carrossel avançaria sozinho por cima do bloqueio.
      if (indice === 0 && !comecouSlides) return;
      if (indice >= slides.length - 1) return;
      timerAutoplay = setTimeout(() => irPara(indice + 1), DURACAO_AUTOPLAY_MS);
    }

    function atualizarBarrinhas() {
      const ultimoSlide = indice === slides.length - 1;
      const capaTravada = indice === 0 && !comecouSlides;
      fills.forEach((fill, i) => {
        fill.style.transition = 'none';
        if (i < indice) {
          fill.style.width = '100%';
        } else if (i > indice) {
          fill.style.width = '0%';
        } else if (capaTravada) {
          // barrinha da capa fica parada em 0% enquanto o usuário não
          // aperta "Começar" — sem animar, já que não há cronômetro rodando.
          fill.style.width = '0%';
        } else if (ultimoSlide) {
          // último slide: marca como "visto" na hora, sem cronômetro.
          fill.style.width = '100%';
        } else {
          fill.style.width = '0%';
          // força reflow pra garantir que o navegador registre o 0%
          // antes de ligar a transição — senão ele "pula" direto pro
          // 100% sem animar (mesmo truque usado em animarEntradaCartao).
          void fill.offsetWidth;
          fill.style.transition = `width ${DURACAO_AUTOPLAY_MS}ms linear`;
          requestAnimationFrame(() => {
            fill.style.width = '100%';
          });
        }
      });
    }

    function renderizar(direcao) {
      // troca de slide encerra qualquer preview de música tocando —
      // senão a faixa antiga continuaria tocando por cima do slide novo.
      pararPreviewAppleMusic();
      conteudoEl.innerHTML = renderSlideConteudo(slides[indice]);
      progressoEl.textContent = `${indice + 1} / ${slides.length}`;
      atualizarBarrinhas();
      iniciarAutoplay();

      if (slides[indice].previewTitulo) {
        ligarBotaoPreviewAppleMusic(
          slides[indice],
          () => audioPreviewAtivo,
          (audio) => {
            audioPreviewAtivo = audio;
          }
        );
      }

      // V3.5.10.1: direção da transição (definida por quem chamou
      // renderizar — ver irPara) escolhe se o slide novo entra deslizando
      // da direita (avançando) ou da esquerda (voltando), em vez de
      // sempre subir de baixo — mesma sensação de "folhear" um story de
      // verdade. Sem direção (ex: primeiro render da capa, que não tem
      // "de onde vir"), cai na entrada antiga (fade + leve subida).
      conteudoEl.classList.remove('mxm-slide-conteudo-entra', 'mxm-slide-entra-direita', 'mxm-slide-entra-esquerda');
      void conteudoEl.offsetWidth;
      if (direcao === 'frente') conteudoEl.classList.add('mxm-slide-entra-direita');
      else if (direcao === 'tras') conteudoEl.classList.add('mxm-slide-entra-esquerda');
      else conteudoEl.classList.add('mxm-slide-conteudo-entra');

      // chegou no slide final ("Isso foi {mes}!") — chuva de
      // confete comemorando o fechamento da retrospectiva.
      if (slides[indice].tipo === 'final') {
        dispararConfete(conteudoEl);
      }

      if (slides[indice].dinheiro || slides[indice].contagemAnimada) {
        animarNumeroDinheiro(document.getElementById('mxm-slide-valor-numero'));
      } else if (slides[indice].textoFundoAnimado) {
        // slide de letra mais longa/curta ou de missão com
        // mais/menos envios — dispara junto a contagem do selo e o fundo
        // de "texto se escrevendo".
        animarContagemETextoFundo(
          document.getElementById('mxm-slide-contagem-animada'),
          document.getElementById('mxm-slide-texto-fundo-animado'),
          slides[indice].textoFundoAnimado
        );
      }

      // na capa (ainda não iniciada), a barra prev/progresso/next
      // normal some e dá lugar ao botão "Começar" full-width — sinal
      // visual claro de que esse slide não se navega como os outros.
      const capaTravada = indice === 0 && !comecouSlides;
      navEl.style.display = capaTravada ? 'none' : 'flex';
      comecarWrapEl.style.display = capaTravada ? 'block' : 'none';
      if (capaTravada) return;

      btnPrev.style.visibility = indice === 0 ? 'hidden' : 'visible';
      const ultimoSlide = indice === slides.length - 1;
      btnNext.innerHTML = ultimoSlide
        ? icone('eye', 16, 'var(--md-sys-color-on-primary)')
        : icone('chevronRight', 16, 'var(--md-sys-color-on-primary)');
      btnNext.title = ultimoSlide ? t('resumoSlidesVerCompleto') : t('resumoSlidesProximo');
    }

    function irPara(novoIndice) {
      // bloqueia sair da capa (índice 0) pra qualquer outro slide
      // por qualquer via (bolinha, seta, swipe) enquanto "Começar" não foi
      // apertado — só o botão comecar() abaixo consegue destravar.
      if (indice === 0 && !comecouSlides && novoIndice !== 0) return;
      const indiceAnterior = indice;
      indice = Math.max(0, Math.min(slides.length - 1, novoIndice));
      if (indice === indiceAnterior) return;
      renderizar(indice > indiceAnterior ? 'frente' : 'tras');
    }

    function comecar() {
      comecouSlides = true;
      tocarSom('clique');
      irPara(1);
    }

    const fechar = () => {
      pararAutoplay();
      pararPreviewAppleMusic();
      musicaResumo.pause();
      musicaResumo.currentTime = 0;
      document.removeEventListener('keydown', aoTeclado);
      fecharOverlayAnimado(overlay, cartao, { distancia: 8, duracao: 180 });
    };

    btnComecar.addEventListener('click', comecar);
    btnPrev.addEventListener('click', () => irPara(indice - 1));
    btnNext.addEventListener('click', () => {
      if (indice === slides.length - 1) {
        tocarSom('clique');
        fechar();
        abrirPainelResumoDetalhado(mesAnoChave, resumo);
      } else {
        irPara(indice + 1);
      }
    });
    dots.forEach((dot) => dot.addEventListener('click', () => irPara(parseInt(dot.dataset.i, 10))));
    document.getElementById('mxm-log-resumo-slides-fechar').addEventListener('click', () => {
      tocarSom('fechar');
      fechar();
    });

    // teclado: setas pra navegar, Esc pra fechar — só enquanto esse
    // overlay estiver na tela (listener é removido em fechar()).
    function aoTeclado(e) {
      if (e.key === 'ArrowRight') irPara(indice + 1);
      else if (e.key === 'ArrowLeft') irPara(indice - 1);
      else if (e.key === 'Escape') fechar();
    }
    document.addEventListener('keydown', aoTeclado);

    // arraste simples (touch) — sem lib nenhuma, só compara a posição X do
    // dedo entre touchstart e touchend; um arraste maior que 40px conta
    // como troca de slide, senão é ignorado (evita trocar sozinho com um
    // toque tremido).
    let touchStartX = null;
    cartao.addEventListener(
      'touchstart',
      (e) => {
        touchStartX = e.touches[0].clientX;
        // segurou a tela, a barrinha para de encher — igual
        // stories, pra não trocar de slide sozinho no meio do gesto.
        pararAutoplay();
      },
      { passive: true }
    );
    cartao.addEventListener(
      'touchend',
      (e) => {
        if (touchStartX === null) {
          iniciarAutoplay();
          return;
        }
        const deltaX = e.changedTouches[0].clientX - touchStartX;
        touchStartX = null;
        if (Math.abs(deltaX) < 40) {
          // só soltou sem arrastar de verdade — retoma de onde parou.
          iniciarAutoplay();
          return;
        }
        if (deltaX < 0) irPara(indice + 1);
        else irPara(indice - 1);
      },
      { passive: true }
    );

    // mesma pausa do toque, só que pra quem usa mouse — clicou e
    // segurou em cima do cartão, a barrinha para; soltou, retoma.
    cartao.addEventListener('mousedown', () => pararAutoplay());
    cartao.addEventListener('mouseup', () => iniciarAutoplay());
    cartao.addEventListener('mouseleave', () => {
      if (timerAutoplay === null) iniciarAutoplay();
    });

    renderizar();
  }


  // abrirPromptResumoMensal, mas sob demanda (menu da extensão ou botão no
  // painel Reward) e pro mês EM ANDAMENTO, não pro mês que acabou de virar.
  // Como o mês ainda não fechou, o retrato aqui é sempre recalculado ao
  // vivo a partir do log (calcularResumoDoMes) — nunca lido de um resumo já
  // salvo — e o botão de salvar é opcional: serve pra quem quer fixar um
  // "corte" do mês antes do fim dele (ex: comparar a metade de um mês com a
  // metade de outro), sabendo que salvar de novo mais tarde (inclusive na
  // virada automática) substitui esse valor pelo total final.
  function abrirResumoAtual() {
    const mesAnoChave = chaveCicloAtual();
    const resumo = calcularResumoDoMes(mesAnoChave);
    abrirResumoSlides(mesAnoChave, resumo);
  }

  function abrirPainelResumoDetalhado(mesAnoChave, resumo) {
    garantirCotacaoAtualizada();
    document.querySelectorAll('#mxm-log-resumo-atual-overlay').forEach((el) => el.remove());

    const overlay = document.createElement('div');
    overlay.id = 'mxm-log-resumo-atual-overlay';
    Object.assign(overlay.style, {
      position: 'fixed',
      inset: '0',
      background: 'color-mix(in srgb, var(--md-sys-color-scrim) 60%, transparent)',
      zIndex: proximoZIndexFlutuante(),
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
    });

    const detalhesHtml = renderDetalhesResumoMes(resumo);
    // V3.5.58: o botão muda de texto quando já existe um resumo salvo
    // pra este mês — deixa claro que a ação é atualizar um corte já
    // existente, não "salvar pela primeira vez" (ver comentário no
    // handler de clique logo abaixo, que já tratava esse caso ao
    // pedir confirmação de sobrescrita).
    const jaTemResumoSalvo = !!getResumosMensais()[mesAnoChave];
    const textoBotaoSalvar = jaTemResumoSalvo ? t('resumoAtualBotaoAtualizar') : t('resumoAtualBotaoSalvar');

    overlay.innerHTML = `
      <div style="background:var(--md-sys-color-surface-container-low); color:var(--md-sys-color-on-surface); width:360px; max-width:90vw; max-height:88vh; border-radius:var(--md-shape-xl); box-shadow:var(--md-elevation-3); font-family:sans-serif; overflow:hidden; display:flex; flex-direction:column;">
        <div style="padding:20px 20px 14px; display:flex; align-items:flex-start; gap:12px; flex-shrink:0;">
          <div style="width:40px; height:40px; border-radius:var(--md-shape-lg); background:var(--md-sys-color-primary-container); display:flex; align-items:center; justify-content:center; flex-shrink:0;" class="mxm-icone-pop">${icone(
            'eye',
            19,
            'var(--md-sys-color-on-primary-container)'
          )}</div>
          <div style="min-width:0; flex:1;">
            <div style="font-size:15px; font-weight:700; margin-bottom:5px;">${t('resumoAtualTitulo')}</div>
            <span style="display:inline-flex; padding:3px 10px; border-radius:var(--md-shape-full); background:var(--md-sys-color-surface-container-high); font-size:11px; font-weight:600; color:var(--md-sys-color-on-surface-variant);">${formatarRotuloMes(
              mesAnoChave
            )}</span>
          </div>
          <div id="mxm-log-resumo-atual-slides" title="${escapeHtml(
            t('resumoAtualVerSlides')
          )}" style="width:34px; height:34px; border-radius:50%; background:var(--md-sys-color-surface-container-high); color:var(--md-sys-color-primary); display:flex; align-items:center; justify-content:center; flex-shrink:0; cursor:pointer;">${icone(
      'sparkles',
      16,
      'var(--md-sys-color-primary)'
    )}</div>
        </div>
        <div style="padding:2px 20px 6px; display:flex; flex-direction:column; gap:10px; overflow-y:auto; min-height:0;">
          <div style="background:${corDeFundoCartaoDestaque()}; border-radius:var(--md-shape-lg); padding:16px; overflow:hidden;">
            <div style="font-size:11px; font-weight:700; letter-spacing:.3px; text-transform:uppercase; color:var(--md-sys-color-on-surface-variant); margin-bottom:4px;">${getSecondaryCurrencyCode()}</div>
            <div style="font-size:30px; font-weight:800; color:#f2b705; line-height:1.1; word-break:break-word;">${simboloMoeda(
              getSecondaryCurrencyCode()
            )}${(resumo.valorUSD * usdToSecondary).toFixed(2)}</div>
          </div>
          <div style="display:flex; gap:10px;">
            <div style="flex:1; background:var(--md-sys-color-surface-container-high); border-radius:var(--md-shape-lg); padding:12px 14px; min-width:0; overflow:hidden;">
              <div style="font-size:10.5px; font-weight:700; text-transform:uppercase; letter-spacing:.3px; color:var(--md-sys-color-on-surface-variant); margin-bottom:4px;">USD</div>
              <div style="font-size:19px; font-weight:800; color:#1DB954; white-space:nowrap;">$${resumo.valorUSD.toFixed(
                2
              )}</div>
            </div>
            <div style="flex:1; background:var(--md-sys-color-surface-container-high); border-radius:var(--md-shape-lg); padding:12px 14px; min-width:0; overflow:hidden;">
              <div style="font-size:10.5px; font-weight:700; text-transform:uppercase; letter-spacing:.3px; color:var(--md-sys-color-on-surface-variant); margin-bottom:4px;">${t(
                'tarefasAbrev'
              )}</div>
              <div style="font-size:19px; font-weight:800; color:var(--md-sys-color-primary); white-space:nowrap;">${resumo.quantidade}</div>
            </div>
          </div>
          ${detalhesHtml}
        </div>
        <div style="display:flex; gap:8px; padding:18px 20px 20px; flex-shrink:0;">
          <button id="mxm-log-resumo-atual-fechar" style="flex:1; padding:10px; border-radius:var(--md-shape-full); border:none; background:var(--md-sys-color-surface-container-high); color:var(--md-sys-color-on-surface-variant); font-size:13px; font-weight:600; cursor:pointer;">${t(
            'resumoAtualFechar'
          )}</button>
          <button id="mxm-log-resumo-atual-salvar" style="flex:1; padding:10px; border-radius:var(--md-shape-full); border:none; background:var(--md-sys-color-primary); color:var(--md-sys-color-on-primary); font-size:13px; font-weight:700; cursor:pointer;">${textoBotaoSalvar}</button>

        </div>
      </div>
    `;

    document.body.appendChild(overlay);
    const cartao = overlay.firstElementChild;
    animarEntradaCartao(cartao, { distancia: 8, duracao: 180 });

    document.getElementById('mxm-log-resumo-atual-fechar').addEventListener('click', () => {
      tocarSom('fechar');
      fecharOverlayAnimado(overlay, cartao, { distancia: 8, duracao: 180 });
    });
    // "ver em slides" — fecha o cartão compacto e abre o carrossel
    // de slides em cima do mesmo resumo (mesmo objeto `resumo`, já
    // calculado, sem recalcular nada de novo).
    document.getElementById('mxm-log-resumo-atual-slides').addEventListener('click', () => {
      tocarSom('clique');
      fecharOverlayAnimado(overlay, cartao, { distancia: 8, duracao: 180 });
      abrirResumoSlides(mesAnoChave, resumo);
    });
    document.getElementById('mxm-log-resumo-atual-salvar').addEventListener('click', () => {
      const salvarAgora = () => {
        salvarResumoMensal(mesAnoChave, resumo);
        marcarMesPerguntado(mesAnoChave);
        fecharOverlayAnimado(overlay, cartao, { distancia: 8, duracao: 180 });
        mostrarToastSimples(preencherTemplate(t('resumoMensalSalvoToast'), { mes: formatarRotuloMes(mesAnoChave) }));
        if (document.getElementById('mxm-log-reward-conteudo')) renderPainelReward();
      };

      if (getResumosMensais()[mesAnoChave]) {
        abrirConfirmacao({
          titulo: t('resumoAtualBotaoAtualizar'),
          mensagem: t('resumoAtualConfirmarSobrescrever'),
          textoConfirmar: t('resumoAtualBotaoAtualizar'),
          aoConfirmar: salvarAgora,
        });
      } else {
        salvarAgora();
      }
    });
  }

  // Roda uma vez ao carregar a página: compara o "MM/AAAA" salvo da última
  // vez que o script rodou com o mês ATUAL. Se mudou, o mês salvo é o que
  // acabou de terminar — oferece guardar o resumo dele (só se teve pelo
  // menos 1 música enviada, e só se ainda não perguntou sobre esse mês
  // antes). Sempre atualiza o "mês visto" pro atual em seguida, inclusive
  // no primeiro uso do script (quando ainda não havia nada salvo).
  function verificarViradaDeMes() {
    const agora = mxmAgora();
    const mesAtualChave = chaveCicloAtual();
    const mesVistoChave = GM_getValue(STORAGE_MES_VISTO_KEY, null);

    if (mesVistoChave && mesVistoChave !== mesAtualChave) {
      const jaPerguntado = getMesesPerguntados().includes(mesVistoChave);
      const jaSalvo = Boolean(getResumosMensais()[mesVistoChave]);
      if (!jaPerguntado && !jaSalvo) {
        const resumo = calcularResumoDoMes(mesVistoChave);
        if (resumo.quantidade > 0) {
          abrirPromptResumoMensal(mesVistoChave, resumo);
        }
      }
    }

    GM_setValue(STORAGE_MES_VISTO_KEY, mesAtualChave);
    // mês virou → o resumo do mês anterior pode ter passado a
    // aparecer (ou sumido, se já foi salvo/perguntado acima) na lista de
    // notificações; atualiza o badge sem precisar reabrir o painel.
    atualizarBadgeNotificacoes();
  }

  const STORAGE_AVISO_TROCA_CICLO_CONFIRMADO_KEY = 'mxm_log_aviso_troca_ciclo_confirmado';

  function getAvisoTrocaCicloConfirmado() {
    return GM_getValue(STORAGE_AVISO_TROCA_CICLO_CONFIRMADO_KEY, null);
  }

  function confirmarAvisoTrocaCiclo(mesAnoChave) {
    GM_setValue(STORAGE_AVISO_TROCA_CICLO_CONFIRMADO_KEY, mesAnoChave);
  }

  // A janela real em que o banner deve aparecer é exatamente a mesma que
  // horasRestantesNoMes já calcula (desconta o OFFSET_VIRADA_CICLO_MS): a
  // partir do momento em que faltarem 0h ou menos pro fim do mês — ou
  // seja, 21h de Brasília do último dia — até a virada de CALENDÁRIO (meia-
  // noite), quando horasRestantesNoMes passa a ser calculado sobre o mês
  // novo e volta a dar positivo sozinho, escondendo o banner sem precisar
  // de nenhum controle extra de horário aqui.
  function deveMostrarAvisoTrocaCiclo() {
    const agora = mxmAgora();
    if (horasRestantesNoMes(agora) > 0) return false;
    // cicloFechando: mês de CALENDÁRIO puro (ainda não passou de dia) — é
    // esse o ciclo que está prestes a fechar de verdade, mesmo que
    // chaveCicloAtual() já esteja contando o mês seguinte a essa altura.
    const cicloFechando = chaveMesAno(agora);
    return getAvisoTrocaCicloConfirmado() !== cicloFechando;
  }


  // Lista simples (mais recente primeiro) dos resumos já guardados, com
  // botão de apagar em cada linha — é essa lista que dá pra usar pra
  // comparar qualquer mês fechado com qualquer outro.
  function renderResumosMensais() {
    garantirCotacaoAtualizada();
    const moedaAtual = getSecondaryCurrencyCode();
    const simboloAtual = simboloMoeda(moedaAtual);
    const resumos = getResumosMensais();
    const chaves = Object.keys(resumos).sort((a, b) => {
      const [ma, aa] = a.split('/').map(Number);
      const [mb, ab] = b.split('/').map(Number);
      return ab - aa || mb - ma;
    });

    if (!chaves.length) {
      return `<div style="color:var(--md-sys-color-outline); font-size:12px; padding:6px 0;">${t('resumosMensaisVazio')}</div>`;
    }

    // valor máximo entre os resumos exibidos — só pra desenhar a barra
    // proporcional abaixo de cada card (maior mês = barra cheia), o
    // mesmo tratamento visual usado nos cartões da tela "Ciclos"
    // (cartaoCiclo/renderPainelCiclos), reaproveitado aqui pra dar a
    // mesma leitura rápida de "qual mês rendeu mais" à primeira vista.
    const maiorValorUSD = Math.max(1, ...chaves.map((c) => Number(resumos[c].valorUSD || 0)));

    return chaves
      .map((chave) => {
        const r = resumos[chave];
        const rotulo = formatarRotuloMes(chave);
        const [mesAbrev, anoAbrev] = rotulo.split('/');
        const valorUSD = Number(r.valorUSD || 0);
        const barraPct = Math.round((valorUSD / maiorValorUSD) * 100);
        return `
        <div class="mxm-resumo-mensal-linha" data-chave="${chave}" style="padding:12px 14px; margin-bottom:8px; border-radius:var(--md-shape-lg); background:var(--md-sys-color-surface-container); font-size:13px;">
          <div style="display:flex; align-items:center; gap:12px;">
            <div style="width:38px; height:38px; border-radius:var(--md-shape-md); flex-shrink:0; background:var(--md-sys-color-surface-container-high); display:flex; flex-direction:column; align-items:center; justify-content:center; color:var(--md-sys-color-primary); line-height:1;">
              <span style="font-size:9px; font-weight:700; text-transform:uppercase; letter-spacing:.3px;">${escapeHtml(mesAbrev || '')}</span>
              <span style="font-size:11px; font-weight:700; color:var(--md-sys-color-on-surface); margin-top:2px;">${escapeHtml(anoAbrev || '')}</span>
            </div>
            <div style="flex:1; min-width:0; display:flex; flex-direction:column; gap:2px;">
              <span style="color:var(--md-sys-color-on-surface); font-weight:600; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${escapeHtml(rotulo)}</span>
              <span style="font-size:11px; color:var(--md-sys-color-on-surface-variant);">${r.quantidade} ${t('tarefasAbrev')}</span>
            </div>
            <div style="text-align:right; flex-shrink:0;">
              <div style="font-size:18px; font-weight:800; color:var(--md-sys-color-on-surface); line-height:1.1; font-variant-numeric:tabular-nums; white-space:nowrap;">${simboloAtual}${formatarNumeroMoeda(valorUSD * usdToSecondary, moedaAtual)}</div>
              <div style="font-size:10px; color:var(--md-sys-color-outline); font-variant-numeric:tabular-nums;">$${formatarNumeroMoeda(valorUSD, 'USD')}</div>
            </div>
            <div style="display:flex; align-items:center; gap:2px; flex-shrink:0;">
              <span class="mxm-resumo-mensal-rever" title="${t('resumosMensaisRever')}" style="cursor:pointer; display:flex; align-items:center; justify-content:center; width:28px; height:28px; border-radius:var(--md-shape-full); background:transparent; color:var(--md-sys-color-outline); flex-shrink:0; transition:background-color .15s ease, color .15s ease;">${icone(
                'eye',
                13
              )}</span>
              <span class="mxm-resumo-mensal-apagar" title="${t('resumosMensaisApagar')}" style="cursor:pointer; display:flex; align-items:center; justify-content:center; width:28px; height:28px; border-radius:var(--md-shape-full); background:transparent; color:var(--md-sys-color-outline); flex-shrink:0; transition:background-color .15s ease, color .15s ease;">${icone(
                'trash',
                13
              )}</span>
            </div>
          </div>
          <div style="height:4px; border-radius:4px; background:var(--md-sys-color-surface-container-highest); overflow:hidden; margin-top:10px;">
            <div style="height:100%; width:${barraPct}%; border-radius:4px; background:var(--md-sys-color-primary);"></div>
          </div>
        </div>
      `;
      })
      .join('');
  }

  function calcularComparativoDiaEquivalente(porData) {
    const hoje = mxmAgora();
    const diaHoje = hoje.getDate();
    const hojeQtd = porData[formatDateHora(hoje).data] || 0;

    let mesAnteriorNum = hoje.getMonth() - 1;
    let anoAnterior = hoje.getFullYear();
    if (mesAnteriorNum < 0) {
      mesAnteriorNum = 11;
      anoAnterior -= 1;
    }
    const ultimoDiaMesAnterior = new Date(anoAnterior, mesAnteriorNum + 1, 0).getDate();
    const diaEquivalente = Math.min(diaHoje, ultimoDiaMesAnterior);
    const dataEquivalenteStr = formatDateHora(new Date(anoAnterior, mesAnteriorNum, diaEquivalente)).data;
    const equivalenteQtd = porData[dataEquivalenteStr] || 0;

    return { hojeQtd, equivalenteQtd, dataEquivalenteStr };
  }

  // Mesmo padrão visual do comparativo mensal — dois cards + variação
  // percentual — só que comparando hoje com o dia equivalente do mês
  // passado, em vez do total dos dois meses inteiros.
  function renderComparativoDiaEquivalente(dados) {
    const { hojeQtd, equivalenteQtd, dataEquivalenteStr } = dados;

    let deltaHtml;
    if (equivalenteQtd > 0) {
      const deltaPct = Math.round(((hojeQtd - equivalenteQtd) / equivalenteQtd) * 100);
      const cor = deltaPct > 0 ? '#1DB954' : deltaPct < 0 ? '#ff6b6b' : 'var(--md-sys-color-outline)';
      const seta = deltaPct > 0 ? '▲' : deltaPct < 0 ? '▼' : '';
      deltaHtml =
        deltaPct === 0
          ? `<span style="color:var(--md-sys-color-outline);">${t('semMudanca')}</span>`
          : `<span style="color:${cor}; font-weight:700;">${seta} ${Math.abs(deltaPct)}%</span> <span style="color:var(--md-sys-color-outline);">${t(
              'emRelacaoAoDiaEquivalente'
            )}</span>`;
    } else {
      deltaHtml = `<span style="color:var(--md-sys-color-outline);">${t('semDadosDiaEquivalente')}</span>`;
    }

    const cardHoje = `
      <div style="flex:1; background:var(--md-sys-color-surface); border-radius:var(--md-shape-sm); padding:12px; min-width:0;">
        <div style="display:flex; align-items:center; gap:5px; font-size:11px; color:var(--md-sys-color-outline); text-transform:uppercase; letter-spacing:.3px;">${icone(
          'calendar',
          11
        )}${t('hoje')}</div>
        <div style="font-size:26px; font-weight:800; color:#1DB954; line-height:1; margin-top:6px;">${hojeQtd}</div>
      </div>
    `;
    const cardEquivalente = `
      <div style="flex:1; background:var(--md-sys-color-surface); border-radius:var(--md-shape-sm); padding:12px; min-width:0;">
        <div style="display:flex; align-items:center; gap:5px; font-size:11px; color:var(--md-sys-color-outline); text-transform:uppercase; letter-spacing:.3px;">${icone(
          'clock',
          11
        )}${t('diaEquivalenteMesPassado')}</div>
        <div style="font-size:26px; font-weight:800; color:var(--md-sys-color-primary); line-height:1; margin-top:6px;">${equivalenteQtd}</div>
        <div style="font-size:10.5px; color:var(--md-sys-color-outline); margin-top:4px;">${dataEquivalenteStr}</div>
      </div>
    `;

    return `
      <div style="display:flex; gap:10px;">${cardHoje}${cardEquivalente}</div>
      <div style="text-align:center; margin-top:10px; padding:8px; background:var(--md-sys-color-surface); border-radius:var(--md-shape-sm); font-size:11.5px;">${deltaHtml}</div>
    `;
  }

  function calcularEstatisticas(entradas) {
    const porMissao = {};
    const porHora = new Array(24).fill(0);
    let maisCurta = null;
    let maisLonga = null;

    entradas.forEach((e) => {
      const missao = e.missao || t('semMissaoIdentificada');
      porMissao[missao] = (porMissao[missao] || 0) + 1;

      if (Number.isFinite(e.duracaoSegundos)) {
        if (!maisCurta || e.duracaoSegundos < maisCurta.duracaoSegundos) maisCurta = e;
        if (!maisLonga || e.duracaoSegundos > maisLonga.duracaoSegundos) maisLonga = e;
      }

      const horaNum = parseInt((e.hora || '').split(':')[0], 10);
      if (!Number.isNaN(horaNum) && horaNum >= 0 && horaNum < 24) porHora[horaNum]++;
    });

    const porData = calcularContagemPorData(entradas);
    const porDataRecorde = calcularContagemPorData(entradas, { ignorarManuais: true });

    return { porMissao, porHora, maisCurta, maisLonga, porData, porDataRecorde };
  }

  // Cards "Hoje" e "Recorde" usados no painel detalhado, seguindo o mesmo
  // padrão visual dos outros cards da tela (fundo var(--md-sys-color-surface), número grande
  // em destaque) — substitui as duas barras de progresso separadas, que
  // ficavam estranhas sempre que um dos dois valores era 0 (barra
  // invisível) ou igual ao maior (barra 100% cheia, virando um bloco sem
  // graça). No lugar, uma única barrinha fina embaixo mostra o quanto o
  // dia de hoje já avançou em direção ao recorde — métrica mais útil e
  // sempre visível (largura mínima garantida mesmo em 0%).
  function renderBarraHojeVsRecorde(porData, porDataRecorde) {
    const hojeStr = formatDateHora(mxmAgora()).data;
    const hojeQtd = porData[hojeStr] || 0;
    const { recordeData, recordeQtd } = calcularRecordeDiario(porDataRecorde || porData);
    const ehRecordeHoje = recordeData === hojeStr && recordeQtd > 0;
    const pctParaRecorde = recordeQtd > 0 ? Math.min(100, Math.round((hojeQtd / recordeQtd) * 100)) : 0;

    const cardHoje = `
      <div style="flex:1; background:var(--md-sys-color-surface); border-radius:var(--md-shape-sm); padding:12px; min-width:0;">
        <div style="display:flex; align-items:center; gap:5px; font-size:11px; color:var(--md-sys-color-outline); text-transform:uppercase; letter-spacing:.3px;">${icone(
          'calendar',
          11
        )}${t('hoje')}</div>
        <div style="display:flex; align-items:baseline; gap:6px; margin-top:6px;">
          <span style="font-size:26px; font-weight:800; color:var(--md-sys-color-primary); line-height:1;">${hojeQtd}</span>
          ${ehRecordeHoje ? icone('flame', 13, 'var(--md-sys-color-tertiary)') : ''}
        </div>
      </div>
    `;

    const cardRecorde = `
      <div style="flex:1; background:var(--md-sys-color-surface); border-radius:var(--md-shape-sm); padding:12px; min-width:0; border:1px solid color-mix(in srgb, var(--md-sys-color-tertiary) 28%, transparent);">
        <div style="display:flex; align-items:center; gap:5px; font-size:11px; color:var(--md-sys-color-outline); text-transform:uppercase; letter-spacing:.3px;">${icone(
          'star',
          11
        )}${t('recorde')}</div>
        <div style="display:flex; align-items:baseline; gap:6px; margin-top:6px;">
          <span style="font-size:26px; font-weight:800; color:var(--md-sys-color-tertiary); line-height:1;">${
            recordeQtd > 0 ? recordeQtd : '—'
          }</span>
        </div>
        <div style="font-size:10.5px; color:var(--md-sys-color-outline); margin-top:4px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${
          recordeData ? formatarRotuloData(recordeData) : t('nenhumAinda')
        }</div>
      </div>
    `;

    const progressoHtml =
      recordeQtd > 0
        ? `
      <div style="margin-top:10px;">
        <div style="display:flex; justify-content:space-between; font-size:10.5px; color:var(--md-sys-color-outline); margin-bottom:4px;">
          <span>${t('progressoRecorde')}</span>
          <span style="color:var(--md-sys-color-on-surface-variant); font-weight:600;">${pctParaRecorde}%</span>
        </div>
        <div style="background:var(--md-sys-color-surface); border-radius:var(--md-shape-sm); height:6px; overflow:hidden;">
          <div style="width:${
            pctParaRecorde > 0 ? Math.max(pctParaRecorde, 4) : 0
          }%; height:100%; background:linear-gradient(90deg,var(--md-sys-color-primary),var(--md-sys-color-tertiary)); border-radius:var(--md-shape-sm); transition:width .3s ease;"></div>
        </div>
      </div>
    `
        : '';

    return `<div style="display:flex; gap:10px;">${cardHoje}${cardRecorde}</div>${progressoHtml}`;
  }

  // Card "Atual vs Recorde" da SEQUÊNCIA de dias seguidos enviando algo —
  // mesmo layout visual do card de volume acima (renderBarraHojeVsRecorde),
  // só que a métrica é continuidade (dias seguidos), não quantidade.
  function renderCardSequencia(porData) {
    const sequenciaAtual = calcularSequenciaAtual(porData);
    const sequenciaRecorde = calcularMaiorSequenciaDias(porData);
    const empatouRecorde = sequenciaAtual > 0 && sequenciaAtual >= sequenciaRecorde;
    const pctParaRecorde = sequenciaRecorde > 0 ? Math.min(100, Math.round((sequenciaAtual / sequenciaRecorde) * 100)) : 0;

    const cardAtual = `
      <div style="flex:1; background:var(--md-sys-color-surface); border-radius:var(--md-shape-sm); padding:12px; min-width:0;">
        <div style="display:flex; align-items:center; gap:5px; font-size:11px; color:var(--md-sys-color-outline); text-transform:uppercase; letter-spacing:.3px;">${icone(
          'calendar',
          11
        )}${t('sequenciaAtualLabel')}</div>
        <div style="display:flex; align-items:baseline; gap:6px; margin-top:6px;">
          <span style="font-size:26px; font-weight:800; color:var(--md-sys-color-primary); line-height:1;">${sequenciaAtual}</span>
          ${empatouRecorde ? icone('flame', 13, 'var(--md-sys-color-tertiary)') : ''}
        </div>
        <div style="font-size:10.5px; color:var(--md-sys-color-outline); margin-top:4px;">${formatarContagemDias(
          sequenciaAtual
        )}</div>
      </div>
    `;

    const cardRecorde = `
      <div style="flex:1; background:var(--md-sys-color-surface); border-radius:var(--md-shape-sm); padding:12px; min-width:0; border:1px solid color-mix(in srgb, var(--md-sys-color-tertiary) 28%, transparent);">
        <div style="display:flex; align-items:center; gap:5px; font-size:11px; color:var(--md-sys-color-outline); text-transform:uppercase; letter-spacing:.3px;">${icone(
          'star',
          11
        )}${t('sequenciaRecordeLabel')}</div>
        <div style="display:flex; align-items:baseline; gap:6px; margin-top:6px;">
          <span style="font-size:26px; font-weight:800; color:var(--md-sys-color-tertiary); line-height:1;">${
            sequenciaRecorde > 0 ? sequenciaRecorde : '—'
          }</span>
        </div>
        <div style="font-size:10.5px; color:var(--md-sys-color-outline); margin-top:4px;">${
          sequenciaRecorde > 0 ? formatarContagemDias(sequenciaRecorde) : t('nenhumAinda')
        }</div>
      </div>
    `;

    const progressoHtml =
      sequenciaRecorde > 0
        ? `
      <div style="margin-top:10px;">
        <div style="display:flex; justify-content:space-between; font-size:10.5px; color:var(--md-sys-color-outline); margin-bottom:4px;">
          <span>${t('progressoSequenciaRecorde')}</span>
          <span style="color:var(--md-sys-color-on-surface-variant); font-weight:600;">${pctParaRecorde}%</span>
        </div>
        <div style="background:var(--md-sys-color-surface); border-radius:var(--md-shape-sm); height:6px; overflow:hidden;">
          <div style="width:${
            pctParaRecorde > 0 ? Math.max(pctParaRecorde, 4) : 0
          }%; height:100%; background:linear-gradient(90deg,var(--md-sys-color-primary),var(--md-sys-color-tertiary)); border-radius:var(--md-shape-sm); transition:width .3s ease;"></div>
        </div>
      </div>
    `
        : '';

    return `<div style="display:flex; gap:10px;">${cardAtual}${cardRecorde}</div>${progressoHtml}`;
  }

  // Heatmap simples (uma linha, 7 células) de quantos envios caem em cada
  // dia da semana, somando todo o histórico — cor com intensidade
  // proporcional ao dia mais movimentado, no mesmo espírito do gráfico de
  // horário de pico, só que por dia da semana em vez de hora do dia.
  function renderHeatmapDiaSemana(porDiaSemana, cor) {
    const corBase = cor || '#1DB954';
    const max = Math.max(1, ...porDiaSemana);
    const rotulos = rotulosDiaSemana();
    const celulas = porDiaSemana
      .map((qtd, idx) => {
        const intensidade = qtd > 0 ? Math.max(0.16, qtd / max) : 0;
        const bg =
          qtd > 0
            ? `color-mix(in srgb, ${corBase} ${Math.round(intensidade * 100)}%, var(--md-sys-color-surface-container-high))`
            : 'var(--md-sys-color-surface-container-high)';
        const corTexto = qtd > 0 && intensidade > 0.55 ? '#0b0b0b' : 'var(--md-sys-color-on-surface-variant)';
        return `
          <div style="display:flex; flex-direction:column; align-items:center; gap:5px; flex:1; min-width:0;">
            <div title="${rotulos[idx]} — ${qtd}" style="width:100%; aspect-ratio:1; max-width:40px; border-radius:var(--md-shape-sm); background:${bg}; display:flex; align-items:center; justify-content:center; font-size:11px; font-weight:700; color:${corTexto}; transition:background .3s ease;">${qtd}</div>
            <div style="font-size:9.5px; color:var(--md-sys-color-outline);">${rotulos[idx]}</div>
          </div>
        `;
      })
      .join('');
    return `<div style="background:var(--md-sys-color-surface); border-radius:var(--md-shape-sm); padding:10px 8px; display:flex; align-items:flex-start; gap:4px;">${celulas}</div>`;
  }

  // Atualiza a barrinha compacta logo abaixo da busca no painel principal
  // (só o essencial: total de hoje + recorde numa linha pequena embaixo).
  function atualizarResumoDia() {
    const resumo = document.getElementById('mxm-log-resumo-dia');
    if (!resumo) return;

    if (!resumo._mxmClickCronometroBind) {
      resumo._mxmClickCronometroBind = true;
      resumo.addEventListener('click', (e) => {
        if (e.target.closest('[data-mxm-abrir-cronometro]')) abrirJanelaCronometroCiclo();
      });
    }

    // "Mostrar resumo do dia" desligado — some com a barrinha
    // inteira (wrap com display:none, sem afetar o resto do layout do
    // painel) e para o timer do carrossel, se estiver rodando.
    const resumoWrapEl = document.getElementById('mxm-log-resumo-dia-wrap');
    if (!isMostrarResumoDia()) {
      if (resumoWrapEl) resumoWrapEl.style.display = 'none';
      if (resumoDiaIntervalId) {
        clearInterval(resumoDiaIntervalId);
        resumoDiaIntervalId = null;
      }
      resumo.innerHTML = '';
      return;
    }
    if (resumoWrapEl) resumoWrapEl.style.display = '';

    const entradas = Object.values(getLogs());
    const porData = calcularContagemPorData(entradas);
    const porDataRecorde = calcularContagemPorData(entradas, { ignorarManuais: true });
    const hojeStr = formatDateHora(mxmAgora()).data;
    const hojeQtd = porData[hojeStr] || 0;
    const { recordeData, recordeQtd } = calcularRecordeDiario(porDataRecorde);
    const ehRecordeHoje = recordeData === hojeStr && recordeQtd > 0;
    const palavraTarefa = t('tarefa');
    const layout = getLayoutResumo();

    const recordeTextoLongo =
      recordeQtd > 0
        ? `${recordeQtd} ${palavraTarefa}${recordeQtd === 1 ? '' : 's'} ${t('em')} ${formatarRotuloData(recordeData)}`
        : t('nenhumAinda');

    // três variações de layout pro resumo do dia, escolhidas pelo
    // usuário no menu de configurações (getLayoutResumo()).
    if (layout === 'chip') {
      resumo.innerHTML = `
        <div data-mxm-resumo-abrir="1" style="display:flex; align-items:center; justify-content:space-between; gap:10px; cursor:pointer;">
          <div style="min-width:0;">
            <div style="display:flex; align-items:center; gap:5px; font-size:12px; color:var(--md-sys-color-on-surface-variant);">${icone(
              'calendar',
              13
            )}${t('tarefasHoje')}</div>
            <div style="display:flex; align-items:center; gap:5px; font-size:10px; color:var(--md-sys-color-outline); margin-top:3px;">
              ${icone('star', 11)}<span>${t('recorde')}: ${recordeTextoLongo}</span>
            </div>
          </div>
          <div style="display:flex; align-items:center; gap:6px; background:color-mix(in srgb, var(--md-sys-color-primary) 14%, transparent); border-radius:var(--md-shape-sm); padding:4px 11px; flex-shrink:0;">
            ${ehRecordeHoje ? icone('flame', 13, 'var(--md-sys-color-tertiary)') : ''}
            <span style="font-size:21px; font-weight:800; color:var(--md-sys-color-primary); line-height:1;">${hojeQtd}</span>
          </div>
        </div>
      `;
    } else if (layout === 'tipografia') {
      resumo.innerHTML = `
        <div data-mxm-resumo-abrir="1" style="display:flex; align-items:center; justify-content:space-between; gap:10px; cursor:pointer;">
          <div style="min-width:0;">
            <div style="display:flex; align-items:center; gap:5px; font-size:12px; color:var(--md-sys-color-on-surface-variant);">${icone(
              'calendar',
              13
            )}${t('tarefasHoje')}</div>
            <div style="display:flex; align-items:center; gap:5px; font-size:10px; color:var(--md-sys-color-outline); margin-top:3px;">
              ${icone('star', 11)}<span>${t('recorde')}: ${recordeTextoLongo}</span>
            </div>
          </div>
          <div style="display:flex; align-items:center; gap:6px; flex-shrink:0;">
            ${ehRecordeHoje ? icone('flame', 13, 'var(--md-sys-color-tertiary)') : ''}
            <span style="font-size:24px; font-weight:800; color:var(--md-sys-color-primary); line-height:1;">${hojeQtd}</span>
          </div>
        </div>
      `;
    } else {
      const compMes = calcularComparativoMensal(entradas);
      const compDia = calcularComparativoDiaEquivalente(porData);

      // comparação hoje vs ontem (mesma base do hojeQtd/recordeQtd —
      // ignora manuais) usada só pela linha de delta do blob orgânico
      // abaixo, no padrão "prototipo-topo-m3-expressive": texto solto,
      // sem caixa/pill em volta, com seta pra cima/baixo.
      const ontemDeltaDate = mxmAgora();
      ontemDeltaDate.setDate(ontemDeltaDate.getDate() - 1);
      const ontemStr = formatDateHora(ontemDeltaDate).data;
      const ontemQtd = porDataRecorde[ontemStr] || 0;
      let deltaHojeOntemHtml = '';
      if (ontemQtd > 0) {
        const deltaPctHojeOntem = Math.round(((hojeQtd - ontemQtd) / ontemQtd) * 100);
        const corDeltaHojeOntem =
          deltaPctHojeOntem > 0 ? '#1DB954' : deltaPctHojeOntem < 0 ? '#ff6b6b' : 'var(--md-sys-color-outline)';
        deltaHojeOntemHtml =
          deltaPctHojeOntem === 0
            ? `<div style="font-size:11px; color:var(--md-sys-color-outline); margin-top:6px;">${t('semMudancaOntem')}</div>`
            : `<div style="display:inline-flex; align-items:center; gap:3px; font-size:11px; font-weight:700; color:${corDeltaHojeOntem}; margin-top:6px;">${icone(
                deltaPctHojeOntem > 0 ? 'trendingUp' : 'trendingDown',
                11,
                corDeltaHojeOntem,
                2.5
              )}${Math.abs(deltaPctHojeOntem)}% ${t('emRelacaoAoDiaAnterior')}</div>`;
      }

      // "blob" orgânico pro número de hoje — a única forma não-retangular
      // do painel, pra puxar o olho sem precisar de mais cor/contraste;
      // o selo de chama de recorde migra pra cima do blob em vez de
      // ficar espremido ao lado do número. Layout replicado 100% do
      // protótipo "topo M3 Expressive": info do lado direito vira texto
      // solto (linha1/linha2/delta), sem o cartão tonal usado nos outros
      // slides do carrossel.
      const slideHojeRecorde = `
        <div data-mxm-resumo-abrir="1" class="mxm-resumo-card-clicavel" style="display:flex; align-items:center; gap:16px;">
          <div style="position:relative; flex-shrink:0; width:76px; height:76px; border-radius:42% 58% 63% 37% / 41% 44% 56% 59%; background:linear-gradient(135deg, var(--md-sys-color-primary), color-mix(in srgb, var(--md-sys-color-tertiary) 70%, var(--md-sys-color-primary))); display:flex; flex-direction:column; align-items:center; justify-content:center; box-shadow:0 4px 14px color-mix(in srgb, var(--md-sys-color-primary) 35%, transparent); transition:border-radius 6s ease-in-out;">
            ${
              ehRecordeHoje
                ? `<div style="position:absolute; top:-4px; right:-4px; display:flex; color:var(--md-sys-color-tertiary); background:var(--md-sys-color-surface-container); border-radius:50%; padding:3px; box-shadow:var(--md-elevation-1);">${icone(
                    'flame',
                    11
                  )}</div>`
                : ''
            }
            <span style="font-size:26px; font-weight:800; color:var(--md-sys-color-on-primary); line-height:1;">${hojeQtd}</span>
            <span style="font-size:9px; font-weight:700; text-transform:lowercase; color:var(--md-sys-color-on-primary); opacity:.85; margin-top:2px;">${t(
              'hoje'
            )}</span>
          </div>
          <div style="min-width:0;">
            <div style="font-size:12.5px; color:var(--md-sys-color-on-surface-variant); overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${t(
              'tarefasEnviadasHoje'
            )}</div>
            <div style="display:flex; align-items:center; gap:5px; font-size:11px; color:var(--md-sys-color-outline); margin-top:4px; min-width:0;">
              ${icone('star', 11)}<span style="overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${t(
                'recorde'
              )}: ${recordeQtd > 0 ? recordeTextoLongo : t('nenhumAinda')}</span>
            </div>
            ${deltaHojeOntemHtml}
          </div>
        </div>
      `;
      const slideMes = `
        <div data-mxm-resumo-abrir="1" class="mxm-resumo-card-clicavel" style="display:flex; gap:6px;">
          ${montarCartaoResumo({
            nomeIcone: 'calendar',
            corToken: 'primary',
            rotulo: t('mesAtual'),
            valor: compMes.mesAtualQtd,
            sublinha: compMes.labelAtual,
          })}
          ${montarCartaoResumo({
            nomeIcone: 'clock',
            corToken: 'tertiary',
            rotulo: t('mesAnterior'),
            valor: compMes.mesAnteriorQtd,
            sublinha: compMes.labelAnterior,
          })}
        </div>
        ${montarLinhaDeltaResumo(compMes.mesAtualQtd, compMes.mesAnteriorQtd, t('semDadosMesAnterior'), t('emRelacaoAoMesAnterior'))}
      `;
      const slideDia = `
        <div data-mxm-resumo-abrir="1" class="mxm-resumo-card-clicavel" style="display:flex; gap:6px;">
          ${montarCartaoResumo({
            nomeIcone: 'calendar',
            corToken: 'primary',
            rotulo: t('hoje'),
            valor: compDia.hojeQtd,
          })}
          ${montarCartaoResumo({
            nomeIcone: 'clock',
            corToken: 'tertiary',
            rotulo: t('diaEquivalenteMesPassado'),
            valor: compDia.equivalenteQtd,
            sublinha: compDia.dataEquivalenteStr,
          })}
        </div>
        ${montarLinhaDeltaResumo(compDia.hojeQtd, compDia.equivalenteQtd, t('semDadosDiaEquivalente'), t('emRelacaoAoDiaEquivalente'))}
      `;

      const slideCronometro = `
        <div data-mxm-abrir-cronometro="1" title="${t('proximoCicloDescricao')}" class="mxm-resumo-card-clicavel" style="display:flex; align-items:center; gap:12px; background:color-mix(in srgb, var(--md-sys-color-primary) 13%, var(--md-sys-color-surface-container-low)); border-radius:var(--md-shape-lg); padding:12px 14px;">
          <div style="flex-shrink:0; width:34px; height:34px; border-radius:50%; background:color-mix(in srgb, var(--md-sys-color-primary) 24%, transparent); display:flex; align-items:center; justify-content:center; color:var(--md-sys-color-primary);">${icone(
            'clock',
            16
          )}</div>
          <div style="min-width:0;">
            <div style="font-size:10.5px; font-weight:600; text-transform:uppercase; letter-spacing:.3px; color:var(--md-sys-color-on-surface-variant);">${t(
              'proximoCicloTitulo'
            )}</div>
            <div style="font-size:19px; font-weight:800; color:var(--md-sys-color-primary); line-height:1.25; font-variant-numeric:tabular-nums; margin-top:2px;"><span id="mxm-log-cronometro-ciclo-valor">${formatarContagemRegressiva(
              proximoInicioCiclo() - mxmAgora()
            )}</span></div>
            <div title="${t('cronometroEstiloSiteTooltip')}" style="font-size:10.5px; font-weight:600; color:var(--md-sys-color-on-surface-variant); margin-top:1px; font-variant-numeric:tabular-nums;">⏰ <span id="mxm-log-cronometro-ciclo-valor-site">${formatarDiasEstiloSite(
              proximoInicioCiclo()
            )}</span> (${t('cronometroEstiloSiteLabel')})</div>
            <div style="font-size:10px; color:var(--md-sys-color-on-surface-variant); margin-top:3px; line-height:1.35; overflow:hidden; display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical;">${t(
              'proximoCicloDescricao'
            )}</div>
          </div>
        </div>
      `;

      const slidesBase = isCarrosselResumoAtivo() ? [slideHojeRecorde, slideMes, slideDia] : [slideHojeRecorde];
      const slidesResumo = isCronometroCicloMainAtivo() ? [...slidesBase, slideCronometro] : slidesBase;
      renderizarResumoRotativo(resumo, slidesResumo);
    }

    if (layout !== 'lado_a_lado' && resumoDiaIntervalId) {
      // trocou pra um layout sem carrossel (chip/tipografia) — não faz
      // sentido o timer continuar rodando "no vazio" tentando animar um
      // elemento que não existe mais.
      clearInterval(resumoDiaIntervalId);
      resumoDiaIntervalId = null;
      // o ícone de pino também some junto (só existe no layout
      // 'lado_a_lado') — esconde o balão de apresentação, se estava aberto.
      esconderPopupPinoCronometro();
    }

    // recalcula a altura expandida do wrap com base no conteúdo que
    // acabou de ser renderizado, pra barrinha nunca ficar cortada (ver
    // sincronizarAlturaResumoWrap, atribuída ao abrir o painel).
    if (typeof sincronizarAlturaResumoWrap === 'function') sincronizarAlturaResumoWrap();
  }

  // Monta um cartão tonal M3 (ícone circular + rótulo + valor grande),
  // mesmo padrão visual já usado no resumo do dia — reaproveitado pelos 3
  // slides do carrossel (hoje/recorde, mês atual/anterior, dia
  // equivalente) pra manter a aparência idêntica entre eles.
  function montarCartaoResumo({ nomeIcone, corToken, rotulo, valor, sublinha, extra }) {
    return `
      <div style="flex:1; min-width:0; display:flex; align-items:center; gap:8px; background:color-mix(in srgb, var(--md-sys-color-${corToken}) 13%, var(--md-sys-color-surface-container-low)); border-radius:var(--md-shape-lg); padding:8px 9px;">
        <div style="flex-shrink:0; width:26px; height:26px; border-radius:50%; background:color-mix(in srgb, var(--md-sys-color-${corToken}) 24%, transparent); display:flex; align-items:center; justify-content:center; color:var(--md-sys-color-${corToken});">${icone(
          nomeIcone,
          13
        )}</div>
        <div style="min-width:0;">
          <div style="font-size:9.5px; font-weight:600; text-transform:uppercase; letter-spacing:.2px; color:var(--md-sys-color-on-surface-variant); overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${rotulo}</div>
          <div style="display:flex; align-items:baseline; gap:4px; min-width:0;">
            <span style="font-size:18px; font-weight:800; color:var(--md-sys-color-${corToken}); line-height:1.3; flex-shrink:0;">${valor}</span>
            ${extra || ''}
            ${
              sublinha
                ? `<span style="font-size:9.5px; color:var(--md-sys-color-on-surface-variant); overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${sublinha}</span>`
                : ''
            }
          </div>
        </div>
      </div>
    `;
  }

  function montarLinhaDeltaResumo(valorAtual, valorAnterior, textoSemDados, textoRelacao) {
    if (!(valorAnterior > 0)) return '';
    const deltaPct = Math.round(((valorAtual - valorAnterior) / valorAnterior) * 100);
    const cor = deltaPct > 0 ? '#1DB954' : deltaPct < 0 ? '#ff6b6b' : 'var(--md-sys-color-outline)';
    const seta = deltaPct > 0 ? '▲' : deltaPct < 0 ? '▼' : '';
    const conteudo =
      deltaPct === 0
        ? `<span style="color:var(--md-sys-color-outline);">${t('semMudanca')}</span>`
        : `<span style="color:${cor}; font-weight:700;">${seta} ${Math.abs(deltaPct)}%</span> <span style="color:var(--md-sys-color-outline);">${textoRelacao}</span>`;
    return `<div style="text-align:center; margin-top:6px; padding:5px 8px; background:color-mix(in srgb, var(--md-sys-color-outline-variant) 22%, transparent); border-radius:var(--md-shape-sm); font-size:10.5px;">${conteudo}</div>`;
  }

  function medirAlturasSlides(resumoEl, slides) {
    const larguraRef = resumoEl.clientWidth || resumoEl.offsetWidth || 0;
    if (!larguraRef || !slides || !slides.length) return [];
    const medidor = document.createElement('div');
    medidor.style.cssText = `position:absolute; visibility:hidden; pointer-events:none; left:-9999px; top:-9999px; width:${larguraRef}px;`;
    document.body.appendChild(medidor);
    const alturas = slides.map((html) => {
      medidor.innerHTML = html;
      return medidor.scrollHeight;
    });
    medidor.remove();
    return alturas;
  }

  function renderizarResumoRotativo(resumoEl, slides) {
    resumoEl._mxmSlidesResumo = slides;
    if (resumoEl.dataset.mxmSlideIdx === undefined) resumoEl.dataset.mxmSlideIdx = '0';
    let indiceAtual = Math.min(Number(resumoEl.dataset.mxmSlideIdx), slides.length - 1);

    let slideFixado = getResumoSlideFixado(slides.length);
    if (slideFixado !== null) {
      if (slideFixado < slides.length) {
        indiceAtual = slideFixado;
      } else {
        setResumoSlideFixado(null);
        slideFixado = null;
      }
    }
    resumoEl.dataset.mxmSlideIdx = String(indiceAtual);

    let miolo = resumoEl.querySelector('[data-mxm-resumo-miolo]');
    let dotsWrap = resumoEl.querySelector('[data-mxm-resumo-dots]');
    let botaoFixar = resumoEl.querySelector('[data-mxm-resumo-fixar]');
    let slideAtualEl;
    if (!miolo) {
      // primeira montagem (ou troca de volta pro layout 'lado_a_lado'
      // depois de ter passado por chip/tipografia, que sobrescrevem o
      // innerHTML sem esse wrapper) — monta a estrutura fixa uma vez só;
      // as trocas seguintes de slide só mexem no slide "ativo" lá dentro.
      // overflow:visible nos dois eixos (não "overflow-x:hidden;
      // overflow-y:visible") de propósito: pela própria spec do CSS,
      // combinar um eixo 'hidden' com o outro 'visible' faz o navegador
      // converter o 'visible' pra 'auto' por baixo dos panos — que
      // também recorta. Era exatamente isso que cortava o brilho do
      // blob "hoje" (V3.4.69/70), mesmo com overflow-y:visible escrito
      // no style. O recorte horizontal do vaivém de ±20px na troca de
      // slide agora é contido só pelo overflow:hidden do wrap externo
      // (#mxm-log-resumo-dia-wrap), que já tem respiro suficiente.
      resumoEl.innerHTML = `
        <div data-mxm-resumo-miolo style="position:relative; overflow:visible; border-radius:var(--md-shape-lg); transition:height ${DURACAO_TRANSICAO_SLIDE_RESUMO_MS}ms cubic-bezier(.2,0,0,1);">
          <div data-mxm-resumo-slide data-mxm-atual="1"></div>
        </div>
        ${
          // V3.4.66: setas de navegação, pino de fixar e pontinhos agora
          // moram todos numa única barrinha de controle ABAIXO do slide,
          // em vez de flutuarem por cima do conteúdo (o que espremia/
          // cobria o texto dos cartões nos slides mais estreitos, tipo
          // "mês" e "dia equivalente"). Só existe com mais de 1 slide,
          // igual antes.
          // V3.4.68: virou grid de 3 colunas (1fr/auto/1fr) em vez de
          // flex — como o grupo da direita tem 2 botões (seta + pino)
          // contra só 1 da esquerda (seta), um flex simples deixava os
          // pontinhos puxados pro lado esquerdo em vez de centralizados
          // de verdade na barra.
          slides.length > 1
            ? `
              <div data-mxm-resumo-dots class="mxm-resumo-controles" style="display:grid; grid-template-columns:1fr auto 1fr; align-items:center; margin-top:8px;">
                <button type="button" data-mxm-resumo-seta="anterior" title="${t('resumoSetaAnterior')}" class="mxm-resumo-seta-btn" style="justify-self:start; flex-shrink:0; width:22px; height:22px; border:none; border-radius:50%; display:flex; align-items:center; justify-content:center; cursor:pointer; padding:0;">${icone(
                  'chevronLeft',
                  13
                )}</button>
                <div data-mxm-dots-central class="mxm-resumo-dots-central" style="justify-self:center; display:flex; align-items:center; gap:7px;"></div>
                <div style="justify-self:end; display:flex; align-items:center; gap:2px;">
                  <button type="button" data-mxm-resumo-seta="proxima" title="${t('resumoSetaProxima')}" class="mxm-resumo-seta-btn" style="flex-shrink:0; width:22px; height:22px; border:none; border-radius:50%; display:flex; align-items:center; justify-content:center; cursor:pointer; padding:0;">${icone(
                    'chevronRight',
                    13
                  )}</button>
                  <button type="button" data-mxm-resumo-fixar class="mxm-resumo-fixar-btn" style="flex-shrink:0; width:20px; height:20px; border:none; border-radius:50%; display:flex; align-items:center; justify-content:center; cursor:pointer; padding:0;"></button>
                </div>
              </div>
            `
            : ''
        }
      `;
      miolo = resumoEl.querySelector('[data-mxm-resumo-miolo]');
      dotsWrap = resumoEl.querySelector('[data-mxm-resumo-dots]');
      botaoFixar = resumoEl.querySelector('[data-mxm-resumo-fixar]');
      if (botaoFixar) {
        botaoFixar.addEventListener('click', (e) => {
          e.stopPropagation();
          const atual = Number(resumoEl.dataset.mxmSlideIdx);
          const totalAtual = (resumoEl._mxmSlidesResumo || slides).length;
          const jaFixadoNesse = getResumoSlideFixado(totalAtual) === atual;
          setResumoSlideFixado(jaFixadoNesse ? null : atual);
          tocarSom('clique');
          atualizarBotaoFixarResumo(botaoFixar, getResumoSlideFixado(totalAtual), atual);
          fecharPopupPinoCronometro();
        });

        if (isCronometroCicloMainAtivo() && estaUsandoPinoPadraoCronometro() && !jaViuPopupPinoCronometro()) {
          requestAnimationFrame(() => requestAnimationFrame(() => mostrarPopupPinoCronometro(botaoFixar)));
        }
      }

      // V3.4.64: clique nas setas anterior/próxima — anda um slide na
      // direção escolhida, dando a volta do último pro primeiro (e
      // vice-versa) igual ao giro automático. stopPropagation pra não
      // disparar o clique geral do slide (data-mxm-resumo-abrir/
      // data-mxm-abrir-cronometro), que abriria o painel por baixo.
      const botaoSetaAnterior = resumoEl.querySelector('[data-mxm-resumo-seta="anterior"]');
      const botaoSetaProxima = resumoEl.querySelector('[data-mxm-resumo-seta="proxima"]');
      const irParaSlideRelativo = (passo) => {
        const totalAtual = (resumoEl._mxmSlidesResumo || slides).length;
        if (totalAtual < 2) return;
        const atual = Number(resumoEl.dataset.mxmSlideIdx);
        const proximo = (atual + passo + totalAtual) % totalAtual;
        tocarSom('clique');
        irParaSlideResumo(resumoEl, proximo);
      };
      if (botaoSetaAnterior) {
        botaoSetaAnterior.addEventListener('click', (e) => {
          e.stopPropagation();
          irParaSlideRelativo(-1);
        });
      }
      if (botaoSetaProxima) {
        botaoSetaProxima.addEventListener('click', (e) => {
          e.stopPropagation();
          irParaSlideRelativo(1);
        });
      }
    }
    resumoEl._mxmAlturasSlides = medirAlturasSlides(resumoEl, slides);
    const alturaAtualPx = resumoEl._mxmAlturasSlides[indiceAtual];
    // V3.4.81: mesmo motivo do comentário em irParaSlideResumo — esta
    // atribuição de miolo.style.height roda toda vez que o resumo é
    // atualizado (nova entrada de log, troca de layout), não só na troca
    // de slide do carrossel, e pode mudar a altura do wrap sem que o
    // usuário tenha rolado nada.
    if (typeof ancorarScrollListaAntesDeResize === 'function') ancorarScrollListaAntesDeResize();
    if (alturaAtualPx) miolo.style.height = `${alturaAtualPx}px`;
    // atualiza o conteúdo do slide "ativo" (settled, sem animação) — usado
    // tanto na primeira montagem quanto nas atualizações de dados (novo
    // log registrado) que não são troca de slide. Se por acaso cair no
    // meio de uma transição em andamento (janela de ~340ms), simplesmente
    // não mexe — a transição em curso vai terminar e o próximo refresh de
    // dados (chamado de novo pelo fluxo normal) já traz o valor certo.
    slideAtualEl = miolo.querySelector('[data-mxm-resumo-slide][data-mxm-atual="1"]');
    if (slideAtualEl && !resumoEl._mxmEmTransicao) {
      slideAtualEl.innerHTML = slides[indiceAtual];
    }
    atualizarDotsResumo(dotsWrap, slides.length, indiceAtual);
    if (botaoFixar) atualizarBotaoFixarResumo(botaoFixar, slideFixado, indiceAtual);

    if (slides.length <= 1) {
      // "Girar automaticamente" foi desligado com o painel já aberto —
      // não faz sentido manter o timer rodando só pra ele se checar e não
      // fazer nada a cada 6s.
      if (resumoDiaIntervalId) {
        clearInterval(resumoDiaIntervalId);
        resumoDiaIntervalId = null;
      }
      return;
    }

    if (!resumoDiaIntervalId) {
      resumoDiaIntervalId = setInterval(() => {
        if (resumoEl._mxmResumoPausado) return;
        const total = (resumoEl._mxmSlidesResumo || []).length;
        if (total < 2) return;
        // slide fixado (pino ativo, inclusive o padrão automático
        // da tile do cronômetro) — não gira sozinho.
        if (getResumoSlideFixado(total) !== null) return;
        const proximo = (Number(resumoEl.dataset.mxmSlideIdx) + 1) % total;
        irParaSlideResumo(resumoEl, proximo);
      }, 6000);
      resumoEl.addEventListener('mouseenter', () => {
        resumoEl._mxmResumoPausado = true;
      });
      resumoEl.addEventListener('mouseleave', () => {
        resumoEl._mxmResumoPausado = false;
      });
    }
  }

  function atualizarBotaoFixarResumo(botaoEl, slideFixado, indiceAtual) {
    if (!botaoEl) return;
    const ativo = slideFixado === indiceAtual;
    botaoEl.classList.toggle('mxm-resumo-fixar-ativo', ativo);
    botaoEl.title = ativo ? t('resumoDesfixarSlide') : t('resumoFixarSlide');
    botaoEl.innerHTML = icone('pin', 12, ativo ? 'var(--md-sys-color-primary)' : 'currentColor');
  }

  // guarda se o popup de apresentação do pino padrão (tile do
  // cronômetro nascendo fixada sozinha) já foi visto — some pra sempre
  // depois da primeira vez, mesmo espírito de STORAGE_TOUR_KEY.
  const STORAGE_POPUP_PINO_CRONOMETRO_VISTO_KEY = 'mxm_log_popup_pino_cronometro_visto';

  function jaViuPopupPinoCronometro() {
    return GM_getValue(STORAGE_POPUP_PINO_CRONOMETRO_VISTO_KEY, '0') === '1';
  }

  function marcarPopupPinoCronometroVisto() {
    GM_setValue(STORAGE_POPUP_PINO_CRONOMETRO_VISTO_KEY, '1');
  }

  // Elemento do balão de apresentação — vive no nível do módulo pra poder
  // ser fechado de qualquer lugar (clique no próprio pino, fechamento do
  // painel principal, troca de layout) sem precisar espalhar referência.
  let popupPinoCronometroEl = null;

  // Só tira o balão da tela, sem marcar como "visto" — usado quando o
  // painel fecha ou o botão-alvo some do DOM (troca de layout) por um
  // motivo alheio à leitura do usuário, pra ele poder aparecer de novo na
  // próxima vez que fizer sentido.
  function esconderPopupPinoCronometro() {
    if (popupPinoCronometroEl) {
      popupPinoCronometroEl.remove();
      popupPinoCronometroEl = null;
    }
  }

  // Dispensa de vez — usado quando o próprio usuário interage (botão
  // "Entendi" ou o ícone de pino em si), daí sim marcando como visto pra
  // nunca mais aparecer.
  function fecharPopupPinoCronometro() {
    marcarPopupPinoCronometroVisto();
    esconderPopupPinoCronometro();
  }

  function mostrarPopupPinoCronometro(botaoFixar) {
    if (jaViuPopupPinoCronometro() || popupPinoCronometroEl || !botaoFixar || !botaoFixar.isConnected) return;

    const balao = document.createElement('div');
    Object.assign(balao.style, {
      position: 'fixed',
      zIndex: '2147483001',
      background: 'var(--md-sys-color-surface-container-lowest)',
      color: 'var(--md-sys-color-on-surface)',
      border: '1px solid rgba(255,255,255,0.07)',
      borderLeft: '3px solid var(--md-sys-color-primary)',
      borderRadius: '12px',
      padding: '12px 14px',
      width: '220px',
      boxSizing: 'border-box',
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      fontSize: '12px',
      lineHeight: '1.5',
      boxShadow: 'var(--md-elevation-4)',
      pointerEvents: 'auto',
      opacity: '0',
      transition: 'opacity .18s ease',
    });
    balao.innerHTML = `
      <div style="font-weight:700; margin-bottom:4px; color:var(--md-sys-color-on-surface);">${t('popupPinoCronometroTitulo')}</div>
      <div style="margin-bottom:10px; color:var(--md-sys-color-on-surface-variant);">${t('popupPinoCronometroMensagem')}</div>
      <div style="display:flex; justify-content:flex-end;">
        <button id="mxm-popup-pino-cronometro-ok" style="padding:5px 13px; border-radius:999px; border:none; background:var(--md-sys-color-primary); color:#111; font-size:11.5px; font-weight:600; cursor:pointer;">${t(
          'popupPinoCronometroBotao'
        )}</button>
      </div>
    `;

    const seta = document.createElement('div');
    Object.assign(seta.style, {
      position: 'absolute',
      width: '10px',
      height: '10px',
      background: 'var(--md-sys-color-surface-container-lowest)',
      transform: 'rotate(45deg)',
    });
    balao.appendChild(seta);

    document.body.appendChild(balao);
    popupPinoCronometroEl = balao;

    function posicionar() {
      if (!botaoFixar.isConnected) {
        esconderPopupPinoCronometro();
        return;
      }
      const rect = botaoFixar.getBoundingClientRect();
      const alturaBalao = balao.offsetHeight;
      const larguraBalao = balao.offsetWidth;
      let top = rect.bottom + 12;
      let setaEmCima = true;
      if (top + alturaBalao > window.innerHeight - 10) {
        top = rect.top - 12 - alturaBalao;
        setaEmCima = false;
      }
      top = Math.max(10, Math.min(top, window.innerHeight - alturaBalao - 10));
      const centroAlvo = rect.left + rect.width / 2;
      let left = centroAlvo - larguraBalao + 24;
      left = Math.max(10, Math.min(left, window.innerWidth - larguraBalao - 10));
      balao.style.top = `${top}px`;
      balao.style.left = `${left}px`;
      let setaLeft = centroAlvo - left - 5;
      setaLeft = Math.max(12, Math.min(setaLeft, larguraBalao - 22));
      seta.style.left = `${setaLeft}px`;
      if (setaEmCima) {
        seta.style.top = '-5px';
        seta.style.bottom = '';
      } else {
        seta.style.bottom = '-5px';
        seta.style.top = '';
      }
    }

    posicionar();
    requestAnimationFrame(() => {
      balao.style.opacity = '1';
    });

    const intervaloReposicionar = setInterval(() => {
      if (!popupPinoCronometroEl) {
        clearInterval(intervaloReposicionar);
        return;
      }
      posicionar();
    }, 250);

    balao.querySelector('#mxm-popup-pino-cronometro-ok').addEventListener('click', () => {
      tocarSom('clique');
      fecharPopupPinoCronometro();
    });
  }

  function atualizarDotsResumo(dotsWrap, total, indiceAtual) {
    if (!dotsWrap) return;
    // V3.4.66: dotsWrap agora é a barrinha de controle inteira (setas +
    // pontinhos + pino) — os pontinhos em si vivem num filho dedicado
    // (data-mxm-dots-central) pra não apagar as setas/pino ao lado toda
    // vez que a lista de pontinhos é reconstruída. Fallback pro próprio
    // dotsWrap cobre qualquer estrutura antiga que ainda não tenha esse
    // filho.
    const central = dotsWrap.querySelector('[data-mxm-dots-central]') || dotsWrap;
    if (total <= 1) {
      dotsWrap.style.display = 'none';
      central.innerHTML = '';
      return;
    }
    dotsWrap.style.display = 'grid';
    const dotsAtuais = central.querySelectorAll('[data-mxm-dot]');
    if (dotsAtuais.length !== total) {
      central.innerHTML = Array.from({ length: total })
        .map((_, i) => `<span data-mxm-dot="${i}" class="mxm-resumo-dot" style="cursor:pointer;"></span>`)
        .join('');
      central.querySelectorAll('[data-mxm-dot]').forEach((dot) => {
        dot.addEventListener('click', () => {
          const resumoEl = dot.closest('#mxm-log-resumo-dia');
          if (resumoEl) irParaSlideResumo(resumoEl, Number(dot.dataset.mxmDot));
        });
      });
    }
    central.querySelectorAll('[data-mxm-dot]').forEach((dot) => {
      dot.classList.toggle('mxm-resumo-dot-ativa', Number(dot.dataset.mxmDot) === indiceAtual);
    });
  }

  // Decide de que lado o slide novo deve "entrar" — atravessa sempre pelo
  // caminho mais curto no círculo de slides, então o giro automático do
  // último slide de volta pro primeiro continua parecendo "pra frente" em
  // vez de dar um passo pra trás visualmente.
  function calcularDirecaoResumo(atual, indice, total) {
    let diferenca = indice - atual;
    if (Math.abs(diferenca) > total / 2) diferenca = -diferenca;
    return diferenca >= 0 ? 1 : -1;
  }

  const DESLOCAMENTO_SLIDE_RESUMO_PX = 20;
  const DURACAO_TRANSICAO_SLIDE_RESUMO_MS = 340;

  function irParaSlideResumo(resumoEl, indice) {
    const slides = resumoEl._mxmSlidesResumo;
    const miolo = resumoEl.querySelector('[data-mxm-resumo-miolo]');
    const slideAtualEl = miolo && miolo.querySelector('[data-mxm-resumo-slide][data-mxm-atual="1"]');
    if (!slides || !slides[indice] || !miolo || !slideAtualEl || resumoEl._mxmEmTransicao) return;
    const atual = Number(resumoEl.dataset.mxmSlideIdx);
    if (atual === indice) return;

    // V3.4.81: CORREÇÃO DE BUG GRAVE — causa raiz de verdade do "scroll
    // trava no topo" em listas pequenas (confirmada com backup real do
    // usuário: 4 itens no log, carrossel do resumo ativo). O giro
    // automático do carrossel (a cada 6s, sem gesto nenhum do usuário)
    // troca de slide e muda miolo.style.height JÁ no requestAnimationFrame
    // logo abaixo — e como #mxm-log-resumo-dia-wrap e #mxm-log-lista-wrap
    // são irmãos num flex column com a lista em flex:1, isso empurra a
    // lista e corrompe seu scrollTop pelo mesmo mecanismo de sempre
    // (ver V3.4.80). sincronizarAlturaResumoWrap (chamada só no fim desta
    // função, no setTimeout ~380ms depois) ancora TARDE DEMAIS — a
    // transição de altura do miolo já aconteceu inteira antes disso.
    // Numa lista grande isso passa despercebido (a fração do espaço
    // "roubado" é ínfima); numa lista pequena, é grande o bastante pra
    // zerar o scroll no meio do gesto do usuário. Corrigido ancorando a
    // posição aqui, no início, antes de qualquer mudança de altura.
    if (typeof ancorarScrollListaAntesDeResize === 'function') ancorarScrollListaAntesDeResize(380); // 340ms (DURACAO_TRANSICAO_SLIDE_RESUMO_MS) + 40ms, igual ao setTimeout logo abaixo

    const direcao = calcularDirecaoResumo(atual, indice, slides.length);
    resumoEl.dataset.mxmSlideIdx = String(indice);
    resumoEl._mxmEmTransicao = true;

    slideAtualEl.removeAttribute('data-mxm-atual');
    slideAtualEl.style.cssText = `position:absolute; top:0; left:0; width:100%; transition:opacity ${DURACAO_TRANSICAO_SLIDE_RESUMO_MS}ms cubic-bezier(.2,0,0,1), transform ${DURACAO_TRANSICAO_SLIDE_RESUMO_MS}ms cubic-bezier(.2,0,0,1); opacity:1; transform:translateX(0);`;

    const slideNovoEl = document.createElement('div');
    slideNovoEl.setAttribute('data-mxm-resumo-slide', '');
    slideNovoEl.style.cssText = `position:absolute; top:0; left:0; width:100%; opacity:0; transform:translateX(${
      direcao * DESLOCAMENTO_SLIDE_RESUMO_PX
    }px); transition:opacity ${DURACAO_TRANSICAO_SLIDE_RESUMO_MS}ms cubic-bezier(.2,0,0,1), transform ${DURACAO_TRANSICAO_SLIDE_RESUMO_MS}ms cubic-bezier(.2,0,0,1);`;
    slideNovoEl.innerHTML = slides[indice];
    miolo.appendChild(slideNovoEl);

    const alturaNovaPx = (resumoEl._mxmAlturasSlides || [])[indice];
    void slideNovoEl.offsetHeight; // força aplicar o estado inicial (fora da tela) antes de animar

    requestAnimationFrame(() => {
      slideAtualEl.style.opacity = '0';
      slideAtualEl.style.transform = `translateX(${-direcao * DESLOCAMENTO_SLIDE_RESUMO_PX}px)`;
      slideNovoEl.style.opacity = '1';
      slideNovoEl.style.transform = 'translateX(0)';
      if (alturaNovaPx) miolo.style.height = `${alturaNovaPx}px`;
    });

    setTimeout(() => {
      slideAtualEl.remove();
      slideNovoEl.setAttribute('data-mxm-atual', '1');
      slideNovoEl.style.position = 'static';
      slideNovoEl.style.transform = 'none';
      resumoEl._mxmEmTransicao = false;
      // reconfirma a altura do wrap externo (que segue o
      // offsetHeight do miolo, agora variável de acordo com o slide ativo).
      if (typeof sincronizarAlturaResumoWrap === 'function') sincronizarAlturaResumoWrap();
    }, DURACAO_TRANSICAO_SLIDE_RESUMO_MS + 40);

    atualizarDotsResumo(resumoEl.querySelector('[data-mxm-resumo-dots]'), slides.length, indice);
    atualizarBotaoFixarResumo(resumoEl.querySelector('[data-mxm-resumo-fixar]'), getResumoSlideFixado(slides.length), indice);
  }

  function renderGraficoHoras(porHora, cor) {
    const corBarra = cor || '#1DB954';
    const max = Math.max(1, ...porHora);
    const barras = porHora
      .map((qtd, hora) => {
        const alturaPct = qtd > 0 ? Math.max(6, Math.round((qtd / max) * 100)) : 2;
        const mostrarLabel = hora % 3 === 0;
        return `
          <div style="display:flex; flex-direction:column; align-items:center; flex:1; height:100%; justify-content:flex-end;">
            <div title="${String(hora).padStart(2, '0')}h — ${qtd}" data-final-altura="${alturaPct}"
                 style="width:60%; min-height:2px; height:0%; background:${
          qtd > 0 ? corBarra : 'var(--md-sys-color-outline-variant)'
        }; border-radius:var(--md-shape-xs) var(--md-shape-xs) 0 0; transition:height .5s cubic-bezier(.22,.85,.32,1) ${hora * 10}ms;"></div>
            <div style="font-size:9px; color:var(--md-sys-color-outline); margin-top:4px; height:11px;">${
              mostrarLabel ? `${String(hora).padStart(2, '0')}h` : ''
            }</div>
          </div>
        `;
      })
      .join('');
    return `<div style="background:var(--md-sys-color-surface); border-radius:var(--md-shape-sm); padding:10px 6px; display:flex; align-items:flex-end; height:110px; gap:2px;">${barras}</div>`;
  }

  const LIMITE_COLUNAS_FLEX = 20;
  const LARGURA_MAX_COLUNA_FLEX = 64; // px — teto de largura por coluna no modo flexível
  const LARGURA_COLUNA_SERIE = 20; // px por dia/mês (modo com scroll)
  const LARGURA_BARRA_SERIE = 10; // px — a barra em si, dentro da coluna (modo com scroll)

  const CORES_DESTAQUE = {
    maisCurta: '#5eead4', // turquesa
    maisLonga: '#ff8fb1', // rosa
    atividadeSemana: 'var(--md-sys-color-primary)', // azul
    atividadeMes: '#c792ea', // roxo
    horarioPico: '#f2b705', // dourado
  };

  function renderGraficoBarrasSerie(itens, cor) {
    const corBarra = cor || '#1DB954';
    if (!itens || itens.length === 0) {
      return `<div style="background:var(--md-sys-color-surface); border-radius:var(--md-shape-sm); padding:10px; color:var(--md-sys-color-outline); font-size:12px;">${t(
        'nenhumRegistroAinda'
      )}</div>`;
    }

    const max = Math.max(1, ...itens.map((i) => i.qtd));
    // Evita rótulo colado em rótulo quando há muitas colunas: mostra só uma
    // a cada N, sempre incluindo a última coluna (mais recente).
    const passoLabel = itens.length <= 10 ? 1 : Math.ceil(itens.length / 10);
    const modoFlex = itens.length <= LIMITE_COLUNAS_FLEX;

    const barras = itens
      .map((item, idx) => {
        const alturaPct = item.qtd > 0 ? Math.max(6, Math.round((item.qtd / max) * 100)) : 2;
        const mostrarLabel = idx % passoLabel === 0 || idx === itens.length - 1;
        const estiloColuna = modoFlex
          ? `display:flex; flex-direction:column; align-items:center; justify-content:flex-end; height:100%; flex:1 1 ${LARGURA_MAX_COLUNA_FLEX}px; max-width:${LARGURA_MAX_COLUNA_FLEX}px; min-width:0;`
          : `display:flex; flex-direction:column; align-items:center; justify-content:flex-end; height:100%; width:${LARGURA_COLUNA_SERIE}px; flex:0 0 ${LARGURA_COLUNA_SERIE}px;`;
        const larguraBarra = modoFlex ? '60%' : `${LARGURA_BARRA_SERIE}px`;
        return `
          <div style="${estiloColuna}">
            <div title="${item.tooltip}" data-final-altura="${alturaPct}"
                 style="width:${larguraBarra}; min-height:2px; height:0%; background:${
          item.qtd > 0 ? corBarra : 'var(--md-sys-color-outline-variant)'
        }; border-radius:var(--md-shape-xs) var(--md-shape-xs) 0 0; transition:height .5s cubic-bezier(.22,.85,.32,1) ${Math.min(idx, 20) * 16}ms;"></div>
            <div style="font-size:9px; color:var(--md-sys-color-outline); margin-top:4px; height:11px; white-space:nowrap;">${
              mostrarLabel ? item.label : ''
            }</div>
          </div>
        `;
      })
      .join('');

    if (modoFlex) {
      return `<div style="background:var(--md-sys-color-surface); border-radius:var(--md-shape-sm); padding:10px 6px; display:flex; align-items:flex-end; justify-content:center; height:110px; gap:6px;">${barras}</div>`;
    }
    return `<div style="background:var(--md-sys-color-surface); border-radius:var(--md-shape-sm); padding:10px 6px; overflow-x:auto; overflow-y:hidden;"><div style="display:flex; align-items:flex-end; justify-content:flex-start; height:110px; width:max-content; min-width:100%; box-sizing:border-box;">${barras}</div></div>`;
  }

  // Card único com o tempo médio entre envios DENTRO de uma sessão de
  // trabalho (ver calcularRitmoSessoes) — não é o total do dia, é o ritmo:
  // quanto tempo em média passa de uma música pra outra enquanto o
  // usuário está ativamente trabalhando.
  function renderCardRitmoSessao(ritmo) {
    if (!ritmo.mediaSegundos || ritmo.amostras < 3) {
      return `<div style="color:var(--md-sys-color-outline); font-size:12px;">${t('ritmoDadosInsuficientes')}</div>`;
    }
    return `
      <div style="background:var(--md-sys-color-surface); border-radius:var(--md-shape-sm); padding:14px; display:flex; align-items:center; gap:12px;">
        <div style="flex-shrink:0; width:40px; height:40px; border-radius:50%; background:color-mix(in srgb, var(--md-sys-color-primary) 20%, transparent); display:flex; align-items:center; justify-content:center; color:var(--md-sys-color-primary);">${icone(
          'clock',
          18
        )}</div>
        <div style="min-width:0;">
          <div style="font-size:22px; font-weight:800; color:var(--md-sys-color-primary); line-height:1.2; font-variant-numeric:tabular-nums;">${
            segundosParaDuracao(ritmo.mediaSegundos) || '—'
          }</div>
          <div style="font-size:10.5px; color:var(--md-sys-color-outline); margin-top:2px;">${preencherTemplate(
            t('ritmoBaseadoEm'),
            { n: String(ritmo.amostras), sessoes: String(ritmo.sessoes) }
          )}</div>
        </div>
      </div>
    `;
  }

  // Gráfico de barras da duração MÉDIA das faixas por mês (últimos 6
  // meses) — mesmo visual dos outros gráficos de barra da tela, mas a
  // escala parte de um pouco abaixo do menor valor (em vez de zero),
  // porque aqui o que importa é enxergar a VARIAÇÃO entre os meses, não o
  // valor absoluto virando barra cheia/vazia como nos gráficos de
  // contagem de envios.
  function renderGraficoDuracaoMedia(itens, cor) {
    const corBarra = cor || '#1DB954';
    const valores = itens.map((i) => i.mediaSegundos).filter((v) => v !== null);
    if (!valores.length) {
      return `<div style="background:var(--md-sys-color-surface); border-radius:var(--md-shape-sm); padding:10px; color:var(--md-sys-color-outline); font-size:12px;">${t(
        'nenhumaFaixaComDuracao'
      )}</div>`;
    }
    const max = Math.max(...valores);
    const min = Math.min(...valores);
    const base = Math.max(0, min - (max - min || min) * 0.35);
    const escala = Math.max(1, max - base);

    const barras = itens
      .map((item) => {
        const temDado = item.mediaSegundos !== null;
        const alturaPct = temDado ? Math.max(6, Math.round(((item.mediaSegundos - base) / escala) * 100)) : 2;
        const tooltip = temDado
          ? `${item.label} — ${segundosParaDuracao(item.mediaSegundos)}`
          : `${item.label} — ${t('nenhumRegistroAinda')}`;
        return `
          <div style="display:flex; flex-direction:column; align-items:center; flex:1; height:100%; justify-content:flex-end; min-width:0;">
            <div title="${tooltip}" data-final-altura="${alturaPct}"
                 style="width:60%; min-height:2px; height:0%; background:${
                   temDado ? corBarra : 'var(--md-sys-color-outline-variant)'
                 }; border-radius:var(--md-shape-xs) var(--md-shape-xs) 0 0; transition:height .5s cubic-bezier(.22,.85,.32,1);"></div>
            <div style="font-size:9px; color:var(--md-sys-color-outline); margin-top:4px; height:11px; white-space:nowrap;">${
              item.label
            }</div>
          </div>
        `;
      })
      .join('');

    return `<div style="background:var(--md-sys-color-surface); border-radius:var(--md-shape-sm); padding:10px 6px; display:flex; align-items:flex-end; height:110px; gap:2px;">${barras}</div>`;
  }

  // Frase de destaque comparando o mês atual com o mesmo mês há ~3 meses
  // atrás (primeiro e último item da série de 6 meses) — responde direto
  // à pergunta "trabalho com músicas mais curtas ou mais longas do que
  // trabalhava antes?".
  function renderComparativoDuracaoMedia(itens) {
    if (!itens || itens.length < 2) return '';
    const atual = itens[itens.length - 1];
    const passado = itens[0];
    if (atual.mediaSegundos === null || passado.mediaSegundos === null) {
      return `<div style="color:var(--md-sys-color-outline); font-size:11.5px; margin-top:8px;">${t(
        'evolucaoDuracaoDadosInsuficientes'
      )}</div>`;
    }
    const diffSegundos = atual.mediaSegundos - passado.mediaSegundos;
    const diffAbs = Math.abs(diffSegundos);
    if (diffAbs < 3) {
      return `<div style="display:flex; align-items:center; gap:6px; margin-top:8px; font-size:12px; color:var(--md-sys-color-outline); font-weight:600;">${icone(
        'minus',
        13,
        'var(--md-sys-color-outline)'
      )}${t('evolucaoDuracaoEstavel')}</div>`;
    }
    const maisCurtas = diffSegundos < 0;
    const cor = maisCurtas ? '#5eead4' : '#ff8fb1';
    const nomeIcone = maisCurtas ? 'trendingDown' : 'trendingUp';
    const texto = preencherTemplate(t(maisCurtas ? 'evolucaoDuracaoMaisCurtas' : 'evolucaoDuracaoMaisLongas'), {
      tempo: segundosParaDuracao(diffAbs) || `${diffAbs}s`,
      mes: passado.label,
    });
    return `<div style="display:flex; align-items:center; gap:6px; margin-top:8px; font-size:12px; color:${cor}; font-weight:600;">${icone(
      nomeIcone,
      13,
      cor
    )}${texto}</div>`;
  }

  function animarBarrasEntrada(container) {
    if (!container) return;
    const barrasAltura = container.querySelectorAll('[data-final-altura]');
    const barrasLargura = container.querySelectorAll('[data-final-largura]');
    if (!barrasAltura.length && !barrasLargura.length) return;
    if (!isAnimacoesAtiva()) {
      barrasAltura.forEach((barra) => {
        barra.style.transition = 'none';
        barra.style.height = `${barra.dataset.finalAltura}%`;
      });
      barrasLargura.forEach((barra) => {
        barra.style.transition = 'none';
        barra.style.width = `${barra.dataset.finalLargura}%`;
      });
      return;
    }
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        barrasAltura.forEach((barra) => {
          barra.style.height = `${barra.dataset.finalAltura}%`;
        });
        barrasLargura.forEach((barra) => {
          barra.style.width = `${barra.dataset.finalLargura}%`;
        });
      });
    });
  }

  const MISSION_ACCENT_COLOR_DEFAULT = 'var(--md-sys-color-outline)';
  const MISSION_ACCENT_COLORS = [
    { termo: 'spotify', cor: '#1DB954' },
    { termo: 'youtube', cor: '#FF4B4B' },
    { termo: 'amazon', cor: '#3EA6FF' },
    { termo: 'iheart', cor: '#FF7A45' },
    { termo: 'saregama', cor: '#FFC53D' },
    { termo: 'jukebox', cor: '#B388FF' },
    { termo: 'russian', cor: '#4DD0E1' },
    { termo: 'transcription', cor: '#8FA3B0' },
    { termo: 'artists special', cor: '#FF6FA5' },
  ];

  function getMissionAccentColor(nomeMissao) {
    const chave = normalizeMissionLabelForLookup(nomeMissao || '');
    if (!chave) return MISSION_ACCENT_COLOR_DEFAULT;
    const encontrada = MISSION_ACCENT_COLORS.find((item) => chave.includes(item.termo));
    return encontrada ? encontrada.cor : MISSION_ACCENT_COLOR_DEFAULT;
  }

  const TOUR_ACCENT_NEUTRO = 'var(--md-sys-color-outline)';

  function renderListaRanking(itens, resolverCor) {
    if (!itens.length) {
      return `<div style="color:var(--md-sys-color-outline); font-size:12px; padding:6px 0;">${t('nenhumRegistroAinda')}</div>`;
    }
    const obterCor = resolverCor || (() => '#1DB954');
    const max = Math.max(...itens.map(([, qtd]) => qtd), 1);
    const linhas = itens
      .map(([nome, qtd], i) => {
        const cor = obterCor(nome);
        const pct = Math.max(6, Math.round((qtd / max) * 100));
        return `
        <div style="position:relative; overflow:hidden; border-radius:var(--md-shape-md); background:var(--md-sys-color-surface-container-low); margin-bottom:${
          i === itens.length - 1 ? '0' : '6px'
        };">
          <div data-final-largura="${pct}" style="position:absolute; inset:0; width:0%; background:${cor}22; transition:width .5s cubic-bezier(.22,.85,.32,1) ${
          i * 40
        }ms;"></div>
          <div style="position:relative; display:flex; align-items:center; gap:9px; padding:9px 10px; font-size:13px;">
            <span style="flex-shrink:0; width:8px; height:8px; border-radius:50%; background:${cor};"></span>
            <span style="flex:1; min-width:0; color:var(--md-sys-color-on-surface); overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${escapeHtml(nome)}</span>
            <span style="flex-shrink:0; color:${cor}; font-weight:700; font-size:11.5px; background:${cor}26; border-radius:var(--md-shape-full); padding:2px 9px;">${qtd}</span>
          </div>
        </div>
      `;
      })
      .join('');
    return `<div>${linhas}</div>`;
  }

  function renderSeletorFiltroMissao(filtroAtual) {
    const opcoes = [
      { valor: 'total', rotulo: t('filtroTotal') },
      { valor: 'ciclo', rotulo: t('filtroCicloAtual') },
    ];
    const botoes = opcoes
      .map((op, i) => {
        const selecionado = op.valor === filtroAtual;
        return `
          <button type="button" data-filtro-missao="${op.valor}" style="
            padding:4px 10px; font-size:10.5px; font-family:inherit; white-space:nowrap;
            border:none; border-left:${i === 0 ? 'none' : '1px solid var(--md-sys-color-outline-variant)'};
            background:${
              selecionado ? 'color-mix(in srgb, var(--md-sys-color-primary) 18%, transparent)' : 'transparent'
            };
            color:${selecionado ? 'var(--md-sys-color-primary)' : 'var(--md-sys-color-on-surface-variant)'};
            font-weight:${selecionado ? '700' : '500'}; cursor:pointer; transition:background .12s ease, color .12s ease;
          ">${op.rotulo}</button>
        `;
      })
      .join('');
    return `<div id="mxm-seletor-filtro-missao" style="flex-shrink:0; display:inline-flex; border:1px solid var(--md-sys-color-outline-variant); border-radius:var(--md-shape-full); overflow:hidden;">${botoes}</div>`;
  }

  function renderSeletorModoComparacao(modoAtual) {
    const opcoes = [
      { valor: 'mensal', rotulo: t('modoComparacaoMensal') },
      { valor: 'ciclo', rotulo: t('modoComparacaoCiclo') },
    ];
    const botoes = opcoes
      .map((op, i) => {
        const selecionado = op.valor === modoAtual;
        return `
          <button type="button" data-modo-comparacao="${op.valor}" style="
            padding:4px 10px; font-size:10.5px; font-family:inherit; white-space:nowrap;
            border:none; border-left:${i === 0 ? 'none' : '1px solid var(--md-sys-color-outline-variant)'};
            background:${
              selecionado ? 'color-mix(in srgb, var(--md-sys-color-primary) 18%, transparent)' : 'transparent'
            };
            color:${selecionado ? 'var(--md-sys-color-primary)' : 'var(--md-sys-color-on-surface-variant)'};
            font-weight:${selecionado ? '700' : '500'}; cursor:pointer; transition:background .12s ease, color .12s ease;
          ">${op.rotulo}</button>
        `;
      })
      .join('');
    return `<div id="mxm-seletor-modo-comparacao" style="flex-shrink:0; display:inline-flex; border:1px solid var(--md-sys-color-outline-variant); border-radius:var(--md-shape-full); overflow:hidden;">${botoes}</div>`;
  }

  function renderPainelDetalhado() {
    const painel = document.getElementById('mxm-log-detalhado-conteudo');
    if (!painel) return;

    const entradas = Object.values(getLogs());
    const stats = calcularEstatisticas(entradas);

    const filtroMissaoAtual = getFiltroMissaoPainel();
    const porMissaoCiclo = calcularEstatisticas(entradasDoMes(entradas, chaveCicloAtual())).porMissao;
    const porMissaoAtivo = filtroMissaoAtual === 'ciclo' ? porMissaoCiclo : stats.porMissao;
    const porMissaoOrdenado = Object.entries(porMissaoAtivo).sort((a, b) => b[1] - a[1]);

    const missaoHtml = renderListaRanking(porMissaoOrdenado, getMissionAccentColor);
    const seletorMissaoHtml = renderSeletorFiltroMissao(filtroMissaoAtual);

    function renderCardDuracao(entrada, cor, label) {
      const mostrarImg = isImgVisible();
      let capaHtml;
      if (mostrarImg && entrada.imagemUrl) {
        capaHtml = `<img src="${entrada.imagemUrl}" style="width:100%; height:100%; object-fit:cover;">`;
      } else if (mostrarImg) {
        capaHtml = renderCapaPlaceholder(`${entrada.titulo}|${entrada.artista}`, '100%', 18, false);
      } else {
        capaHtml = `<div style="width:100%; height:100%; display:flex; align-items:center; justify-content:center;">${icone(
          'music',
          18,
          'var(--md-sys-color-outline-variant)'
        )}</div>`;
      }
      return `
        <div style="flex:1; background:var(--md-sys-color-surface); border-radius:var(--md-shape-sm); padding:10px; display:flex; align-items:center; gap:10px; min-width:0;">
          <div style="width:46px; height:46px; border-radius:var(--md-shape-sm); overflow:hidden; flex-shrink:0; background:var(--md-sys-color-surface-container-low); border:2px solid ${cor}4d;">${capaHtml}</div>
          <div style="min-width:0; flex:1;">
            <div style="display:flex; align-items:center; gap:5px; font-size:11px; color:var(--md-sys-color-outline); text-transform:uppercase; margin-bottom:4px;">${icone(
              'clock',
              11
            )}${label}</div>
            <div style="font-size:13px; color:var(--md-sys-color-on-surface); font-weight:600; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${
        entrada.titulo
      }</div>
            <div style="font-size:12px; color:var(--md-sys-color-outline); overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${
        entrada.artista
      }</div>
            <div style="font-size:16px; color:${cor}; font-weight:800; margin-top:2px;">${entrada.duracao}</div>
          </div>
        </div>
      `;
    }

    const duracaoHtml =
      stats.maisCurta && stats.maisLonga
        ? `
      <div style="display:flex; gap:10px;">
        ${renderCardDuracao(stats.maisCurta, CORES_DESTAQUE.maisCurta, t('maisCurta'))}
        ${renderCardDuracao(stats.maisLonga, CORES_DESTAQUE.maisLonga, t('maisLonga'))}
      </div>
    `
        : `<div style="color:var(--md-sys-color-outline); font-size:12px;">${t('nenhumaFaixaComDuracao')}</div>`;

    const seriePorDia = calcularSeriePorDia(stats.porData, 7);
    const seriePorMes = calcularSeriePorMes(entradas);
    const modoComparacaoAtivo = getModoComparacaoPeriodo();
    const comparativoMensal = calcularComparativoMensal(entradas);
    const comparativoCiclo = calcularComparativoCiclo(entradas);
    const comparativoAtivo = modoComparacaoAtivo === 'ciclo' ? comparativoCiclo : comparativoMensal;
    const seletorModoComparacaoHtml = renderSeletorModoComparacao(modoComparacaoAtivo);
    const comparativoDia = calcularComparativoDiaEquivalente(stats.porData);
    const distribuicaoDiaSemana = calcularDistribuicaoPorDiaSemana(stats.porData);
    const ritmoSessao = calcularRitmoSessoes(entradas);
    const serieDuracaoMedia = calcularSerieDuracaoMediaPorMes(entradas, 6);

    const blocosSecoes = {
      hojeVsRecorde: `
      <div style="margin-bottom:30px;">
        <div id="mxm-log-detalhado-titulo-hoje-recorde" style="display:flex; align-items:center; gap:6px; font-size:12px; font-weight:700; color:var(--md-sys-color-outline); text-transform:uppercase; margin-bottom:10px; user-select:none;">${icone(
          'flame',
          13
        )}${t('hojeVsRecorde')}</div>
        ${renderBarraHojeVsRecorde(stats.porData, stats.porDataRecorde)}
      </div>
      `,
      proximoCiclo: `
      <div style="margin-bottom:30px;">
        <div style="display:flex; align-items:center; gap:6px; font-size:12px; font-weight:700; color:var(--md-sys-color-outline); text-transform:uppercase; margin-bottom:10px;">${icone(
          'clock',
          13
        )}${t('proximoCicloTitulo')}</div>
        <div style="display:flex; gap:10px;">
          <div title="${t('proximoCicloDescricao')}" style="flex:1; min-width:0; background:color-mix(in srgb, var(--md-sys-color-primary) 13%, var(--md-sys-color-surface)); border-radius:var(--md-shape-lg); padding:14px; display:flex; align-items:center; gap:12px;">
            <div style="flex-shrink:0; width:40px; height:40px; border-radius:50%; background:color-mix(in srgb, var(--md-sys-color-primary) 24%, transparent); display:flex; align-items:center; justify-content:center; color:var(--md-sys-color-primary);">${icone(
              'clock',
              18
            )}</div>
            <div style="min-width:0;">
              <div style="font-size:10.5px; font-weight:600; text-transform:uppercase; letter-spacing:.3px; color:var(--md-sys-color-on-surface-variant); overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${t(
                'proximoCicloTitulo'
              )}</div>
              <div style="font-size:20px; font-weight:800; color:var(--md-sys-color-primary); line-height:1.25; font-variant-numeric:tabular-nums; margin-top:2px;"><span id="mxm-log-detalhado-cronometro-valor">${formatarContagemRegressiva(
                proximoInicioCiclo() - mxmAgora()
              )}</span></div>
            </div>
          </div>
          <div title="${t('cronometroEstiloSiteTooltip')}" style="flex:1; min-width:0; background:color-mix(in srgb, #5eead4 16%, var(--md-sys-color-surface)); border-radius:var(--md-shape-lg); padding:14px; display:flex; align-items:center; gap:12px;">
            <div style="flex-shrink:0; width:40px; height:40px; border-radius:50%; background:color-mix(in srgb, #5eead4 28%, transparent); display:flex; align-items:center; justify-content:center; font-size:17px;">⏰</div>
            <div style="min-width:0;">
              <div style="font-size:10.5px; font-weight:600; text-transform:uppercase; letter-spacing:.3px; color:var(--md-sys-color-on-surface-variant); overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${t(
                'cronometroEstiloSiteLabel'
              )}</div>
              <div style="font-size:20px; font-weight:800; color:#5eead4; line-height:1.25; font-variant-numeric:tabular-nums; margin-top:2px;"><span id="mxm-log-detalhado-cronometro-valor-site">${formatarDiasEstiloSite(
                proximoInicioCiclo()
              )}</span></div>
            </div>
          </div>
        </div>
      </div>
      `,
      musicasPorMissao: `
      <div style="margin-bottom:30px;">
        <div style="display:flex; align-items:center; justify-content:space-between; gap:8px; margin-bottom:10px;">
          <div style="display:flex; align-items:center; gap:6px; font-size:12px; font-weight:700; color:var(--md-sys-color-outline); text-transform:uppercase; min-width:0;">${icone(
            'target',
            13
          )}${t('musicasPorMissao')}</div>
          ${seletorMissaoHtml}
        </div>
        ${missaoHtml}
      </div>
      `,
      duracaoDasFaixas: `
      <div style="margin-bottom:30px;">
        <div style="display:flex; align-items:center; gap:6px; font-size:12px; font-weight:700; color:var(--md-sys-color-outline); text-transform:uppercase; margin-bottom:10px;">${icone(
          'clock',
          13
        )}${t('duracaoDasFaixas')}</div>
        ${duracaoHtml}
      </div>
      `,
      horarioDePico: `
      <div style="margin-bottom:30px;">
        <div style="display:flex; align-items:center; gap:6px; font-size:12px; font-weight:700; color:var(--md-sys-color-outline); text-transform:uppercase; margin-bottom:10px;">${icone(
          'trendingUp',
          13
        )}${t('horarioDePico')}</div>
        ${renderGraficoHoras(stats.porHora, CORES_DESTAQUE.horarioPico)}
      </div>
      `,
      atividadePorDia: `
      <div style="margin-bottom:30px;">
        <div style="display:flex; align-items:center; gap:6px; font-size:12px; font-weight:700; color:var(--md-sys-color-outline); text-transform:uppercase; margin-bottom:10px;">${icone(
          'calendar',
          13
        )}${t('atividadePorDia')}</div>
        ${renderGraficoBarrasSerie(seriePorDia, CORES_DESTAQUE.atividadeSemana)}
      </div>
      `,
      atividadePorMes: `
      <div style="margin-bottom:30px;">
        <div style="display:flex; align-items:center; gap:6px; font-size:12px; font-weight:700; color:var(--md-sys-color-outline); text-transform:uppercase; margin-bottom:10px;">${icone(
          'barChart',
          13
        )}${t('atividadePorMes')}</div>
        ${renderGraficoBarrasSerie(seriePorMes, CORES_DESTAQUE.atividadeMes)}
      </div>
      `,
      comparativoPeriodo: `
      <div style="margin-bottom:30px;">
        <div style="display:flex; align-items:center; justify-content:space-between; gap:8px; margin-bottom:10px;">
          <div style="display:flex; align-items:center; gap:6px; font-size:12px; font-weight:700; color:var(--md-sys-color-outline); text-transform:uppercase; min-width:0;">${icone(
            'trendingUp',
            13
          )}${t('comparativoPeriodo')}</div>
          ${seletorModoComparacaoHtml}
        </div>
        ${renderComparativoMensal(comparativoAtivo, modoComparacaoAtivo)}
      </div>
      `,
      diaVsDiaEquivalente: `
      <div style="margin-bottom:30px;">
        <div style="display:flex; align-items:center; gap:6px; font-size:12px; font-weight:700; color:var(--md-sys-color-outline); text-transform:uppercase; margin-bottom:10px;">${icone(
          'trendingUp',
          13
        )}${t('diaVsDiaEquivalente')}</div>
        ${renderComparativoDiaEquivalente(comparativoDia)}
      </div>
      `,
      sequencia: `
      <div style="margin-bottom:30px;">
        <div style="display:flex; align-items:center; gap:6px; font-size:12px; font-weight:700; color:var(--md-sys-color-outline); text-transform:uppercase; margin-bottom:10px;">${icone(
          'calendar',
          13
        )}${t('sequenciaTitulo')}</div>
        ${renderCardSequencia(stats.porData)}
      </div>
      `,
      distribuicaoDiaSemana: `
      <div style="margin-bottom:30px;">
        <div style="display:flex; align-items:center; gap:6px; font-size:12px; font-weight:700; color:var(--md-sys-color-outline); text-transform:uppercase; margin-bottom:10px;">${icone(
          'barChart',
          13
        )}${t('distribuicaoDiaSemanaTitulo')}</div>
        ${renderHeatmapDiaSemana(distribuicaoDiaSemana, CORES_DESTAQUE.atividadeSemana)}
      </div>
      `,
      ritmoEnvio: `
      <div style="margin-bottom:30px;">
        <div style="display:flex; align-items:center; gap:6px; font-size:12px; font-weight:700; color:var(--md-sys-color-outline); text-transform:uppercase; margin-bottom:10px;">${icone(
          'clock',
          13
        )}${t('ritmoEnvioTitulo')}</div>
        ${renderCardRitmoSessao(ritmoSessao)}
      </div>
      `,
      evolucaoDuracao: `
      <div style="margin-bottom:30px;">
        <div style="display:flex; align-items:center; gap:6px; font-size:12px; font-weight:700; color:var(--md-sys-color-outline); text-transform:uppercase; margin-bottom:10px;">${icone(
          'trendingUp',
          13
        )}${t('evolucaoDuracaoTitulo')}</div>
        ${renderGraficoDuracaoMedia(serieDuracaoMedia, CORES_DESTAQUE.maisLonga)}
        ${renderComparativoDuracaoMedia(serieDuracaoMedia)}
      </div>
      `,
    };

    // monta o conteúdo final na ordem/visibilidade escolhidas pelo usuário
    // (ver abrirPersonalizarPainelDetalhado) — qualquer id desconhecido ou
    // removido de blocosSecoes (versão antiga salva, por ex.) é ignorado
    // em silêncio, sem quebrar o painel.
    const { ordem: ordemSecoes, ocultas: ocultasSecoes } = getConfigSecoesDetalhado();
    const corpoSecoesHtml = ordemSecoes
      .filter((id) => blocosSecoes[id] && !ocultasSecoes.has(id))
      .map((id) => blocosSecoes[id])
      .join('');

    painel.innerHTML = `
      ${corpoSecoesHtml}
      <div style="display:flex; align-items:flex-start; gap:7px; margin-top:24px; padding-top:16px; font-size:10.5px; line-height:1.5; color:var(--md-sys-color-outline);">
        ${icone('alertTriangle', 12, 'var(--md-sys-color-outline-variant)')}<span>${t('avisoDadosLocais')}</span>
      </div>
    `;
    animarBarrasEntrada(painel);

    painel.querySelectorAll('#mxm-seletor-filtro-missao [data-filtro-missao]').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const valor = btn.dataset.filtroMissao;
        if (valor === filtroMissaoAtual) return;
        setFiltroMissaoPainel(valor);
        renderPainelDetalhado();
      });
    });

    // mesma lógica acima, agora pro seletor Mensal/Ciclo do
    // "Comparativo do período".
    painel.querySelectorAll('#mxm-seletor-modo-comparacao [data-modo-comparacao]').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const valor = btn.dataset.modoComparacao;
        if (valor === modoComparacaoAtivo) return;
        setModoComparacaoPeriodo(valor);
        renderPainelDetalhado();
      });
    });

    vincularCliqueSeloVerificado(document.getElementById('mxm-log-detalhado-titulo-hoje-recorde'));
  }

  // ---------- janela "Personalizar painel" (mostrar/ocultar + reordenar seções do Log Detalhado) ----------
  function abrirPersonalizarPainelDetalhado() {
    document.querySelectorAll('#mxm-log-personalizar-overlay').forEach((el) => el.remove());

    const overlay = document.createElement('div');
    overlay.id = 'mxm-log-personalizar-overlay';
    Object.assign(overlay.style, {
      position: 'fixed',
      inset: '0',
      background: 'color-mix(in srgb, var(--md-sys-color-scrim) 60%, transparent)',
      zIndex: proximoZIndexFlutuante(),
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
    });

    const { ordem: ordemInicial, ocultas } = getConfigSecoesDetalhado();
    const definicaoPorId = {};
    SECOES_LOG_DETALHADO_DEFINICAO.forEach((s) => {
      definicaoPorId[s.id] = s;
    });

    function renderLinha(id) {
      const def = definicaoPorId[id];
      if (!def) return '';
      const oculta = ocultas.has(id);
      return `
        <div class="mxm-personalizar-item" draggable="true" data-secao-id="${id}" style="display:flex; align-items:center; gap:4px; padding:8px; border-radius:var(--md-shape-md); background:var(--md-sys-color-surface-container); margin-bottom:6px; opacity:${
        oculta ? '.55' : '1'
      }; transition:opacity .15s ease;">
          <span class="mxm-personalizar-grip" title="${t(
            'arrastarParaReordenar'
          )}" style="cursor:grab; display:flex; color:var(--md-sys-color-outline); flex-shrink:0; padding:4px;">${icone(
        'gripVertical',
        15
      )}</span>
          <span style="display:flex; flex-shrink:0; color:var(--md-sys-color-outline);">${icone(def.icone, 14)}</span>
          <span style="flex:1; min-width:0; font-size:12.5px; font-weight:600; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; color:var(--md-sys-color-on-surface);">${escapeHtml(
        t(def.tituloChave)
      )}</span>
          <button type="button" data-acao="up" title="${t(
            'moverParaCima'
          )}" style="cursor:pointer; border:none; background:transparent; display:flex; padding:6px; border-radius:50%; color:var(--md-sys-color-outline); transform:rotate(180deg);">${icone(
        'chevronDown',
        13
      )}</button>
          <button type="button" data-acao="down" title="${t(
            'moverParaBaixo'
          )}" style="cursor:pointer; border:none; background:transparent; display:flex; padding:6px; border-radius:50%; color:var(--md-sys-color-outline);">${icone(
        'chevronDown',
        13
      )}</button>
          <button type="button" data-acao="toggle" title="${
            oculta ? t('personalizarSecaoMostrar') : t('personalizarSecaoOcultar')
          }" style="cursor:pointer; border:none; background:transparent; display:flex; padding:6px; border-radius:50%; color:${
        oculta ? 'var(--md-sys-color-outline)' : 'var(--md-sys-color-primary)'
      };">${icone(oculta ? 'eyeOff' : 'eye', 15)}</button>
        </div>
      `;
    }

    overlay.innerHTML = `
      <div id="mxm-log-personalizar-painel" style="background:var(--md-sys-color-surface-container-low); color:var(--md-sys-color-on-surface); width:380px; max-width:92vw; max-height:80vh; border-radius:var(--md-shape-xl); box-shadow:var(--md-elevation-3); font-family:sans-serif; display:flex; flex-direction:column; overflow:hidden;">
        <div style="display:flex; align-items:center; justify-content:space-between; padding:16px 16px 4px;">
          <div style="display:flex; align-items:center; gap:8px; font-size:14px; font-weight:700;">${icone(
            'sliders',
            15
          )}${t('personalizarPainelDetalhadoTitulo')}</div>
          <div id="mxm-log-personalizar-fechar" class="mxm-log-close-btn" style="cursor:pointer; color:var(--md-sys-color-outline); font-size:16px; display:flex; padding:8px; border-radius:50%; transition:background-color .15s ease, color .15s ease;">${icone(
            'x',
            15
          )}</div>
        </div>
        <div style="padding:2px 16px 10px; font-size:11.5px; line-height:1.5; color:var(--md-sys-color-on-surface-variant);">${t(
          'personalizarPainelDetalhadoDescricao'
        )}</div>
        <div id="mxm-log-personalizar-lista" style="overflow-y:auto; flex:1; padding:0 12px 4px;"></div>
        <div id="mxm-log-personalizar-aviso-vazio" style="display:none; padding:0 16px 8px; font-size:11px; color:var(--md-sys-color-error);">${t(
          'personalizarTodasOcultas'
        )}</div>
        <div style="display:flex; gap:8px; padding:12px 16px 16px; border-top:1px solid var(--md-sys-color-outline-variant);">
          <button id="mxm-log-personalizar-restaurar" style="flex:1; padding:8px; border-radius:var(--md-shape-sm); border:1px solid var(--md-sys-color-outline-variant); background:transparent; color:var(--md-sys-color-on-surface-variant); font-size:12.5px; cursor:pointer;">${t(
            'personalizarRestaurarPadrao'
          )}</button>
          <button id="mxm-log-personalizar-concluido" style="flex:1; padding:8px; border-radius:var(--md-shape-sm); border:none; background:var(--md-sys-color-primary); color:var(--md-sys-color-on-primary); font-size:12.5px; font-weight:600; cursor:pointer;">${t(
            'personalizarConcluido'
          )}</button>
        </div>
      </div>
    `;

    document.body.appendChild(overlay);
    const cartao = document.getElementById('mxm-log-personalizar-painel');
    animarEntradaCartao(cartao, { distancia: 8, duracao: 180 });

    const lista = document.getElementById('mxm-log-personalizar-lista');
    const avisoVazio = document.getElementById('mxm-log-personalizar-aviso-vazio');

    function ordemAtualDoDom() {
      return Array.from(lista.querySelectorAll('.mxm-personalizar-item')).map((el) => el.getAttribute('data-secao-id'));
    }

    function atualizarAvisoVazio(ordemAtual) {
      const todasOcultas = ordemAtual.length > 0 && ordemAtual.every((id) => ocultas.has(id));
      avisoVazio.style.display = todasOcultas ? 'block' : 'none';
    }

    // salva a ordem/visibilidade atual (lidas do próprio DOM, já
    // reordenado pelo arraste ou pelas setas) e atualiza o painel de
    // trás ao vivo, sem precisar fechar essa janela.
    function persistirEAtualizar() {
      const ordemNova = ordemAtualDoDom();
      setConfigSecoesDetalhado(ordemNova, ocultas);
      atualizarAvisoVazio(ordemNova);
      renderPainelDetalhado();
    }

    function vincularLinha(item) {
      const id = item.getAttribute('data-secao-id');

      item.addEventListener('dragstart', (e) => {
        item.classList.add('mxm-personalizar-item-arrastando');
        item.style.opacity = '.35';
        try {
          e.dataTransfer.setData('text/plain', id);
        } catch (erro) {}
        e.dataTransfer.effectAllowed = 'move';
      });
      item.addEventListener('dragend', () => {
        item.classList.remove('mxm-personalizar-item-arrastando');
        item.style.opacity = ocultas.has(id) ? '.55' : '1';
        persistirEAtualizar();
      });
      // enquanto arrasta por cima de outra linha, decide se entra antes
      // ou depois dela pela metade em que o cursor está — dá pra soltar
      // em qualquer ponto da linha-alvo, não só bem no topo/base dela.
      item.addEventListener('dragover', (e) => {
        e.preventDefault();
        const arrastando = lista.querySelector('.mxm-personalizar-item-arrastando');
        if (!arrastando || arrastando === item) return;
        const retangulo = item.getBoundingClientRect();
        const depois = (e.clientY - retangulo.top) / retangulo.height > 0.5;
        lista.insertBefore(arrastando, depois ? item.nextSibling : item);
      });

      item.querySelector('[data-acao="toggle"]').addEventListener('click', (e) => {
        e.stopPropagation();
        tocarSom('clique');
        if (ocultas.has(id)) {
          ocultas.delete(id);
        } else {
          ocultas.add(id);
        }
        const oculta = ocultas.has(id);
        item.style.opacity = oculta ? '.55' : '1';
        const btn = e.currentTarget;
        btn.innerHTML = icone(oculta ? 'eyeOff' : 'eye', 15);
        btn.style.color = oculta ? 'var(--md-sys-color-outline)' : 'var(--md-sys-color-primary)';
        btn.title = oculta ? t('personalizarSecaoMostrar') : t('personalizarSecaoOcultar');
        persistirEAtualizar();
      });

      item.querySelector('[data-acao="up"]').addEventListener('click', (e) => {
        e.stopPropagation();
        tocarSom('clique');
        const anterior = item.previousElementSibling;
        if (anterior) {
          lista.insertBefore(item, anterior);
          persistirEAtualizar();
        }
      });
      item.querySelector('[data-acao="down"]').addEventListener('click', (e) => {
        e.stopPropagation();
        tocarSom('clique');
        const proximo = item.nextElementSibling;
        if (proximo) {
          lista.insertBefore(proximo, item);
          persistirEAtualizar();
        }
      });
    }

    function reconstruirLista(ordemAtual) {
      lista.innerHTML = ordemAtual.map(renderLinha).join('');
      lista.querySelectorAll('.mxm-personalizar-item').forEach(vincularLinha);
      atualizarAvisoVazio(ordemAtual);
    }

    reconstruirLista(ordemInicial);

    function fechar() {
      fecharOverlayAnimado(overlay, cartao, { distancia: 8, duracao: 180 });
    }
    overlay.addEventListener('click', (e) => {
      if (e.target === overlay) fechar();
    });
    document.getElementById('mxm-log-personalizar-fechar').addEventListener('click', () => {
      tocarSom('fechar');
      fechar();
    });
    document.getElementById('mxm-log-personalizar-concluido').addEventListener('click', () => {
      tocarSom('clique');
      fechar();
    });
    document.getElementById('mxm-log-personalizar-restaurar').addEventListener('click', () => {
      tocarSom('clique');
      ocultas.clear();
      const ordemPadrao = ORDEM_PADRAO_SECOES_DETALHADO.slice();
      setConfigSecoesDetalhado(ordemPadrao, ocultas);
      reconstruirLista(ordemPadrao);
      renderPainelDetalhado();
    });
  }

  let janelaZIndexTopo = 2100000000;
  function trazerParaFrente(overlay) {
    if (!overlay) return;
    janelaZIndexTopo += 1;
    overlay.style.zIndex = janelaZIndexTopo;
  }

  function proximoZIndexFlutuante() {
    janelaZIndexTopo += 1000;
    return janelaZIndexTopo;
  }

  function animarEntradaCartao(el, opcoes) {
    if (!el || !isAnimacoesAtiva()) return;
    const distancia = (opcoes && opcoes.distancia) || 10;
    const duracao = (opcoes && opcoes.duracao) || 200;
    el.style.opacity = '0';
    el.style.transform = `scale(0.94) translateY(${distancia}px)`;
    el.style.transition = `opacity ${duracao}ms ease-out, transform ${duracao}ms cubic-bezier(.2,.8,.3,1.05)`;
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        el.style.opacity = '1';
        el.style.transform = 'scale(1) translateY(0)';
        setTimeout(() => {
          // limpa a transição/transform depois de terminar, pra não
          // interferir com o que a própria janela faz depois (ex:
          // arrastar, que usa left/top e não mexe em transform).
          el.style.transition = '';
          el.style.transform = '';
        }, duracao + 60);
      });
    });
  }

  // Efeito de saída (fade + leve zoom, indo pra baixo), espelhando
  // animarEntradaCartao acima — usado ao fechar qualquer janela/cartão
  // flutuante do script. Roda a transição e só chama `aoTerminar` (que
  // normalmente remove o overlay do DOM) depois que ela termina; se as
  // animações estiverem desligadas, chama `aoTerminar` na hora.
  function animarSaidaCartao(el, opcoes, aoTerminar) {
    if (!el || !isAnimacoesAtiva()) {
      if (aoTerminar) aoTerminar();
      return;
    }
    const distancia = (opcoes && opcoes.distancia) || 10;
    const duracao = (opcoes && opcoes.duracao) || 200;
    // Garante que a transição comece do estado "aberto" (caso o elemento
    // ainda tenha transform/transition residual de outra animação).
    el.style.transition = 'none';
    el.style.transform = 'scale(1) translateY(0)';
    el.style.opacity = '1';
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        el.style.transition = `opacity ${duracao}ms ease-in, transform ${duracao}ms ease-in`;
        el.style.opacity = '0';
        el.style.transform = `scale(0.96) translateY(${distancia}px)`;
        setTimeout(() => {
          if (aoTerminar) aoTerminar();
        }, duracao);
      });
    });
  }

  // Fecha um overlay flutuante com a animação de saída, animando o
  // elemento indicado (`elAnimado` — o cartão/painel visível dentro do
  // overlay; se omitido, usa o próprio overlay) e só removendo o overlay
  // do DOM depois. Uso: em vez de `overlay.remove()`, chamar
  // `fecharOverlayAnimado(overlay)` (ou passando o cartão/painel como
  // segundo argumento quando o overlay em si não deve encolher, só o
  // cartão dentro dele).
  function fecharOverlayAnimado(overlay, elAnimado, opcoes) {
    if (!overlay) return;
    const alvo = elAnimado || overlay.firstElementChild || overlay;
    animarSaidaCartao(alvo, opcoes, () => overlay.remove());
  }

  // Mesma coisa que fecharOverlayAnimado, mas localizando o overlay pelo
  // id — atalho pra substituir os antigos
  // `document.querySelectorAll('#id').forEach((el) => el.remove())`
  // usados como "ação de fechar" (não como limpeza de sobra antes de
  // reabrir, que continua instantânea de propósito).
  function fecharPorIdAnimado(overlayId, opcoes) {
    const overlay = document.getElementById(overlayId);
    if (!overlay) return;
    fecharOverlayAnimado(overlay, null, opcoes);
  }

  function tornarArrastavel(janela, alca, overlay) {
    if (!janela || !alca) return;

    janela.addEventListener('mousedown', () => trazerParaFrente(overlay), true);

    let arrastando = false;
    let offsetX = 0;
    let offsetY = 0;

    alca.addEventListener('mousedown', (e) => {
      if (e.button !== 0) return;
      // Não inicia o arrasto se o clique foi em algum botão/ícone
      // clicável dentro do cabeçalho (fechar, configurações, idioma,
      // detalhado, reward etc.) — senão um clique rápido nesses botões
      // vira um "arrasto" de distância zero e atrapalha o clique normal.
      if (e.target.closest('[id$="-btn"], [id$="-fechar"], [id*="-abrir-"]')) return;

      const rect = janela.getBoundingClientRect();
      janela.style.position = 'fixed';
      janela.style.left = `${rect.left}px`;
      janela.style.top = `${rect.top}px`;
      janela.style.margin = '0';

      offsetX = e.clientX - rect.left;
      offsetY = e.clientY - rect.top;
      arrastando = true;
      document.body.style.userSelect = 'none';
      e.preventDefault();
    });

    function mover(e) {
      if (!arrastando) return;
      const larguraJanela = janela.offsetWidth;
      const alturaJanela = janela.offsetHeight;
      let novoLeft = e.clientX - offsetX;
      let novoTop = e.clientY - offsetY;
      // trava dentro da área visível da tela
      novoLeft = Math.min(Math.max(0, novoLeft), Math.max(0, window.innerWidth - larguraJanela));
      novoTop = Math.min(Math.max(0, novoTop), Math.max(0, window.innerHeight - alturaJanela));
      janela.style.left = `${novoLeft}px`;
      janela.style.top = `${novoTop}px`;
    }

    function soltar() {
      if (!arrastando) return;
      arrastando = false;
      document.body.style.userSelect = '';
    }

    document.addEventListener('mousemove', mover);
    document.addEventListener('mouseup', soltar);
  }

  function obterFotoPerfilUsuario() {
    const porUrl = document.querySelector('img[src*="googleusercontent.com"]');
    if (porUrl && porUrl.src) return porUrl.src;

    const porClasse = document.querySelector('img.css-9pa8cd');
    if (porClasse && porClasse.src) return porClasse.src;

    return null;
  }

  function valorFotoPadrao() {
    const url = obterFotoPerfilUsuario();
    return url ? { url, zoomPct: 100, xPct: 50, yPct: 50 } : null;
  }

  function aplicarRecorteComFallback(elId, fallbackId, valor) {
    const el = document.getElementById(elId);
    if (!el) return;
    const fallbackEl = fallbackId ? document.getElementById(fallbackId) : null;

    if (!valor) {
      el.style.backgroundImage = '';
      el.style.display = 'none';
      if (fallbackEl) fallbackEl.style.display = 'flex';
      return;
    }

    const testeImg = new Image();
    testeImg.onload = () => {
      if (!el.isConnected) return;
      Object.assign(el.style, {
        backgroundImage: `url("${String(valor.url).replace(/"/g, '&quot;')}")`,
        backgroundRepeat: 'no-repeat',
        backgroundSize: `${valor.zoomPct}% auto`,
        backgroundPosition: `${valor.xPct}% ${valor.yPct}%`,
        display: 'block',
      });
      if (fallbackEl) fallbackEl.style.display = 'none';
    };
    testeImg.onerror = () => {
      if (!el.isConnected) return;
      el.style.backgroundImage = '';
      el.style.display = 'none';
      if (fallbackEl) fallbackEl.style.display = 'flex';
    };
    testeImg.src = valor.url;
  }

  function atualizarFotoCuratorNoPainel(valor) {
    aplicarRecorteComFallback('mxm-log-detalhado-perfil-img', 'mxm-log-detalhado-perfil-fallback', valor);
    aplicarRecorteComFallback('mxm-log-detalhado-avatar-mini-img', 'mxm-log-detalhado-avatar-mini-fallback', valor);

    // mesma foto no avatar do cabeçalho do painel principal, se
    // ele estiver aberto no momento.
    const avatarHeaderBtn = document.getElementById('mxm-log-avatar-header-btn');
    if (avatarHeaderBtn) {
      avatarHeaderBtn.innerHTML = valor
        ? `<div style="width:22px; height:22px; border-radius:50%; ${estiloFundoRecorte(valor)}"></div>`
        : `<div style="width:22px; height:22px; border-radius:50%; background:var(--md-sys-color-surface-container-high); display:flex; align-items:center; justify-content:center; color:var(--md-sys-color-on-surface-variant);">${icone(
            'user',
            13
          )}</div>`;
    }
  }

  // mesmo papel de atualizarFotoCuratorNoPainel, só que pra
  // capa/banner — não tem versão "mini" nem avatar de cabeçalho, só o
  // próprio bloco da capa no painel Detalhado.
  function atualizarCapaCuratorNoPainel(valor) {
    aplicarRecorteComFallback('mxm-log-detalhado-capa-img', null, valor);
  }

  function fecharMenuFotoCurator() {
    document.querySelectorAll('#mxm-log-foto-menu-overlay').forEach((el) => el.remove());
  }

  function abrirMenuFotoCurator(x, y, inputFotoEl) {
    fecharMenuFotoCurator();

    const temFotoCustom = !!getFotoCuratorCustom();
    const itemStyle =
      'padding:8px 10px; border-radius:var(--md-shape-sm); cursor:pointer; display:flex; align-items:center; gap:8px; white-space:nowrap;';

    const overlay = document.createElement('div');
    overlay.id = 'mxm-log-foto-menu-overlay';
    Object.assign(overlay.style, {
      position: 'fixed',
      inset: '0',
      zIndex: String(proximoZIndexFlutuante()),
    });

    const menu = document.createElement('div');
    Object.assign(menu.style, {
      position: 'fixed',
      minWidth: '210px',
      background: 'var(--md-sys-color-surface-container-low)',
      color: 'var(--md-sys-color-on-surface)',
      borderRadius: '10px',
      boxShadow: 'var(--md-elevation-3)',
      border: '1px solid var(--md-sys-color-surface-container-high)',
      fontFamily: 'sans-serif',
      fontSize: '13px',
      padding: '6px',
      left: `${x}px`,
      top: `${y}px`,
    });
    menu.innerHTML = `
      <div class="mxm-foto-opcao" data-acao="trocar" style="${itemStyle} color:var(--md-sys-color-on-surface);">${icone(
      'image',
      13
    )}<span>${t('alterarFoto')}</span></div>
      <div class="mxm-foto-opcao" data-acao="ajustar" style="${itemStyle} color:${
      temFotoCustom ? 'var(--md-sys-color-on-surface)' : 'var(--md-sys-color-outline)'
    };">${icone('zoomIn', 13)}<span>${t('ajustarRecorte')}</span></div>
      <div class="mxm-foto-opcao" data-acao="padrao" style="${itemStyle} color:${
      temFotoCustom ? 'var(--md-sys-color-on-surface)' : 'var(--md-sys-color-outline)'
    };">${icone('refresh', 13)}<span>${t('usarFotoPadrao')}</span></div>
    `;

    overlay.appendChild(menu);
    document.body.appendChild(overlay);

    const rect = menu.getBoundingClientRect();
    let left = x;
    let top = y;
    if (left + rect.width > window.innerWidth) left = window.innerWidth - rect.width - 8;
    if (top + rect.height > window.innerHeight) top = window.innerHeight - rect.height - 8;
    menu.style.left = `${Math.max(8, left)}px`;
    menu.style.top = `${Math.max(8, top)}px`;

    function fechar() {
      document.removeEventListener('keydown', aoTeclar);
      fecharMenuFotoCurator();
    }
    function aoTeclar(e) {
      if (e.key === 'Escape') fechar();
    }
    document.addEventListener('keydown', aoTeclar);

    overlay.addEventListener('click', (e) => {
      if (e.target === overlay) fechar();
    });
    overlay.addEventListener('contextmenu', (e) => {
      e.preventDefault();
      if (e.target === overlay) fechar();
    });

    menu.querySelectorAll('.mxm-foto-opcao').forEach((el) => {
      el.addEventListener('mouseenter', () => (el.style.background = 'rgba(255,255,255,0.06)'));
      el.addEventListener('mouseleave', () => (el.style.background = 'transparent'));
      el.addEventListener('click', () => {
        const acao = el.getAttribute('data-acao');
        fechar();
        if (acao === 'trocar') {
          inputFotoEl.click();
        } else if (acao === 'ajustar' && temFotoCustom) {
          abrirEditorRecorte({
            valorExistente: getFotoCuratorCustom(),
            formato: 'circulo',
            tituloTxt: t('ajustarRecorte'),
            frameLargura: 260,
            frameAltura: 260,
            aoSalvar: (valor) => {
              setFotoCuratorCustom(valor);
              atualizarFotoCuratorNoPainel(valor);
            },
          });
        } else if (acao === 'padrao' && temFotoCustom) {
          limparFotoCuratorCustom();
          atualizarFotoCuratorNoPainel(valorFotoPadrao());
          const avatarEditorEl = document.getElementById('mxm-log-detalhado-avatar-editor');
          if (avatarEditorEl) avatarEditorEl.title = t('editarFotoCurator');
        }
      });
    });
  }

